Object.assign(window.TEM8_DICTIONARY, {"housing":{"media":{"uk":"media/uk/housing__gb_1.mp3","us":"media/us/housing__us_1.mp3"},"oxford":{"phon":"ˈhaʊzɪŋ","pos":"noun","senses":[{"en":"houses, flats, etc. that people live in, especially when referring to their type, price or condition","cn":"（统称，尤指住房类型、价格、条件）住房，住宅","g":"[uncountable]","ex":{"en":"rental/student housing","cn":"租赁／学生住房"}},{"en":"the job of providing houses, flats, etc. for people to live in","cn":"住房供给","g":"[uncountable]","ex":{"en":"Tenants may only keep pets with the written consent of the housing department.","cn":"租户只有在获得住房部门书面同意的情况下才可以饲养宠物。"}},{"en":"a hard cover that protects part of a machine","cn":"（机器的）外壳，套","g":"[countable]","ex":{"en":"a car’s rear axle housing","cn":"汽车的后轴套"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"住房;住宅","en":"You refer to the buildings in which people live as housing when you are talking about their standard, price, or availability.","ex":{"en":"...a shortage of affordable housing","cn":"保障房的短缺"}},{"pos":"N-UNCOUNT 不可数名词","cn":"住房供给;住房建设","en":"Housing is the job of providing houses for people to live in.","ex":{"en":"...graduate courses in housing and public administration","cn":"住房建设和公共管理的研究生课程"}},{"pos":"N-COUNT 可数名词","cn":"（机器的）外壳，外罩，护盖","en":"A housing is a case or covering which protects parts of a machine.","ex":{"en":"Both housings are waterproof to a depth of two metres.","cn":"两个机罩的防水深度均为两米。"}}]},"examples":[{"en":"the housing market (= the activity of buying and selling houses, etc.)","cn":"住房市场"},{"en":"public/private housing","cn":"公共/私人住房"}]},"hometown":{"media":{"uk":"media/uk/hometown__gb_1.mp3","us":"media/us/hometown__us_1.mp3"},"oxford":{"phon":"ˈhəʊmtaʊn","pos":"noun","senses":[{"en":"the place where you were born or lived as a child","cn":"家乡；故乡"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"家乡;故乡","en":"Someone's hometown is the town where they live or the town that they come from.","ex":{"en":"I went to work as a painter in my hometown, Natrona Heights, Pennsylvania.","cn":"我在家乡宾夕法尼亚州的纳特罗纳海茨当了个油漆匠。"}}]}},"housework":{"media":{"uk":"media/uk/housework__gb_1.mp3","us":"media/us/housework__us_1.mp3"},"oxford":{"phon":"ˈhaʊswɜːk","pos":"noun","senses":[{"en":"the work involved in taking care of a home and family, for example cleaning and cooking","cn":"家务劳动；家务事","ex":{"en":"to do the housework","cn":"做家务"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"家务劳动","en":"Housework is the work such as cleaning, washing, and ironing that you do in your home."}]},"examples":[{"en":"to do the housework","cn":"做家务"}]},"horns":{"oxford":{"phon":"hɔːn","pos":"noun","senses":[{"en":"a hard pointed part that grows, usually in pairs, on the heads of some animals, such as sheep and cows. Horns are often curved. （","cn":"羊、牛等动物的）角"},{"en":"the hard substance of which animal horns are made","cn":"角质物"}]}},"however":{"media":{"uk":"media/uk/however__gb_1.mp3","us":"media/us/however__us_1.mp3"},"oxford":{"phon":"haʊˈevə(r)","pos":"adverb","senses":[{"en":"used to introduce a statement that contrasts with something that has just been said","cn":"然而；不过；仍然","ex":{"en":"He was feeling bad. He went to work, however, and tried to concentrate.","cn":"他感觉不舒服，但他仍然去上班，并且努力集中精神工作。"}},{"en":"used with an adjective or adverb to mean ‘to whatever degree’","cn":"（与形容词或副词连用）无论到什么程度，不管多么","ex":{"en":"He wanted to take no risks, however small.","cn":"他再小的风险也不想冒。"}},{"en":"in whatever way","cn":"不管怎样；无论如何","ex":{"en":"However you look at it, it's going to cost a lot.","cn":"不管你怎么看，它都要花很多钱。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"然而;不过;仍然","en":"You use however when you are adding a comment which is surprising or which contrasts with what has just been said.","ex":{"en":"This was not an easy decision. It is, however, a decision that we feel is dictated by our duty","cn":"这很难抉择。不过，我们觉得自己有义务作出决定。"}},{"pos":"ADV 副词","cn":"（后接形容词或副词用于强调）不管怎样，无论多么","en":"You use however before an adjective or adverb to emphasize that the degree or extent of something cannot change a situation.","ex":{"en":"You should always strive to achieve more, however well you have done before","cn":"无论之前取得何等辉煌的成就，都应该不断努力进取。"}},{"pos":"CONJ-SUBORD 连词","cn":"不管用什么方式;无论如何","en":"You use however when you want to say that it makes no difference how something is done.","ex":{"en":"However we adopt healthcare reform, it isn't going to save major amounts of money","cn":"不管我们采取何种医疗改革措施，都省不下太多钱。"}},{"pos":"ADV 副词","cn":"…左右;…上下","en":"You use however in expressions such as or however long it takes and or however many there were to indicate that the figure you have just mentioned may not be accurate.","ex":{"en":"The 20,000 or however many who come to watch would love to be out on the pitch","cn":"约两万名来看比赛的观众都希望能身处球场之上。"}},{"pos":"QUEST 疑问词","cn":"究竟怎样，到底如何（用于强调地询问令人吃惊的事情;一些人认为此用法不正确，用how ever较为妥当）","en":"You can use however to ask in an emphatic way how something has happened which you are very surprised about. Some speakers of English think that this form is incorrect and prefer to use 'how ever'.","ex":{"en":"However did you find this place in such weather?","cn":"你到底是怎样在这样的天气里找到这个地方的？"}}]},"examples":[{"en":"He was feeling bad. He went to work, however, and tried to concentrate.","cn":"他感觉不舒服，但他仍然去上班，并且努力集中精神工作。"},{"en":"We thought the figures were correct. However, we have now discovered some errors.","cn":"我们原以为这些数据正确，不过我们现在发现了一些错误。"}]},"housewife":{"media":{"uk":"media/uk/housewife__gb_1.mp3","us":"media/us/housewife__us_1.mp3"},"oxford":{"phon":"ˈhaʊswaɪf","pos":"noun","senses":[{"en":"a woman who stays at home to cook, clean, take care of the children, etc. while her husband or partner goes out to work","cn":"主妇；家庭妇女"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"家庭主妇;家庭妇女","en":"A housewife is a married woman who does not have a paid job, but instead looks after her home and children.","ex":{"en":"...a 42-year-old housewife from Brisbane.","cn":"来自布里斯班的42岁家庭主妇"}}]}},"hovering":{"oxford":{"phon":"ˈhɒvə(r)","pos":"verb","senses":[{"en":"to stay in the air in one place","cn":"翱翔；盘旋"},{"en":"to wait somewhere, especially near sb, in a shy or uncertain manner","cn":"踌躇，彷徨（尤指在某人身边）"}]}},"horseshoe":{"oxford":{"phon":"ˈhɔːsʃuː","pos":"noun","senses":[{"en":"a piece of curved iron that is attached with nails to the bottom of a horse’s foot. A horseshoe is often used as a symbol of good luck.","cn":"马蹄铁，马掌（常用来象征好运）"},{"en":"anything that is like a horseshoe in shape","cn":"马蹄铁形物","ex":{"en":"a horseshoe bend in the river","cn":"河道中的马蹄形弯曲"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"马蹄铁;马掌","en":"A horseshoe is a piece of metal shaped like a U, which is fixed with nails to the bottom of a horse's foot in order to protect it."},{"pos":"N-COUNT 可数名词","cn":"(尤指婚礼上用的）马蹄铁吉祥物","en":"A horseshoe is an object in the shape of a horseshoe which is used as a symbol of good luck, especially at a wedding."}]},"media":{"uk":"media/uk/horseshoe__gb_1.mp3","us":"media/us/horseshoe__us_1.mp3","img":["media/ldoce/img/horseshoe.jpg"]},"examples":[{"en":"a horseshoe bend in the river","cn":"河道中的马蹄形弯曲"}]},"homeward":{"media":{"uk":"media/uk/homeward__gb_1.mp3","us":"media/us/homeward__us_1.mp3"},"oxford":{"phon":"ˈhəʊmwəd","pos":"adverb","senses":[{"en":"towards home","cn":"回家的；回国的","ex":{"en":"Commuters were heading homeward at the end of the day.","cn":"一天的工作结束，上班族正赶着回家。"}},{"en":"going towards home","cn":"回家的；回国的","ex":{"en":"the homeward journey","cn":"归家的旅程"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"归家的;还乡的;回国的","en":"If you are on a homeward journey, you are on a journey towards your home.","ex":{"en":"She is ready for her homeward journey.","cn":"她准备好踏上返家之程了。"}},{"pos":"ADV 副词","cn":"向家;向家乡;向本国","en":"If you are travelling homeward or homewards, you are travelling towards your home.","ex":{"en":"John drove homeward through the lanes","cn":"约翰驱车穿过小巷向家驶去。"}}]},"examples":[{"en":"Commuters were heading homeward at the end of the day.","cn":"一天结束时下班的人们正赶着回家。"},{"en":"We drove homewards in silence.","cn":"我们默默地开车回家。"}]},"house":{"media":{"img":["media/pic/house_labels_comp.jpg","media/thumb/house.jpg"],"uk":"media/uk/house__gb_1.mp3","us":"media/us/house__us_1.mp3"},"oxford":{"phon":"haʊs","pos":"noun","senses":[{"en":"a building for people to live in, usually for one family","cn":"房屋；房子；住宅","g":"[countable]","lab":"British English","sc":"building","ex":{"en":"We live in a two-bedroom house.","cn":"我们住在一个两居室的房子里。"}},{"en":"all the people living in a house","cn":"住在一所房子里的人；全家人","g":"[singular]","sc":"building","ex":{"en":"Be quiet or you'll wake the whole house!","cn":"安静点，别把全家人都吵醒！"}},{"en":"a building used for a particular purpose, for example for holding meetings in or keeping animals or goods in","cn":"某种用途的建筑物","g":"[countable]","sc":"building","ex":{"en":"an opera house","cn":"歌剧院"}},{"en":"used in the names of office buildings","cn":"（用于办公楼名称）大厦，大楼","g":"[singular]","lab":"British English","sc":"building","ex":{"en":"Their offices are on the second floor of Chester House.","cn":"他们的办公室在切斯特大厦三楼。"}},{"en":"a company involved in a particular kind of business; an institution of a particular kind","cn":"（从事某种生意的）公司，机构","g":"[countable]","sc":"company/institution","ex":{"en":"a fashion/banking/publishing house","cn":"时装公司；银行；出版社"}},{"en":"a restaurant","cn":"餐馆；餐厅","g":"[countable]","sc":"restaurant","ex":{"en":"a steakhouse","cn":"牛排餐馆"}},{"en":"a group of people who meet to discuss and make the laws of a country","cn":"议院；议会；国会","g":"[countable]","sc":"parliament","ex":{"en":"Legislation requires approval by both houses of parliament.","cn":"立法须要得到议会两院的一致通过。"}},{"en":"the House of Commons or the House of Lords in the UK; the House of Representatives in the US","cn":"（英国）下议院，上议院；（美国）众议院","g":"[singular]","sc":"parliament"},{"en":"a group of people discussing something in a formal debate","cn":"（统称）参与辩论的人","g":"[singular]","sc":"in debate","ex":{"en":"I urge the house to vote against the motion.","cn":"我呼吁参加辩论的诸位投票反对这项动议。"}},{"en":"the part of a theatre where the audience sits; the audience at a particular performance","cn":"观众席；（统称）观众","g":"[countable]","sc":"in theatre","ex":{"en":"playing to a full/packed/empty house (= to a large/small audience)","cn":"演出座无虚席／满座／观众寥寥无几"}},{"en":"(in some British schools) an organized group of students of different ages who compete against other groups in sports competitions, etc. and who may, in boarding schools, live together in one building","cn":"（英国某些学校为进行体育比赛或按宿舍将学生分成的）社，舍","g":"[countable]","sc":"in school"},{"en":"an old and famous family","cn":"名门世家；望族","g":"[countable]","sc":"family","ex":{"en":"the House of Windsor (= the British royal family)","cn":"温莎王室"}},{"en":"a type of electronic dance music with a fast beat","cn":"货仓音乐，浩室音乐（一种快节奏电子舞曲）","g":"[uncountable]","sc":"music"},{"en":"to provide a place for a person or an animal to live","cn":"给（人或动物）提供住处","sc":"provide home","ex":{"en":"The government is committed to housing the refugees.","cn":"政府承诺收容难民。"},"pos":"verb"},{"en":"to be the place where something is kept or where something operates from","cn":"是（某物）的贮藏处（或安置处）；收藏；安置","sc":"keep something","ex":{"en":"The library houses a collection of 15 000 books.","cn":"该图书馆藏书 15 000 册。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"房屋;房子;住宅","en":"A house is a building in which people live, usually the people belonging to one family.","ex":{"en":"She has moved to a smaller house.","cn":"她已经搬进了一所小一些的房子。"}},{"pos":"N-SING 单数名词","cn":"住在一幢房子里的人;一家人","en":"You can refer to all the people who live together in a house as the house .","ex":{"en":"If he set his alarm clock for midnight, it would wake the whole house","cn":"如果他把闹钟设在午夜响，那会把全家人都吵醒的。"}},{"pos":"N-COUNT 可数名词","cn":"（用于餐饮场所的名称）餐厅，馆，屋","en":"House is used in the names of types of places where people go to eat and drink.","ex":{"en":"...a steak house.","cn":"牛排餐厅"}},{"pos":"N-COUNT 可数名词","cn":"（尤用于出版、借贷或服装设计等公司的名称）公司，商行","en":"House is used in the names of types of companies, especially ones which publish books, lend money, or design clothes.","ex":{"en":"Many of the clothes come from the world's top fashion houses","cn":"这些服装中有很多出自世界顶级时装设计公司。"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于办公楼、私宅或豪宅名称）大楼，大厦，大宅","en":"House is sometimes used in the names of office buildings and large private homes or expensive houses.","ex":{"en":"I was to go to the very top floor of Bush House in Aldwych.","cn":"我正要去奥尔德威治的布什大厦最顶层。"}},{"pos":"N-COUNT 可数名词","cn":"（英国）上（或下）议院；（美国）众议院","en":"You can refer to the two main bodies of Britain's parliament and the United States of America's legislature as the House or a House.","ex":{"en":"Some members of the House and Senate worked all day yesterday","cn":"一些众议员和参议员昨天工作了整整一天。"}},{"pos":"N-SING 单数名词","cn":"全体辩论者;所有辩手","en":"You can refer to all the people at a debate as the house .","ex":{"en":"The club is planning a public debate on 'This house believes that journalism has not gained from the introduction of new technology'.","cn":"该俱乐部拟就“我方辩手认为新闻报道并没有从新技术中获益”一题进行一次公开辩论。"}},{"pos":"N-COUNT 可数名词","cn":"（英国学校中为进行体育竞赛等所划分的）组，社","en":"In a British school, a house is a group of children of different ages who compete against other groups in sports and other activities. Each house usually has a name.","ex":{"en":"He was a prefect and house captain.","cn":"他是班长兼社长。"}},{"pos":"N-COUNT 可数名词","cn":"贵族;名门望族；（尤指）王室，王族","en":"A house is a family which has been or will be important for many generations, especially the family of a king or queen.","ex":{"en":"...the Saudi Royal House.","cn":"沙特王族"}},{"pos":"N-COUNT 可数名词","cn":"（剧场、影院或其他娱乐场所的）观众席;全体观众","en":"The house is the part of a theatre, cinema, or other place of entertainment where the audience sits. You can also refer to the audience at a particular performance as the house.","ex":{"en":"They played in front of a packed house.","cn":"他们的演出座无虚席。"}},{"pos":"ADJ 形容词","cn":"（餐馆里的葡萄酒）廉价佐餐的，未列入酒水单的","en":"A restaurant's house wine is the cheapest wine it sells, which is not listed by name on the wine list.","ex":{"en":"Tweed ordered a carafe of the house wine.","cn":"特威德点了一瓶佐餐葡萄酒。"}},{"pos":"VERB 动词","cn":"为…提供房屋（或住所）","en":"To house someone means to provide a house or flat for them to live in.","ex":{"en":"Part III of the Housing Act 1985 imposes duties on local authorities to house homeless people","cn":"1985年《住房法案》的第三部分要求地方政府为无家可归者提供住所。"}},{"pos":"VERB 动词","cn":"安置;容纳;作为…之用","en":"A building or container that houses something is the place where it is located or from where it operates.","ex":{"en":"The château itself is open to the public and houses a museum of motorcycles and cars","cn":"古堡本身对公众开放，并设有一个摩托车和汽车博物馆。"}},{"pos":"VERB 动词","cn":"（建筑物）供…居住，供…下榻","en":"If you say that a building houses a number of people, you mean that is the place where they live or where they are staying.","ex":{"en":"The building will house twelve boys and eight girls","cn":"这座房子里会住12个男孩和8个女孩。"}},{"pos":"PHRASE 短语","cn":"(人、表演或演讲）博得全场喝彩，引得哄堂大笑","en":"If a person or their performance or speech brings the house down, the audience claps, laughs, or shouts loudly because the performance or speech is very impressive or amusing.","ex":{"en":"It's really an amazing dance. It just always brings the house down.","cn":"这真是一段精彩绝伦的舞蹈表演，每次总是博得全场喝彩。"}},{"pos":"PHRASE 短语","cn":"很快就打得火热;一见如故;一拍即合","en":"If two people get on like a house on fire, they quickly become close friends, for example because they have many interests in common."},{"pos":"PHRASE 短语","cn":"（不出去工作而）操持家务，当家","en":"If you keep house, you do the cleaning and cooking for your household, and do not go out to work.","ex":{"en":"He lives with an aunt who keeps house for him.","cn":"他和一位帮他料理家务的姑妈住在一起。"}},{"pos":"PHRASE 短语","cn":"（餐馆或酒吧）免费招待的","en":"If you are given something in a restaurant or bar on the house, you do not have to pay for it.","ex":{"en":"The owner knew about the engagement and brought them glasses of champagne on the house.","cn":"店主知道了订婚一事，于是免费请他们喝香槟。"}},{"pos":"PHRASE 短语","cn":"管好自己的事;处理好自身问题","en":"If someone gets their house in order ,puts their house in order, or sets their house in order, they arrange their affairs and solve their problems.","ex":{"en":"Some think Stempel's departure will help the company get its financial house in order","cn":"有些人认为斯坦普尔的离职将有助于公司解决自身的财务问题。"}}]},"examples":[{"en":"They set up house together in a small flat in Brighton.","cn":"他们一同在布莱顿的一个小公寓里建立了家庭。"},{"en":"The gallery houses 2 000 works of modern art.","cn":"美术馆收藏了 2 000 件现代艺术作品。"}]},"hopping":{"media":{"uk":"media/uk/hopping__gb_1.mp3","us":"media/us/hopping__us_1.mp3"},"oxford":{"phon":"ˈhɒpɪŋ","pos":"adjective","senses":[{"en":"very lively or busy","cn":"很活跃的；忙忙碌碌的","ex":{"en":"The clubs in town are really hopping.","cn":"城里的俱乐部真够热闹的。"}}]},"examples":[{"en":"The clubs in town are really hopping.","cn":"城里的俱乐部真够热闹的。"}]},"holistic":{"media":{"uk":"media/uk/holistic__gb_1.mp3","us":"media/us/holistic__us_1.mp3"},"oxford":{"phon":"həˈlɪstɪk","pos":"adjective","senses":[{"en":"considering a whole thing or being to be more than a collection of parts","cn":"整体的；全面的","ex":{"en":"a holistic approach to life","cn":"对生命的全面探讨"}},{"en":"treating the whole person rather than just the symptoms (= effects) of a disease","cn":"功能整体性的","lab":"medical","ex":{"en":"holistic medicine","cn":"整体医学"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"整体论的;整体主义的","en":"Holistic means based on the principles of holism.","ex":{"en":"...practitioners of holistic medicine.","cn":"整体医学执业医师"}}]},"examples":[{"en":"a holistic approach to life","cn":"对生命的全面探讨"},{"en":"holistic medicine","cn":"整体医学"}]},"horse":{"media":{"uk":"media/uk/horse__gb_1.mp3","us":"media/us/horse__us_1.mp3"},"oxford":{"phon":"hɔːs","pos":"noun","senses":[{"en":"a large animal with four legs, a mane (= long thick hair on its neck) and a tail. Horses are used for riding on, pulling carriages, etc.","cn":"马","ex":{"en":"to ride a horse","cn":"骑马"}},{"en":"horse racing","cn":"赛马","g":"[plural]","lab":"informal","ex":{"en":"He lost a lot of money on the horses (= by gambling on races).","cn":"他赌赛马输了很多钱。"}},{"en":"a large object with legs, and sometimes handles, used in gymnastics","cn":"（体操器械）木马"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"马","en":"A horse is a large animal which people can ride. Some horses are used for pulling ploughs and carts.","ex":{"en":"A small man on a grey horse had appeared.","cn":"一个骑着灰马的小个子男人出现了。"}},{"pos":"N-PLURAL 复数名词","cn":"赛马","en":"When you talk about the horses, you mean horse races in which people bet money on the horse which they think will win.","ex":{"en":"He still likes to bet on the horses.","cn":"他仍然喜欢赌马。"}},{"pos":"N-COUNT 可数名词","cn":"（体操器械）跳马","en":"A vaulting horse is a tall piece of gymnastics equipment for jumping over."},{"pos":"PHRASE 短语","cn":"从知情人那里直接（获悉）","en":"If you hear something from the horse's mouth, you hear it from someone who knows that it is definitely true.","ex":{"en":"He has got to hear it from the horse's mouth. Then he can make a judgment as to whether his policy is correct or not.","cn":"他必须得到千真万确的信息才行。这样他才能判断自己的政策是否正确。"}},{"pos":"See also:","cn":"","en":"→see: ;"},{"pos":"","cn":"","en":"相关词组：horse around"}]},"examples":[{"en":"He lost a lot of money on the horses (= by gambling on races).","cn":"他赌赛马输了很多钱。"},{"en":"He mounted his horse and rode off.","cn":"他跨上马骑走了。"}]},"household":{"media":{"uk":"media/uk/household__gb_1.mp3","us":"media/us/household__us_1.mp3"},"oxford":{"phon":"ˈhaʊshəʊld","pos":"noun","senses":[{"en":"all the people living together in a house or flat","cn":"一家人；家庭；一户","ex":{"en":"Most households now own at least one car.","cn":"大多数家庭现在至少有一辆汽车。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"家庭;一家人;同住一幢房子的人","en":"A household is all the people in a family or group who live together in a house.","ex":{"en":"...growing up in a male-only household","cn":"在一个只有男性的家庭里长大"}},{"pos":"N-SING 单数名词","cn":"家;家务","en":"The household is your home and everything that is connected with looking after it.","ex":{"en":"My husband gave me cash to manage the household, but none of it was ever my own.","cn":"丈夫给我钱来持家，但这些钱一毫一厘都不属于我。"}},{"pos":"ADJ 形容词","cn":"家喻户晓的;众人皆知的","en":"Someone or something that is a household name or word is very well known.","ex":{"en":"Today, fashion designers are household names","cn":"今天，时装设计师是家喻户晓的人物。"}},{"pos":"ADJ 形容词","cn":"（用于王室警卫队名称中）皇家的","en":"Household is used in the names of groups of soldiers who have the job of protecting a king or queen and their family.","ex":{"en":"...the Household Cavalry Mounted Regiment.","cn":"皇家骑兵团"}}]},"examples":[{"en":"Most households now own at least one car.","cn":"大多数家庭现在至少有一辆汽车。"},{"en":"household bills/chores/goods (= connected with looking after a house and the people living in it)","cn":"家庭账单/杂务/用品"}]},"holding":{"media":{"uk":"media/uk/holding__gb_1.mp3","us":"media/us/holding__us_1.mp3"},"oxford":{"phon":"ˈhəʊldɪŋ","pos":"noun","senses":[{"en":"a number of shares that somebody has in a company","cn":"股份","ex":{"en":"She has a 40% holding in the company.","cn":"她持有公司 40% 的股份。"}},{"en":"an amount of property that is owned by a person, museum, library, etc.","cn":"私有财产；（博物馆、图书馆等的）馆藏","ex":{"en":"one of the most important private holdings of Indian art","cn":"印度艺术最重要的私人馆藏之一"}},{"en":"a piece of land that is rented by somebody and used for farming","cn":"租种的土地"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"股份","en":"If you have a holding in a company, you own shares in it.","ex":{"en":"That would increase Olympia & York's holding to 35%","cn":"那样就会使奥林匹亚约克公司的股份上升到35%。"}},{"pos":"N-COUNT 可数名词","cn":"（自有或租用的）农田，耕地","en":"A holding is an area of farm land which is owned or rented by the person who grows crops on it."},{"pos":"N-PLURAL 复数名词","cn":"（博物馆、图书馆、美术馆等的）收藏品，馆藏","en":"The holdings of a place such as a museum, library, or art gallery are the items such as books or paintings which are kept there."},{"pos":"ADJ 形容词","cn":"（活动或行动）暂时用作维持现状的","en":"A holding operation or action is a temporary one that is intended to keep a situation under control and to prevent it from becoming worse.","ex":{"en":"A garden is, at best, a holding operation against nature.","cn":"花园充其量不过是抗拒自然的一时之法。"}}]},"examples":[{"en":"one of the most important private holdings of Indian art","cn":"印度艺术最重大的私人馆藏之一。"},{"en":"She has a 40% holding in the company.","cn":"她持有公司 40% 的股份。"}]},"hood":{"media":{"img":["media/pic/hats_comp.jpg","media/thumb/hood.jpg"],"uk":"media/uk/hood__gb_1.mp3","us":"media/us/hood__us_1.mp3"},"oxford":{"phon":"hʊd","pos":"noun","senses":[{"en":"a part of a coat, etc. that you can pull up to cover the back and top of your head","cn":"风帽，兜帽（外衣的一部分，可拉起蒙住头颈）","ex":{"en":"a jacket with a detachable hood","cn":"有可拆卸风帽的夹克"}},{"en":"a piece of cloth put over somebody’s face and head so that they cannot be recognized or so that they cannot see","cn":"（布质）面罩","ex":{"en":"The detainees were led away with black hoods over their heads.","cn":"被拘留者被带走，头上蒙着黑色头巾。"}},{"en":"a piece of coloured silk or fur worn over an academic gown to show the kind of degree held by the person wearing it","cn":"学位连领帽（表示学位种类）"},{"en":"a folding cover over a car, child's buggy, etc.","cn":"（汽车、婴儿车等的）折叠式车篷","lab":"especially British English","ex":{"en":"We drove all the way with the hood down.","cn":"我们一路上敞着车篷开车。"}},{"en":"the metal part over the front of a vehicle, usually covering the engine","cn":"（车辆的）引擎盖","lab":"North American English","ex":{"en":"the sound of a bird hitting the hood of the car","cn":"鸟撞到汽车发动机罩的声音"}},{"en":"a cover placed over a device or machine, for example, to protect it","cn":"（设备或机器的）防护罩，罩","ex":{"en":"a lens hood","cn":"镜头遮光罩"}},{"en":"hoodlum (= a violent criminal, especially one who is part of a gang)","cn":"暴徒，恶棍（尤指属于某团伙者）","lab":"especially North American English, slang，，"},{"en":"a neighbourhood, especially a person’s own neighbourhood","cn":"街区；邻里；左邻右舍","lab":"especially North American English, slang，，"},{"en":"the state or quality of","cn":"状态；性质；品质","ex":{"en":"childhood","cn":"儿童时期"},"pos":"suffix"},{"en":"a group of people of the type mentioned","cn":"（某类人的）集体","ex":{"en":"the priesthood","cn":"司祭团"},"pos":"suffix"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（外衣的）风帽，兜帽","en":"A hood is a part of a coat which you can pull up to cover your head. It is in the shape of a triangular bag attached to the neck of the coat at the back."},{"pos":"N-COUNT 可数名词","cn":"面罩;头罩","en":"A hood is a bag made of cloth, which is put over someone's head and face so that they cannot be recognized or so that they cannot see."},{"pos":"N-COUNT 可数名词","cn":"（汽车的）发动机罩，引擎罩","en":"The hood of a car is the metal cover over the engine at the front."},{"pos":"N-COUNT 可数名词","cn":"折叠式车篷;（设备上的）罩，防护罩","en":"A hood is a covering on a vehicle or a piece of equipment, which is usually curved and can be removed.","ex":{"en":"Why aren't all lenses supplied with a lens hood?","cn":"为什么不给所有的镜头都配上遮光罩呢？"}},{"pos":"N-COUNT 可数名词","cn":"抽油烟机;（厨房）排气罩","en":"A cooker hood is an electrical device fitted over a cooker above head height, and containing an extractor fan and usually a light."}]},"examples":[{"en":"We drove all the way with the hood down.","cn":"我们一路上敞着车篷开车。"},{"en":"a jacket with a detachable hood","cn":"有拆除式风帽的夹克"}]},"honesty":{"media":{"uk":"media/uk/honesty__gb_1.mp3","us":"media/us/honesty__us_1.mp3"},"oxford":{"phon":"ˈɒnəsti","pos":"noun","senses":[{"en":"the quality of being honest","cn":"诚实；老实；正直","ex":{"en":"She answered all my questions with her usual honesty.","cn":"她像平常一样老老实实地回答了我的所有问题。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"诚实;正直;坦诚","en":"Honesty is the quality of being honest.","ex":{"en":"They said the greatest virtues in a politician were integrity, correctness and honesty.","cn":"他们说政治家身上最重要的美德就是正直、得体和诚实。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"银扇草;金钱花","en":"Honesty is a plant whose seeds are contained in silvery-white papery discs."}]},"examples":[{"en":"She answered all my questions with her usual honesty.","cn":"她像平常一样老老实实地回答了我的所有问题。"},{"en":"The book isn't, in all honesty, as good as I expected.","cn":"说实话，这本书并没有我预期的那么好。"}]},"hopeless":{"media":{"uk":"media/uk/hopeless__gb_1.mp3","us":"media/us/hopeless__us_1.mp3"},"oxford":{"phon":"ˈhəʊpləs","pos":"adjective","senses":[{"en":"if something is hopeless, there is no hope that it will get better or succeed","cn":"没有好转（或成功）希望的；无望的","ex":{"en":"a hopeless situation","cn":"无可挽救的局势"}},{"en":"extremely bad","cn":"极差的；糟糕透顶的","lab":"British English, informal，，","ex":{"en":"The buses are absolutely hopeless these days!","cn":"如今的公共汽车简直糟透了。"}},{"en":"very bad (at something); with no ability or skill","cn":"不能胜任的；无能的；缺乏技能的","lab":"especially British English","ex":{"en":"He's an absolutely hopeless driver.","cn":"他是一个绝对无可救药的司机。"}},{"en":"feeling or showing no hope","cn":"感到（或显得）无望的","ex":{"en":"She felt lonely and hopeless.","cn":"她感到孤独绝望。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不抱希望的;绝望的","en":"If you feel hopeless, you feel very unhappy because there seems to be no possibility of a better situation or success.","ex":{"en":"He had not heard her cry before in this uncontrolled, hopeless way","cn":"他从未听到过她如此绝望地失声痛哭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无望的;注定失败的;不会成功的","en":"Someone or something thing that is hopeless is certain to fail or be unsuccessful.","ex":{"en":"I don't believe your situation is as hopeless as you think. If you love each other, you'll work it out","cn":"我认为你们的情况并不像你想的那样无望。如果你们彼此相爱，总会找到解决办法的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）没有希望（做好…）的，不行的，无能的","en":"If someone is hopeless at something, they are very bad at it.","ex":{"en":"I'd be hopeless at working for somebody else","cn":"要是让我为别人工作，我一定做不好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"糟糕透顶的;无可救药的;极坏的","en":"You use hopeless to emphasize how bad or inadequate something or someone is.","ex":{"en":"I don't drive and the buses are quite hopeless","cn":"我不开车，公共汽车条件又太糟糕。"}}]},"examples":[{"en":"Most of the students are making good progress, but Michael is a hopeless case.","cn":"大多数学生都很有进步，唯有迈克尔不可救药。"},{"en":"‘I'll never manage it,’ he said hopelessly. “","cn":"我永远也搞不定。”他绝望地说。"}]},"honestly":{"oxford":{"phon":"ˈɒnɪstli","pos":"adverb","senses":[{"en":"in an honest way","cn":"诚实地；正当地","ex":{"en":"I can't believe he got that money honestly.","cn":"我不相信他是靠正当手段弄到那笔钱的。"}},{"en":"used to emphasize that what you are saying is true, however surprising it may seem","cn":"真的；确实","ex":{"en":"I didn't tell anyone, honestly!","cn":"我确实没告诉过任何人！"}},{"en":"used to show that you think something is bad and are annoyed by it","cn":"（表示认为某事恶劣而恼火）","lab":"informal","ex":{"en":"Honestly! Whatever will they think of next?","cn":"真是的！他们接下来还会想出什么？"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（强调信念或情感）真的，的确","en":"You use honestly to emphasize that you are referring to your, or someone else's, true beliefs or feelings.","ex":{"en":"I honestly feel I cannot do any more to prove myself","cn":"我的确感到我已经尽全力来证明我自己了。"}},{"pos":"ADV 副词","cn":"（强调所说的是事实）真的，确实","en":"You use honestly to emphasize that you are telling the truth and that you want people to believe you.","ex":{"en":"Honestly, I don't know anything about it","cn":"真的，我对此事一无所知。"}},{"pos":"ADV 副词","cn":"（表示恼怒或不耐烦）天哪，哎呀","en":"You use honestly to indicate that you are annoyed or impatient.","ex":{"en":"Honestly, Nev! Must you be quite so crude!","cn":"哎呀，内夫! 你就非得如此粗俗吗！"}}]},"media":{"uk":"media/uk/honestly__gb_1.mp3","us":"media/us/honestly__us_1.mp3"},"examples":[{"en":"I can't believe he got that money honestly.","cn":"我不相信他是靠正当手段弄到那笔钱的。"},{"en":"Honestly! Whatever will they think of next?","cn":"真是的！他们接下来还会想出什么？"}]},"housebound":{"media":{"uk":"media/uk/housebound__gb_1.mp3","us":"media/us/housebound__us_1.mp3"},"oxford":{"phon":"ˈhaʊsbaʊnd","pos":"adjective","senses":[{"en":"unable to leave your house because you cannot walk very far as a result of being ill or old","cn":"（因病或年迈）不能离家的，出不了门的"},{"en":"people who are housebound","cn":"出不了门的人","g":"[plural]"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（通常指因为生病或步行不便而）出不了门的，足不出户的","en":"Someone who is housebound is unable to go out of their house, usually because they are ill or cannot walk far.","ex":{"en":"If you are housebound, you can arrange for a home visit from a specialist adviser.","cn":"如果您不方便出门，可以安排专业顾问登门拜访。"}}]}},"honest":{"media":{"uk":"media/uk/honest__gb_1.mp3","us":"media/us/honest__us_1.mp3"},"oxford":{"phon":"ˈɒnɪst","pos":"adjective","senses":[{"en":"always telling the truth, and never stealing or cheating","cn":"诚实的；老实的；正直的","ex":{"en":"an honest man/woman","cn":"诚实的男人／女人"}},{"en":"not hiding the truth about something","cn":"坦率的；坦诚的","ex":{"en":"Are you being completely honest about your feelings?","cn":"你丝毫没有隐瞒你的感情吗？"}},{"en":"showing an honest mind or attitude","cn":"真诚的；显示内心诚意的；表示态度诚恳的","ex":{"en":"She's got an honest face.","cn":"她有一张真诚的面孔。"}},{"en":"earned or resulting from hard work","cn":"辛勤挣得的；勤劳的","ex":{"en":"He hasn't done an honest day's work in his life.","cn":"他一辈子从未努力认真干过一天活儿。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诚实的;正直的","en":"If you describe someone as honest, you mean that they always tell the truth, and do not try to deceive people or break the law.","ex":{"en":"My dad was the most honest man I ever met","cn":"爸爸是我所见过的最正直的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦诚的;直率的;不隐瞒真相的","en":"If you are honest in a particular situation, you tell the complete truth or give your sincere opinion, even if this is not very pleasant.","ex":{"en":"I was honest about what I was doing","cn":"我对自己所做的事情并无隐瞒。"}},{"pos":"ADV 副词","cn":"真的;确实","en":"You say 'honest' before or after a statement to emphasize that you are telling the truth and that you want people to believe you.","ex":{"en":"I'm not sure, honest.","cn":"我不能肯定，真的。"}},{"pos":"PHRASE 短语","cn":"（表示强调）真的，实在，千真万确","en":"Some people say 'honest to God' to emphasize their feelings or to emphasize that something is really true.","ex":{"en":"I wish we weren't doing this, Lillian, honest to God, I really do","cn":"我希望我们没有在干这事，莉莲，真的，我真这么想。"}},{"pos":"PHRASE 短语","cn":"老实说;说实在的","en":"You can say 'to be honest' before or after a statement to indicate that you are telling the truth about your own opinions or feelings, especially if you think these will disappoint the person you are talking to.","ex":{"en":"To be honest the house is not quite our style","cn":"说实话，这所房子不太适合我们。"}}]},"examples":[{"en":"Let's be honest, she's only interested in Mike because of his money.","cn":"坦率地说吧，她对迈克有好感只不过是因为他有钱。"},{"en":"To be frank with you, I think your son has little chance of passing the exam.","cn":"坦白说，我认为你的儿子不大可能通过考试。"}]},"horizontal":{"oxford":{"phon":"ˌhɒrɪˈzɒntl","pos":"adjective","senses":[{"en":"flat and level; going across and parallel to the ground rather than going up and down","cn":"水平的；与地面平行的；横的","lab":"informal","ex":{"en":"horizontal lines","cn":"横线"}},{"en":"a horizontal position","cn":"水平位置","g":"[uncountable]","ex":{"en":"He shifted his position from the horizontal.","cn":"他从水平姿势变换成其他姿势。"},"pos":"noun"},{"en":"a horizontal line or surface","cn":"水平线；水平面；横线；横切面","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"水平的;横的","en":"Something that is horizontal is flat and level with the ground, rather than at an angle to it.","ex":{"en":"The board consists of vertical and horizontal lines","cn":"板上画着横纵的线条。"}},{"pos":"N-COUNT 可数名词","cn":"水平线;横线;水平结构","en":"A horizontal is a line or structure that is horizontal.","ex":{"en":"The undulating planes of the countryside provide relief from the hard horizontals and verticals of the urban scene.","cn":"乡村起伏不平的地势使人们摆脱了城市刻板的横平竖直景象。"}}]},"media":{"uk":"media/uk/horizontal__gb_1.mp3","us":"media/us/horizontal__us_1.mp3"},"examples":[{"en":"Cut the cake in half horizontally and spread jam on one half.","cn":"把蛋糕横切成两半，把果酱涂在半面上。"},{"en":"He shifted his position from the horizontal.","cn":"他从水平姿势变换成其他姿势。"}]},"homeworkers":{"oxford":{"phon":"ˈhəʊmwɜːkə(r)","pos":"noun","senses":[{"en":"a person who works at home, often doing jobs that are not well paid such as making clothes for shops/stores","cn":"在家工作的人（常做报酬低微的工作）"}]}},"honour":{"media":{"uk":"media/uk/honour__gb_1.mp3","us":"media/us/honour__us_1.mp3"},"oxford":{"phon":"ˈɒnə(r)","pos":"noun","senses":[{"en":"great respect for somebody","cn":"尊敬；尊重；崇敬","g":"[uncountable]","sc":"respect","ex":{"en":"the guest of honour (= the most important one)","cn":"贵宾"}},{"en":"something that you are very pleased or proud to do because people are showing you great respect","cn":"荣幸；光荣","g":"[singular]","sc":"privilege","ex":{"en":"It was a great honour to be invited here today.","cn":"今天承蒙邀请到此，深感荣幸。"}},{"en":"the quality of knowing and doing what is morally right","cn":"正义感；道义；节操","g":"[uncountable]","sc":"moral behaviour","ex":{"en":"a man of honour","cn":"品德高尚的人"}},{"en":"a good reputation; respect from other people","cn":"荣誉；名誉；他人的尊敬","g":"[uncountable]","sc":"reputation","ex":{"en":"upholding the honour of your country","cn":"捍卫祖国的荣誉"}},{"en":"a person or thing that causes others to respect and admire something/somebody","cn":"引起尊敬（或尊重、崇敬）的人（或事物）","g":"[singular]","sc":"reputation","ex":{"en":"She is an honour to the profession.","cn":"她是这一行业的光荣。"}},{"en":"an award, official title, etc. given to somebody as a reward for something that they have done","cn":"（为表扬某人的）奖励，荣誉称号，头衔","g":"[countable]","sc":"award","ex":{"en":"the New Year’s Honours list (= in Britain, a list of awards and titles given on January 1 each year)","cn":"（英国）元旦受勋者名册"}},{"en":"a university course that is of a higher level than a basic course (in the US also used to describe a class in school that is at a higher level than other classes)","cn":"大学荣誉学位课程；（美国学校的）优等班","g":"[plural]","lab":"North American English","sc":"at university/school","ex":{"en":"an honours degree/course","cn":"荣誉学位／课程"}},{"en":"if you pass an exam or graduate from a university or school with honours, you receive a special grade for having achieved a very high standard","cn":"优异成绩","g":"[plural]","sc":"at university/school","ex":{"en":"He passed with second-class honours.","cn":"他以二级优等成绩通过了考试。"}},{"en":"a title of respect used when talking to or about a judge or a US mayor","cn":"法官大人；（美国）市长阁下","g":"[countable]","sc":"judge/mayor","ex":{"en":"No more questions, Your Honour.","cn":"没有其他问题了，法官大人。"}},{"en":"the cards that have the highest value","cn":"最大点数的牌","g":"[countable, usually plural]","sc":"in card games"},{"en":"to do something that shows great respect for somebody/something","cn":"尊敬，尊重（某人）","lab":"ironic","sc":"show respect","ex":{"en":"our honoured guests","cn":"我们的贵宾"},"pos":"verb"},{"en":"to give public praise, an award or a title to somebody for something they have done","cn":"给予表扬（或奖励、头衔、称号）","g":"[often passive]","sc":"give award","ex":{"en":"She has never been properly honoured in her own country.","cn":"她在自己的国家从未受到过适当的荣誉。"},"pos":"verb"},{"en":"to do what you have agreed or promised to do","cn":"信守，执行（承诺）","lab":"formal","sc":"keep promise","ex":{"en":"I have every intention of honouring our contract.","cn":"我完全愿意执行我们的合约。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"正义感;道义;气节","en":"Honour means doing what you believe to be right and being confident that you have done what is right.","ex":{"en":"The officers died faithful to Poland and to the honour of a soldier","cn":"这些军官至死都忠于波兰，坚守了军人气节。"}},{"pos":"N-COUNT 可数名词","cn":"荣誉;特殊奖励","en":"An honour is a special award that is given to someone, usually because they have done something good or because they are greatly respected.","ex":{"en":"Most of the high honours usually go to long-serving MPs loyal to the government","cn":"大多数的高级荣誉通常都会授予忠于政府的资深议员。"}},{"pos":"VERB 动词","cn":"授予…荣誉;给予…表彰","en":"If someone is honoured, they are given public praise or an award for something they have done.","ex":{"en":"Two American surgeons were last week honoured with the Nobel Prize for Medicine and Physiology","cn":"两位美国外科医生上周获得了诺贝尔医学和生理学奖。"}},{"pos":"N-SING 单数名词","cn":"荣幸;光荣;殊荣","en":"If you describe doing or experiencing something as an honour, you mean you think it is something special and desirable.","ex":{"en":"Five other cities had been competing for the honour of staging the Games","cn":"还有其他5个城市为赢得该届运动会的主办权一直在进行角逐。"}},{"pos":"V-PASSIVE 被动动词","cn":"使感到荣幸;使引以为荣","en":"If you say that you would be honoured to do something, you are saying very politely and formally that you would be pleased to do it. If you say that you are honoured by something, you are saying that you are grateful for it and pleased about it.","ex":{"en":"Peter Alliss says he would be honoured to be asked","cn":"彼得·艾利斯说若受邀约自己将感到非常荣幸。"}},{"pos":"VERB 动词","cn":"尊重;尊敬","en":"To honour someone means to treat them or regard them with special attention and respect.","ex":{"en":"Her Majesty later honoured the Headmaster with her presence at lunch","cn":"女王陛下随后出席了午宴，以表示对校长的尊重。"}},{"pos":"VERB 动词","cn":"执行（协议）;履行（诺言）","en":"If you honour an arrangement or promise, you do what you said you would do.","ex":{"en":"The two sides agreed to honour a new ceasefire","cn":"双方同意执行新的停火协议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（大学）优等学位，荣誉学位","en":"Honours is a type of university degree which is of a higher standard than a pass or ordinary degree.","ex":{"en":"...an honours degree in business studies.","cn":"商学荣誉学位"}},{"pos":"N-VOC 称呼名词","cn":"（美国对法官、市长等的尊称）阁下，大人（当面称呼时用 your honour，其他场合提及时用 his honour 或 her honour）","en":"Judges, and mayors in the United States, are sometimes called your honour or referred to as his honour or her honour .","ex":{"en":"I bring this up, your honor, because I think it is important to understand the background of the defendant.","cn":"法官大人，我之所以提及此事，是因为我觉得了解被告的背景十分重要。"}},{"pos":"PHRASE 短语","cn":"尽主人之谊;主持","en":"If someone does the honours at a social occasion or public event, they act as host or perform some official function.","ex":{"en":"A well-known television personality did the honours at the official opening of the show.","cn":"一位著名的电视明星主持了该次展览的正式开幕典礼。"}},{"pos":"PREP-PHRASE 短语介词","cn":"为庆祝…","en":"If something is arranged in honour of a particular event, it is arranged in order to celebrate that event.","ex":{"en":"The Foundation is holding a dinner at the Museum of American Art in honour of the opening of their new show.","cn":"该基金会将在美国艺术博物馆举办宴会，庆祝新展览的开幕。"}},{"pos":"PHRASE 短语","cn":"为了向…表示敬意","en":"If something is arranged or happens in someone's honour, it is done specially to show appreciation of them.","ex":{"en":"He will attend an outdoor concert in his honour in the centre of Paris","cn":"他将出席在巴黎市中心特地为他举办的一场露天音乐会。"}}]},"examples":[{"en":"Proving his innocence has become a matter of honour.","cn":"证实他的清白已经成了一件道义上的事。"},{"en":"You're on your honour not to go into my room.","cn":"依你的人格，相信你不会进我的房间。"}]},"hospital":{"media":{"uk":"media/uk/hospital__gb_1.mp3","us":"media/us/hospital__us_1.mp3"},"oxford":{"phon":"ˈhɒspɪtl","pos":"noun","senses":[{"en":"a large building where people who are ill or injured are given medical treatment and care","cn":"医院","lab":"British English","ex":{"en":"He had to go to/into hospital for treatment.","cn":"他得到医院接受治疗。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"医院","en":"A hospital is a place where people who are ill are looked after by nurses and doctors.","ex":{"en":"...a children's hospital with 120 beds","cn":"拥有120张病床的儿童医院"}}]},"examples":[{"en":"The injured were rushed to (the) hospital in an ambulance.","cn":"救护车把伤员火速送往医院。"},{"en":"I'm going to the hospital to visit my brother.","cn":"我要去医院探望我弟弟。"}]},"how":{"media":{"uk":"media/uk/how__gb_1.mp3","us":"media/us/how__us_1.mp3"},"oxford":{"phon":"haʊ","pos":"adverb","senses":[{"en":"in what way or manner","cn":"怎样；如何","ex":{"en":"How does it work?","cn":"它是如何运作的？"}},{"en":"used to ask about somebody’s health or how well things are going for them","cn":"（询问某人健康状况或近况）","lab":"informal","ex":{"en":"How are you?","cn":"你（身体）好吗？"}},{"en":"used to ask whether something is successful or fun","cn":"（询问是否顺利或愉快）","ex":{"en":"How was your trip?","cn":"你旅行愉快吗？"}},{"en":"used before an adjective or adverb to ask about the amount, degree, etc. of something, or about somebody’s age","cn":"（后接形容词或副词）多少，多么，多大","ex":{"en":"How often do you go swimming?","cn":"你多久去游一次泳？"}},{"en":"used to express surprise, pleasure, etc.","cn":"（表示惊奇、高兴等）","ex":{"en":"How kind of you to help!","cn":"你来帮忙，真是太好了！"}},{"en":"in any way in which","cn":"以任何方式；无论用什么方法","ex":{"en":"I'll dress how I like in my own house!","cn":"我在自己家里爱怎么穿就怎么穿！"}}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"（用于询问方式、方法）怎样，怎么，如何","en":"You use how to ask about the way in which something happens or is done.","ex":{"en":"How do I make payments into my account?","cn":"我如何向自己的账户付款？"}},{"pos":"CONJ-SUBORD 连词","cn":"（用于某些形容词和动词后引出陈述或事实，常指记起之事或希望他人了解之事）","en":"You use how after certain adjectives and verbs to introduce a statement or fact, often something that you remember or expect other people to know about.","ex":{"en":"It's amazing how people collect so much stuff over the years","cn":"人们竟然日积月累地收集了这么多东西，真令人惊叹。"}},{"pos":"QUEST 疑问词","cn":"（用于询问数量、程度）多少，多么","en":"You use how to ask questions about the quantity or degree of something.","ex":{"en":"How much money are we talking about?","cn":"总共是多少钱？"}},{"pos":"QUEST 疑问词","cn":"（用于询问是否成功或愉快）怎么样，如何","en":"You use how when you are asking someone whether something was successful or enjoyable.","ex":{"en":"How was your trip down to Orlando?","cn":"你的奥兰多之行怎么样？"}},{"pos":"QUEST 疑问词","cn":"（用于询问某人的健康或打探有关某人的消息）怎么样，如何","en":"You use how to ask about someone's health or to find out someone's news.","ex":{"en":"Hi! How are you doing?","cn":"嗨！你近来怎么样？"}},{"pos":"CONVENTION 惯用语","cn":"你好（用于初次见面打招呼）","en":"'How do you do' is a polite way of greeting someone when you meet them for the first time.","ex":{"en":"'How do you do, Mrs Bellingham,' Sam said.","cn":"“你好，贝林厄姆夫人，”萨姆说。"}},{"pos":"CONJ-SUBORD 连词","cn":"不管如何;无论怎样","en":"You use how when you want to say that it does not matter which way something is done.","ex":{"en":"Two historical questions — you can answer them how you like","cn":"两个历史问题——你可以随便回答。"}},{"pos":"ADV 副词","cn":"（强调程度）多么，何等，如此","en":"You use how to emphasize the degree to which something is true.","ex":{"en":"I didn't realize how heavy that shopping was going to be","cn":"我没想到买的东西会有多沉。"}},{"pos":"ADV 副词","cn":"（用于感叹句中强调形容词、副词或陈述内容）多么，何等，如此","en":"You use how in exclamations to emphasize an adjective, adverb, or statement.","ex":{"en":"How strange that something so simple as a walk on the beach could suddenly mean so much","cn":"诸如在沙滩散步这样的小事会突然变得如此重要，真是令人感到不可思议。"}},{"pos":"QUEST 疑问词","cn":"（表示不赞成或难以相信）你怎么能，你怎么会","en":"You use how in expressions such as 'How can you...' and 'How could you...' to indicate that you disapprove of what someone has done or that you find it hard to believe.","ex":{"en":"How can you drink so much beer, Luke?","cn":"你怎么能喝这么多啤酒呢，卢克？"}},{"pos":"QUEST 疑问词","cn":"（用于提出建议或邀请）怎么样好吗","en":"You use how in expressions such as 'how about...' or 'how would you like...' when you are making an offer or a suggestion.","ex":{"en":"How about a cup of coffee?","cn":"来杯咖啡怎么样？"}},{"pos":"CONVENTION 惯用语","cn":"（用于询问对方的想法或要求）你呢，你觉得呢","en":"If you ask someone 'How about you?' you are asking them what they think or want.","ex":{"en":"Well, I enjoyed that. How about you two?","cn":"嗯，我觉得那很棒。你们俩呢？"}},{"pos":"CONVENTION 惯用语","cn":"（用于引起他人对刚说过的话或发生的事的注意）神吧，奇妙吧，你信吗？","en":"If you say 'How about that?' you are drawing attention to something that has been said or done that you think is surprising.","ex":{"en":"The twins made their appearance at three o'clock. How about that? Spot on time.","cn":"双胞胎在3点时出现了。神吧？绝对准时。"}},{"pos":"PHRASE 短语","cn":"（用于引出相关的新话题）怎么样，如何","en":"You use how about to introduce a new subject which you think is relevant to the conversation you have been having.","ex":{"en":"Are your products and services competitive? How about marketing?","cn":"你们的产品和服务有竞争力吗？营销又怎么样呢？"}},{"pos":"PHRASE 短语","cn":"（用于因为惊讶而询问）怎么会这样呢，为什么","en":"You ask 'How come?' or 'How so?' when you are surprised by something and are asking why it happened or was said.","ex":{"en":"'They don't say a single word to each other.'—'How come?'","cn":"“他们相互之间一句话都不说。”——“怎么会这样呢？”"}},{"pos":"PHRASE 短语","cn":"你是什么意思;你到底想说什么","en":"If you say 'How do you mean?' to someone, you are asking them to explain or give more details of what they have just said.","ex":{"en":"'The fuel gauge is broken.' — 'Broken? How do you mean?'","cn":"“燃油表坏了。”——“坏了？你说清楚点？”"}},{"pos":"PHRASE 短语","cn":"（用于询问是否可接受或满意）怎么样，行吗","en":"If you say 'How's that?' to someone, you are asking whether something is acceptable or satisfactory.","ex":{"en":"Suppose we meet somewhere for a drink? I'll pay. How's that?","cn":"我们找个地方一起喝一杯吧？我请客。怎么样？"}}]},"examples":[{"en":"I'll tuck your sheets in for you. How's that? Comfortable?","cn":"我给你把被单掖在垫褥下面吧。怎么样？舒服吗？"},{"en":"Ben! How could you? After all they've done for us!","cn":"本！他们为我们做了这么多，你怎么能这样！"}]},"hollow":{"media":{"uk":"media/uk/hollow__gb_1.mp3","us":"media/us/hollow__us_1.mp3"},"oxford":{"phon":"ˈhɒləʊ","pos":"adjective","senses":[{"en":"having a hole or empty space inside","cn":"中空的；空心的","ex":{"en":"a hollow ball/centre/tube/tree","cn":"中空的球／中心部位／管子／树"}},{"en":"sinking deeply into the face","cn":"凹陷的","ex":{"en":"hollow eyes/cheeks","cn":"凹陷的双眼／双颊"}},{"en":"making a low sound like that made by an empty object when it is hit","cn":"沉闷回荡的；空响的","g":"[usually before noun]","ex":{"en":"a hollow groan","cn":"低沉的呻吟"}},{"en":"not sincere","cn":"无诚意的；虚伪的","g":"[usually before noun]","ex":{"en":"I've had enough of their hollow promises.","cn":"我已经受够了他们的空头支票。"}},{"en":"without real value","cn":"无真正价值的","g":"[usually before noun]","ex":{"en":"He won something of a hollow victory when his opponent was forced to withdraw with a serious injury.","cn":"当他的对手因重伤被迫退出时，他赢得了一场空洞的胜利。"}},{"en":"an area that is lower than the surface around it, especially on the ground","cn":"凹陷处；坑洼处","ex":{"en":"All but one of the ponds are empty, their sites marked only by muddy hollows.","cn":"除了其中一个池塘外，所有池塘都是空的，只有泥泞的洼地。"},"pos":"noun"},{"en":"a hole or an empty space inside something","cn":"洞；坑","ex":{"en":"The squirrel disappeared into a hollow at the base of the tree.","cn":"松鼠钻进了树根处的一个洞。"},"pos":"noun"},{"en":"to make a flat surface go inward in a curve","cn":"使凹陷；使塌陷","ex":{"en":"The stairs have been hollowed by centuries of use.","cn":"历经几个世纪的使用，楼梯都塌陷下去了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"空的;空心的;中空的","en":"Something that is hollow has a space inside it, as opposed to being solid all the way through.","ex":{"en":"...a hollow tree.","cn":"空心的树"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"凹的;凹陷的","en":"A surface that is hollow curves inwards.","ex":{"en":"He looked young, dark and sharp-featured, with hollow cheeks.","cn":"他看起来很年轻，肤色黝黑，五官分明，双颊凹陷。"}},{"pos":"N-COUNT 可数名词","cn":"树洞","en":"A hollow is a hole inside a tree.","ex":{"en":"I made my home there, in the hollow of a dying elm.","cn":"我在一棵快要枯死的榆树的树洞里安了家。"}},{"pos":"N-COUNT 可数名词","cn":"凹陷处;低洼地","en":"A hollow is an area that is lower than the surrounding surface.","ex":{"en":"Below him the town lay warm in the hollow of the hill.","cn":"在他下方，小镇卧在温暖的山谷里。"}},{"pos":"ADJ 形容词","cn":"空洞的;无用的;无价值的","en":"If you describe a statement, situation, or person as hollow, you mean they have no real value, worth, or effectiveness.","ex":{"en":"Any threat to bring in the police is a hollow one.","cn":"任何威胁说要叫警察来的话都是虚声恫吓。"}},{"pos":"ADJ 形容词","cn":"（笑声等）虚伪的，不真诚的","en":"If someone gives a hollow laugh, they laugh in a way that shows that they do not really find something amusing.","ex":{"en":"Murray Pick's hollow laugh had no mirth in it.","cn":"默里·皮克的干笑里没有一点快乐。"}},{"pos":"ADJ 形容词","cn":"（声音）空洞的，沉闷回荡的","en":"A hollow sound is dull and echoing.","ex":{"en":"...the hollow sound of a gunshot.","cn":"空洞的枪响"}},{"pos":"VERB 动词","cn":"使凹陷;使下陷","en":"If something is hollowed, its surface is made to curve inwards or downwards.","ex":{"en":"The mule's back was hollowed by the weight of its burden.","cn":"骡背被重负压得塌下了。"}},{"pos":"","cn":"","en":"相关词组：hollow out"}]},"examples":[{"en":"Their appeals for an end to the violence had a hollow ring.","cn":"他们要求停止使用暴力的呼吁并不真切。"},{"en":"The village lay secluded in a hollow of the hills (= a small valley).","cn":"村子坐落在一个幽静的小山谷中。"}]},"hostel":{"oxford":{"phon":"ˈhɒstl","pos":"noun","senses":[{"en":"a building that provides cheap accommodation and sometimes meals to students, workers or travellers","cn":"宿舍，招待所（提供廉价住宿，有时还提供餐食）","ex":{"en":"We stayed at a student hostel during the conference.","cn":"会议期间我们住在一处学生公寓里。"}},{"en":"a building, usually run by a charity, where people who have no home can stay for a short time","cn":"临时收容所；慈善收容所","lab":"British English","ex":{"en":"He lives in a hostel for homeless people.","cn":"他住在一家为无家可归者提供的旅馆里。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常由当地政府或慈善团体开办的）廉价招待所，临时收容所","en":"A hostel is a large house where people can stay cheaply for a short period of time. Hostels are usually owned by local government authorities or charities."}]},"media":{"uk":"media/uk/hostel__gb_1.mp3","us":"media/us/hostel__us_1.mp3"},"examples":[{"en":"a hostel for the homeless","cn":"流浪者之家"}]},"hooves":{"media":{"uk":"media/uk/hooves__gb_1.mp3","us":"media/us/hooves__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"（hoof 的复数）","en":"Hooves is a plural of hoof."}]}},"homework":{"oxford":{"phon":"ˈhəʊmwɜːk","pos":"noun","senses":[{"en":"work that is given by teachers for students to do at home","cn":"（学生的）家庭作业","lab":"especially North American English","ex":{"en":"I always do my homework on the bus.","cn":"我总是在公共汽车上做作业。"}},{"en":"work that somebody does to prepare for something","cn":"准备工作","lab":"informal","ex":{"en":"You could tell that he had really done his homework (= found out all he needed to know).","cn":"你能看得出他确实做好了充分准备。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（学生的）家庭作业","en":"Homework is school work that teachers give to pupils to do at home in the evening or at the weekend.","ex":{"en":"Have you done your homework, Gemma?","cn":"杰玛，你做完家庭作业了吗？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"必要的准备工作","en":"If you do your homework, you find out what you need to know in preparation for something.","ex":{"en":"Before you go near a stockbroker, do your homework.","cn":"找股票经纪人之前，先要做好必要的准备工作。"}}]},"media":{"uk":"media/uk/homework__gb_1.mp3","us":"media/us/homework__us_1.mp3"},"examples":[{"en":"You could tell that he had really done his homework (= found out all he needed to know).","cn":"你能看得出他确实做了充分准备。"},{"en":"I still haven't done my geography homework.","cn":"我还没做完地理科家庭作业呢。"}]},"hour":{"media":{"uk":"media/uk/hour__gb_1.mp3","us":"media/us/hour__us_1.mp3"},"oxford":{"phon":"ˈaʊə(r)","pos":"noun","senses":[{"en":"60 minutes; one of the 24 parts that a day is divided into","cn":"小时","g":"[countable]","ex":{"en":"I spent an hour on the phone.","cn":"我打了一个小时电话。"}},{"en":"a period of about an hour, used for a particular purpose","cn":"约一小时的时间","g":"[countable, usually singular]","ex":{"en":"I spent my lunch hour shopping.","cn":"我用午餐时间去购物了。"}},{"en":"a fixed period of time during which people work, an office is open, etc.","cn":"（工作、办公等的）固定时间","g":"[plural]","ex":{"en":"Opening hours are from 10 to 6 each day.","cn":"营业时间为每天 10 点到 6 点。"}},{"en":"a long time","cn":"很长时间","g":"[plural]","ex":{"en":"It took hours getting there.","cn":"花了好长时间才到那里。"}},{"en":"a particular point in time","cn":"某一时刻","g":"[singular]","ex":{"en":"You can't turn him away at this hour of the night.","cn":"天这么晚了，你不能把他赶走。"}},{"en":"the time when something important happens","cn":"重要时刻","g":"[countable, usually singular]","ex":{"en":"This was often thought of as the country's finest hour.","cn":"一般认为这是该国最美好的一段时光。"}},{"en":"the time when it is exactly 1 o’clock, 2 o’clock, etc.","cn":"整点","g":"[singular]","ex":{"en":"The clock struck the hour.","cn":"钟敲过整点了。"}},{"en":"used when giving the time according to the 24-hour clock, usually in military or other official language","cn":"（按 24 小时制给出的时间，通常用于军事或其他官方用语）点钟","g":"[plural]","ex":{"en":"The first missile was launched at 2300 hours (= at 11 p.m.).","cn":"首枚导弹是在 23 点（晚上 11 点）发射的。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小时","en":"An hour is a period of sixty minutes.","ex":{"en":"They waited for about two hours","cn":"他们等了约两小时。"}},{"pos":"N-PLURAL 复数名词","cn":"长时间","en":"People say that something takes or lasts hours to emphasize that it takes or lasts a very long time, or what seems like a very long time.","ex":{"en":"Getting there would take hours.","cn":"去那里要花很长时间。"}},{"pos":"N-SING 单数名词","cn":"（时钟的）钟点，整点","en":"A clock that strikes the hour strikes when it is exactly one o'clock, two o'clock, and so on."},{"pos":"N-SING 单数名词","cn":"时间;时刻","en":"You can refer to a particular time or moment as a particular hour .","ex":{"en":"...the hour of his execution","cn":"处决他的时间"}},{"pos":"N-COUNT 可数名词","cn":"（人一生中的某个）时候，时期","en":"If you refer, for example, to someone's hour of need or hour of happiness, you are referring to the time in their life when they are or were experiencing that condition or feeling.","ex":{"en":"He recalled her devotion to her husband during his hour of need.","cn":"他回忆起她在丈夫困难之时的忠贞奉献。"}},{"pos":"N-PLURAL 复数名词","cn":"（每天发生或进行某事的）特定时间，固定时间","en":"You can refer to the period of time during which something happens or operates each day as the hours during which it happens or operates.","ex":{"en":"...the hours of darkness","cn":"夜晚"}},{"pos":"N-PLURAL 复数名词","cn":"（每周的）工作时间","en":"If you refer to the hours involved in a job, you are talking about how long you spend each week doing it and when you do it.","ex":{"en":"I worked quite irregular hours","cn":"我的工作时间相当不固定。"}},{"pos":"","cn":"","en":"→see: ; →see: ; →see: ;"},{"pos":"PHRASE 短语","cn":"下班后;营业（或办公、学习）时间以后","en":"If you do something after hours, you do it outside normal business hours or the time when you are usually at work.","ex":{"en":"...a local restaurant where steel workers unwind after hours","cn":"钢厂工人下班后去放松一下的当地餐馆"}},{"pos":"PHRASE 短语","cn":"在（某一时段的）任何时刻","en":"If you say that something happens at all hours of the day or night, you disapprove of it happening at the time that it does or as often as it does.","ex":{"en":"She didn't want her fourteen-year-old daughter coming home at all hours of the morning.","cn":"她不希望自己14岁的女儿凌晨才回家。"}},{"pos":"PHRASE 短语","cn":"在凌晨;在下半夜","en":"If something happens in the early hours or in the small hours, it happens in the early morning after midnight.","ex":{"en":"Gibbs was arrested in the early hours of yesterday morning.","cn":"吉布斯于昨天凌晨被捕。"}},{"pos":"PHRASE 短语","cn":"长时间地;不停地","en":"If you say that someone does something hour after hour, you are emphasizing that they do it continually for a long time.","ex":{"en":"He and my mom were arguing every night, hour after hour.","cn":"他和我妈妈每天晚上都吵个不停。"}},{"pos":"PHRASE 短语","cn":"整点地","en":"If something happens on the hour, it happens every hour at, for example, nine o'clock, ten o'clock, and so on, and not at any number of minutes past an hour."},{"pos":"PHRASE 短语","cn":"整点差…分/ 整点过…分","en":"If you want to state the time exactly, you can give a number of minutes followed by before the hour or past the hour ."},{"pos":"PHRASE 短语","cn":"在通常营业（或工作、学习）时间之外","en":"Something that happens out of hours happens at a time that is not during the usual hours of business or work.","ex":{"en":"Teachers refused to run out of hours sports matches because they weren't being paid.","cn":"教师拒绝课余安排体育比赛，因为他们不会获得薪酬。"}}]},"examples":[{"en":"The first missile was launched at 2300 hours (= at 11 p.m.).","cn":"首枚导弹是在 23 点（晚上 11 点）发射的。"},{"en":"This is the only place to get a drink after hours (= after the normal closing time for pubs).","cn":"这是酒吧正常关门时间之后唯一能喝一杯的地方。"}]},"horizon":{"media":{"uk":"media/uk/horizon__gb_1.mp3","us":"media/us/horizon__us_1.mp3"},"oxford":{"phon":"həˈraɪzn","pos":"noun","senses":[{"en":"the furthest that you can see, where the sky seems to meet the land or the sea","cn":"地平线；海平线","g":"[singular]","ex":{"en":"The sun sank below the horizon.","cn":"太阳落到了地平线下。"}},{"en":"the limit of your desires, knowledge or interests","cn":"（欲望、知识或兴趣的）范围，眼界","g":"[countable, usually plural]","ex":{"en":"She wanted to travel to broaden her horizons.","cn":"她想旅行，以开阔眼界。"}},{"en":"a television documentary series which is broadcast in Britain, on BBC Two. It started in 1964 and includes programmes on different topics in the areas of science, nature, medicine and natural history.","cn":"地平线：在英国播出的电视纪录片系列，在BBC第二电视台上播出。它始于1964年，包括有关科学，自然，医学和自然历史领域不同主题的课程。","pos":""}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"地平线","en":"The horizon is the line in the far distance where the sky seems to meet the land or the sea.","ex":{"en":"A grey smudge appeared on the horizon. That must be Calais, thought Fay","cn":"一个模糊的灰影出现在地平线上。那里一定是加来，法伊心想。"}},{"pos":"N-COUNT 可数名词","cn":"范围;眼界;见识","en":"Your horizons are the limits of what you want to do or of what you are interested or involved in.","ex":{"en":"As your horizons expand, these new ideas can give a whole new meaning to life","cn":"随着眼界不断开阔，这些新观念会为生活赋予全新的意义。"}},{"pos":"PHRASE 短语","cn":"已露端倪的;即将发生的","en":"If something is on the horizon, it is almost certainly going to happen or be done quite soon.","ex":{"en":"With breast cancer, as with many common diseases, there is no obvious breakthrough on the horizon","cn":"对乳腺癌等很多常见疾病来说，目前还看不到有明显的突破。"}}]},"examples":[{"en":"The company needs new horizons now.","cn":"公司现在需要开拓新的领域。"},{"en":"A ship appeared on the horizon.","cn":"一艘船出现在地平线上。"}]},"host":{"media":{"uk":"media/uk/host__gb_1.mp3","us":"media/us/host__us_1.mp3"},"oxford":{"phon":"həʊst","pos":"noun","senses":[{"en":"a person who invites guests to a meal, a party, etc. or who has people staying at their house","cn":"主人","g":"[countable]","ex":{"en":"Ian, our host, introduced us to the other guests.","cn":"主人伊恩把我们介绍给了其他客人。"}},{"en":"a country, a city or an organization that holds and arranges a special event","cn":"东道主；主办国（或城市、机构）","g":"[countable]","ex":{"en":"the host nation/country/city","cn":"主办国／城市"}},{"en":"a person who introduces a television or radio show, and talks to guests","cn":"（电视或广播的）节目主持人","g":"[countable]","ex":{"en":"a radio/TV host","cn":"广播／电视节目主持人"}},{"en":"an animal or a plant on which another animal or plant lives and feeds","cn":"（寄生动植物的）宿主，寄主","g":"[countable]","lab":"specialist"},{"en":"a large number of people or things","cn":"许多；大量","g":"[countable]","ex":{"en":"a host of possibilities","cn":"多种可能性"}},{"en":"the main computer in a network that controls or supplies information to other computers that are connected to it","cn":"（计算机网络的）主机，服务机","g":"[countable]","lab":"computing","ex":{"en":"transferring files from the host to your local computer","cn":"从主机向你的本地机传送文件"}},{"en":"the bread that is used in the Christian service of communion, after it has been blessed","cn":"圣饼（基督教圣餐仪式中经过祝祷的面饼）","g":"[singular]"},{"en":"to organize an event to which others are invited and make all the arrangements for them","cn":"主办，主持（活动）","g":"[transitive]","ex":{"en":"to host an event/a conference/a meeting","cn":"主办活动／大会／会议"},"pos":"verb"},{"en":"to introduce a television or radio programme, a show, etc.","cn":"主持（电视或广播节目等）","g":"[transitive]","ex":{"en":"Charlie Rose will host tonight's show.","cn":"查理·罗斯将主持今晚的节目。"},"pos":"verb"},{"en":"to organize a party that you have invited guests to","cn":"作为主人组织（聚会）；做东","g":"[transitive, intransitive]","ex":{"en":"to host a dinner","cn":"设宴招待客人"},"pos":"verb"},{"en":"to store a website on a computer connected to the internet, usually in return for payment","cn":"为（网站）提供虚拟主机（通常收费）","g":"[transitive]","lab":"computing","ex":{"en":"a company that builds and hosts e-commerce sites","cn":"为电子商务提供网站创建和虚拟主机服务的公司"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（举办聚会等的）主人，东道主","en":"The host at a party is the person who has invited the guests and provides the food, drink, or entertainment.","ex":{"en":"Apart from my host, I didn't know a single person there","cn":"除了主人外，那里的人我一个也不认识。"}},{"pos":"VERB 动词","cn":"作为主人组织，做东举办（聚会等）","en":"If someone hosts a party, dinner, or other function, they have invited the guests and provide the food, drink, or entertainment.","ex":{"en":"Tonight she hosts a ball for 300 guests.","cn":"今晚她做东举办一场有300名客人参加的舞会。"}},{"pos":"N-COUNT 可数名词","cn":"（某项活动的）主办国（或城市、机构）","en":"A country, city, or organization that is the host of an event provides the facilities for that event to take place.","ex":{"en":"Barcelona was chosen to be host of the 1992 Olympic games.","cn":"巴塞罗那获选为1992年奥运会的主办城市。"}},{"pos":"VERB 动词","cn":"（国家、城市或机构）主办（活动）","en":"If a country, city, or organization hosts an event, they provide the facilities for the event to take place.","ex":{"en":"Cannes hosts the annual film festival.","cn":"戛纳每年主办电影节。"}},{"pos":"PHRASE 短语","cn":"主办（活动）;接待（贵客）","en":"If a person or country plays host to an event or an important visitor, they host the event or the visit.","ex":{"en":"In 1987 Canada played host to the Commonwealth Conference","cn":"1987年加拿大主办了英联邦大会。"}},{"pos":"N-COUNT 可数名词","cn":"（广播、电视的）节目主持人","en":"The host of a radio or television show is the person who introduces it and talks to the people who appear in it.","ex":{"en":"I am host of a live radio programme.","cn":"我是一个电台直播节目的主持人。"}},{"pos":"VERB 动词","cn":"主持（广播、电视节目）","en":"The person who hosts a radio or television show introduces it and talks to the people who appear in it.","ex":{"en":"She also hosts a show on St Petersburg Radio.","cn":"她还在圣彼得堡电台主持一个节目。"}},{"pos":"QUANT 数量词","cn":"大量;许多","en":"A host of things is a lot of them.","ex":{"en":"A host of problems may delay the opening of the Channel Tunnel","cn":"可能推迟英吉利海峡隧道开通的问题一大筐。"}},{"pos":"N-COUNT 可数名词","cn":"（生物的）生长地，栖息地","en":"If an area is host to living things, those creatures live and feed in that area.","ex":{"en":"Uganda's beautiful highlands are host to a wide range of wildlife.","cn":"乌干达美丽的高地是众多野生动物的栖息地。"}},{"pos":"N-COUNT 可数名词","cn":"（计算机）主机","en":"A host or a host computer is the main computer in a network of computers, which controls the most important files and programs."},{"pos":"N-COUNT 可数名词","cn":"（寄生物的）寄主，宿主","en":"The host of a parasite is the plant or animal which it lives on or inside and from which it gets its food.","ex":{"en":"When the eggs hatch the larvae eat the living flesh of the host animal.","cn":"当卵孵化后，幼虫取食寄主的鲜肉。"}},{"pos":"N-COUNT 可数名词","cn":"圣体（基督教圣餐礼等宗教仪式中代表耶稣躯体的面饼）","en":"The Host is the bread which is used to represent the body of Christ in Christian church services such as Holy Communion."}]},"examples":[{"en":"a company that builds and hosts e-commerce sites","cn":"在互联网上建立并存贮电子商务网站的公司"},{"en":"The college is playing host to a group of visiting Russian scientists.","cn":"学院正在接待一批来访的俄罗斯科学家。"}]},"hospitality":{"media":{"uk":"media/uk/hospitality__gb_1.mp3","us":"media/us/hospitality__us_1.mp3"},"oxford":{"phon":"ˌhɒspɪˈtæləti","pos":"noun","senses":[{"en":"friendly and generous behaviour towards guests","cn":"好客；殷勤","ex":{"en":"Thank you for your kind hospitality.","cn":"感谢你的友好款待。"}},{"en":"food, drink or services that are provided by an organization for guests, customers, etc.","cn":"（款待客人、顾客等的）食物，饮料，服务；款待","ex":{"en":"We were entertained in the company's hospitality suite.","cn":"公司款待我们住进他们的迎宾套间。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"殷勤好客;热情友好","en":"Hospitality is friendly, welcoming behaviour towards guests or people you have just met.","ex":{"en":"Every visitor to Georgia is overwhelmed by the kindness, charm and hospitality of the people.","cn":"来到佐治亚州的每位游客都被当地人的善良、可爱和热情好客所深深打动。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（大型活动中公司为来访者或客户提供的）招待茶点，款待","en":"Hospitality is the food, drink, and other privileges which some companies provide for their visitors or clients at major sporting or other public events.","ex":{"en":"A few of us in the press were there, goggle-eyed at the lavish hospitality.","cn":"我们几位记者当时在那里，眼馋地看着丰盛的茶点。"}}]},"examples":[{"en":"We were entertained in the company's hospitality suite.","cn":"公司款待我们住进他们的迎宾套间。"},{"en":"the hospitality industry (= hotels, restaurants, etc.)","cn":"招待性行业（如旅馆、饭店等）"}]},"hollywood":{"media":{"uk":"media/uk/hollywood__gb_1.mp3","us":"media/us/hollywood__us_1.mp3"},"oxford":{"phon":"ˈhɒliwʊd","pos":"noun","senses":[{"en":"the part of Los Angeles where the film industry is based (used to refer to the US film industry and the way of life that is associated with it)","cn":"好莱坞；美国电影业；好莱坞生活方式","lab":"British English"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"（美国的）好莱坞电影业","en":"You use Hollywood to refer to the American film industry that is based in Hollywood, California.","ex":{"en":"...a major Hollywood studio.","cn":"好莱坞一家大制片厂"}}]},"examples":[{"en":"She is one of Hollywood’s major stars.","cn":"她是好莱坞的巨星之一。"}]},"homesickness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not happy","cn":""},{"en":"sad, especially for a long time – used about people and periods of time","cn":""}]},"media":{"uk":"media/uk/homesickness__gb_1.mp3","us":"media/us/homesickness__us_1.mp3"},"oxford":{"phon":"ˈhəʊmsɪknəs","pos":"noun","senses":[{"en":"the feeling of being sad because you are away from home and you miss your family and friends","cn":"思乡的；想家的；患怀乡病的","ex":{"en":"She soon got over her homesickness.","cn":"她的思乡情绪很快就缓解了。"}}]}},"hotel":{"media":{"uk":"media/uk/hotel__gb_1.mp3","us":"media/us/hotel__us_1.mp3"},"oxford":{"phon":"həʊˈtel","pos":"noun","senses":[{"en":"a building where people stay, usually for a short time, paying for their rooms and meals","cn":"旅馆；旅社","lab":"British English","ex":{"en":"a two-star/five-star, etc. hotel","cn":"两星级、五星级等旅馆"}},{"en":"a pub","cn":"酒吧；酒馆","lab":"Australian English, New Zealand English，，"},{"en":"a restaurant","cn":"餐馆","lab":"Indian English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宾馆;旅馆;酒店","en":"A hotel is a building where people stay, for example on holiday, paying for their rooms and meals."}]},"examples":[{"en":"We stayed at/in a hotel.","cn":"我们住在旅馆里。"},{"en":"a friendly, family-run hotel","cn":"一家亲切随和、家庭经营的旅店"}]},"holiday":{"media":{"uk":"media/uk/holiday__gb_1.mp3","us":"media/us/holiday__us_1.mp3"},"oxford":{"phon":"ˈhɒlədeɪ","pos":"noun","senses":[{"en":"a period of time when you are not at work or school","cn":"假期","g":"[uncountable]","lab":"both British English","ex":{"en":"the school/summer/Christmas holidays","cn":"学校假期；暑假；圣诞节假期"}},{"en":"a period of time spent travelling or resting away from home","cn":"度假","g":"[countable]","lab":"British English","ex":{"en":"a camping/skiing/walking holiday","cn":"露营／滑雪／远足度假"}},{"en":"a day when most people do not go to work or school, especially because of a religious or national celebration","cn":"假日，节日（尤指宗教节日或国家庆典日）","g":"[countable]","ex":{"en":"The president's birthday was declared a national holiday.","cn":"总统的生日被定为全国假日。"}},{"en":"the time from late November to early January that includes Thanksgiving, Christmas, Hanukkah and New Year","cn":"节日假期（从十一月底到一月上旬，期间有感恩节、圣诞节、修殿节和新年）","g":"[plural]","lab":"North American English","ex":{"en":"Happy Holidays!","cn":"节日愉快！"}},{"en":"to spend a holiday somewhere","cn":"度假；休假","ex":{"en":"She was holidaying with her family in Ireland.","cn":"她当时正和家人在爱尔兰度假。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（外出度过的）假期","en":"A holiday is a period of time during which you relax and enjoy yourself away from home. People sometimes refer to their holiday as their holidays.","ex":{"en":"I've just come back from a holiday in the United States","cn":"我刚从美国度假回来。"}},{"pos":"N-COUNT 可数名词","cn":"公众假日;节日","en":"A holiday is a day when people do not go to work or school because of a religious or national festival.","ex":{"en":"New Year's Day is a public holiday throughout Britain","cn":"元旦是全英国的公众假日。"}},{"pos":"N-PLURAL 复数名词","cn":"（学校的）假期","en":"The holidays are the time when children do not have to go to school.","ex":{"en":"...the first day of the school holidays.","cn":"学校放假的第一天"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（不上班的）休假期","en":"If you have a particular number of days' or weeks' holiday, you do not have to go to work for that number of days or weeks.","ex":{"en":"Every worker will be entitled to four weeks' paid holiday a year.","cn":"每位工人每年都能享受4周的带薪休假。"}},{"pos":"VERB 动词","cn":"（外出）度假","en":"If you are holidaying in a place away from home, you are on holiday there.","ex":{"en":"Sampling the local cuisine is one of the delights of holidaying abroad","cn":"品尝当地菜肴是海外度假的乐趣之一。"}}]},"examples":[{"en":"The package includes 20 days' paid holiday a year.","cn":"这一揽子福利包括每年 20 天的带薪假。"},{"en":"I'm afraid Mr Walsh is away on holiday this week.","cn":"很抱歉，沃尔什先生这个星期休假去了。"}]},"hostile":{"media":{"uk":"media/uk/hostile__gb_1.mp3","us":"media/us/hostile__us_1.mp3"},"oxford":{"phon":"ˈhɒstaɪl","pos":"adjective","senses":[{"en":"aggressive or unfriendly and ready to argue or fight","cn":"敌意的；敌对的","ex":{"en":"The speaker got a hostile reception from the audience.","cn":"演讲人遭到了听众喝倒彩。"}},{"en":"strongly rejecting something","cn":"坚决否定；强烈反对","ex":{"en":"The proposals have provoked a hostile response from opposition parties.","cn":"这些提案激起了各反对党派的强烈不满。"}},{"en":"making it difficult for something to happen or to be achieved","cn":"有阻碍的；不利的","ex":{"en":"hostile conditions for plants to grow in","cn":"不利于植物生长的环境"}},{"en":"belonging to a military enemy","cn":"敌军的；敌人的","ex":{"en":"hostile territory","cn":"敌方领土"}},{"en":"not wanted by the company that is to be bought","cn":"不受（被购公司）欢迎的；敌意的","lab":"business","ex":{"en":"a hostile takeover bid","cn":"出价敌意收购"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"敌对的;不赞成的","en":"If you are hostile to another person or an idea, you disagree with them or disapprove of them, often showing this in your behaviour.","ex":{"en":"Many people felt he would be hostile to the idea of foreign intervention","cn":"很多人觉得他会反对外国干预的主意。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怀有敌意的;不友善的","en":"Someone who is hostile is unfriendly and aggressive.","ex":{"en":"Drinking may make a person feel relaxed and happy, or it may make her hostile, violent, or depressed","cn":"喝酒可能让人感到放松和愉快，也可能让人变得不友善、暴力或阴郁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情况、形势等）不利的，恶劣的，造成阻碍的","en":"Hostile situations and conditions make it difficult for you to achieve something.","ex":{"en":"...some of the most hostile climatic conditions in the world","cn":"世界上最恶劣的几种气候条件"}},{"pos":"ADJ 形容词","cn":"（收购）恶意的，不受（被购公司）欢迎的","en":"A hostile takeover bid is one that is opposed by the company that is being bid for.","ex":{"en":"Kingfisher launched a hostile bid for Dixons.","cn":"翠丰集团对迪克森公司展开了恶意竞购。"}},{"pos":"ADJ 形容词","cn":"（战争中）敌方的，敌人的","en":"In a war, you use hostile to describe your enemy's forces, organizations, weapons, land, and activities.","ex":{"en":"The city is encircled by a hostile army","cn":"该市被敌军包围了。"}}]},"examples":[{"en":"The speaker got a hostile reception from the audience.","cn":"演讲人遭到了听众喝倒彩。"},{"en":"She was openly hostile towards her parents.","cn":"她公然对抗她的父母。"}]},"homogeneity":{"oxford":{"phon":"ˌhəʊməʊdʒəˈniːəti","pos":"noun","senses":[{"en":"the quality in a group of people or things of being all the same or all of the same type","cn":"同种；同质","ex":{"en":"Cultural homogeneity is created by education and the media.","cn":"文化同质性是由教育和媒体创造的。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同种;同质","en":"Homogeneity is the quality of being homogeneous.","ex":{"en":"The government panicked into imposing a kind of cultural homogeneity.","cn":"政府在恐慌下开始强制实施某种文化统一政策。"}}]},"media":{"uk":"media/uk/homogeneity__gb_1.mp3","us":"media/us/homogeneity__us_1.mp3"}},"hoof":{"oxford":{"phon":"huːf","pos":"noun","senses":[{"en":"the hard part of the foot of some animals, for example horses","cn":"（马等动物的）蹄","ex":{"en":"The horse tossed its head and stamped its hooves nervously.","cn":"马摇摇头，紧张地跺着蹄子。"}},{"en":"to kick a ball very hard or a long way","cn":"猛踢（球）；把（球）踢出很远","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（马等动物的）蹄","en":"The hooves of an animal such as a horse are the hard lower parts of its feet.","ex":{"en":"The horses' hooves often could not get a proper grip.","cn":"马蹄经常会打滑。"}}]},"media":{"img":["media/pic/mammals_comp.jpg","media/thumb/hoof.jpg"],"uk":"media/uk/hoof__gb_1.mp3","us":"media/us/hoof__us_1.mp3"},"examples":[{"en":"We hoofed it all the way to 42nd Street.","cn":"我们一路步行到了第 42 街。"}]},"hooked":{"media":{"uk":"media/uk/hooked__gb_1.mp3","us":"media/us/hooked__us_1.mp3"},"oxford":{"phon":"hʊkt","pos":"adjective","senses":[{"en":"curved; like a hook in shape","cn":"弯曲的；钩形的","ex":{"en":"a hooked nose/beak/finger","cn":"鹰钩鼻子；钩喙；屈指"}},{"en":"needing something that is bad for you, especially a drug","cn":"上瘾；（尤指）有毒瘾","g":"[not before noun]","lab":"informal","ex":{"en":"People who are truly hooked will go to any lengths to satisfy their craving for the drug.","cn":"真正吸毒成瘾的人为了满足毒瘾会不择手段。"}},{"en":"enjoying something very much, so that you want to do it, see it, etc. as much as possible","cn":"（对某事）着迷","g":"[not before noun]","lab":"informal","ex":{"en":"I first got hooked on scuba diving when I was twelve.","cn":"12 岁时我开始迷上了戴水肺潜水。"}},{"en":"having one or more hooks","cn":"有钩的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"钩状的","en":"If you describe something as hooked, you mean that it is shaped like a hook.","ex":{"en":"He was thin and tall, with a hooked nose.","cn":"他又瘦又高，长着鹰钩鼻。"}},{"pos":"ADJ 形容词","cn":"（被…）迷住的;（对…）入迷的","en":"If you are hooked on something, you enjoy it so much that it takes up a lot of your interest and attention.","ex":{"en":"Many of the leaders have become hooked on power and money","cn":"很多领导人都变得贪恋权力和金钱。"}},{"pos":"ADJ 形容词","cn":"（吸毒）上瘾的","en":"If you are hooked on a drug, you are addicted to it.","ex":{"en":"He spent a number of years hooked on cocaine, heroin and alcohol.","cn":"他有好几年时间吸食可卡因和海洛因成瘾，还整日酗酒。"}}]},"examples":[{"en":"a hooked nose/beak/finger","cn":"鹰钩鼻子；钩喙；屈指"},{"en":"I know a girl who got hooked on cocaine.","cn":"我认识一个染上可卡因毒瘾的姑娘。"}]},"homogeneous":{"media":{"uk":"media/uk/homogeneous__gb_1.mp3","us":"media/us/homogeneous__us_1.mp3"},"oxford":{"phon":"ˌhɒməˈdʒiːniəs","pos":"adjective","senses":[{"en":"consisting of things or people that are all the same or all of the same type","cn":"由同类事物（或人）组成的；同种类的","ex":{"en":"a homogeneous group/mixture/population","cn":"相同成分组成的群体／混合物；同类人口"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同种类的;同性质的;由相同成分（或部分）组成的","en":"Homogeneous is used to describe a group or thing which has members or parts that are all the same.","ex":{"en":"The unemployed are not a homogeneous group","cn":"失业者不能一概而论。"}}]},"examples":[{"en":"a homogeneous group/mixture/population","cn":"相同成分组成的群体/混合物；同类人口"},{"en":"a homogeneous society","cn":"同种族人组成的社会"}]},"hook":{"media":{"img":["media/ldoce/img/hook.jpg","media/pic/hook_comp.jpg"],"uk":"media/uk/hook__gb_1.mp3","us":"media/us/hook__us_1.mp3"},"oxford":{"phon":"hʊk","pos":"noun","senses":[{"en":"a curved piece of metal, plastic or wire for hanging things on, catching fish with, etc.","cn":"钩；钓钩；挂钩；鱼钩","ex":{"en":"a picture/curtain/coat hook","cn":"挂图钩；窗帘钩；挂衣钩"}},{"en":"a short hard hit that is made with the elbow bent","cn":"勾拳","ex":{"en":"a left hook to the jaw","cn":"击向下颌的一记左勾拳"}},{"en":"a way of hitting the ball so that it curves to the side instead of going straight ahead (usually by mistake in golf, but deliberately in cricket)","cn":"（高尔夫球）左曲球，内弯球；（板球）曲线球"},{"en":"a thing that is used to make people interested in something","cn":"吸引人的事物；诱饵","ex":{"en":"The images are used as a hook to get children interested in science.","cn":"这些图像用以吸引孩子们对科学产生兴趣。"}},{"en":"to fasten or hang something on something else using a hook; to be fastened or hanging in this way","cn":"（使）钩住，挂住","g":"[transitive, intransitive]","ex":{"en":"We hooked the trailer to the back of the car.","cn":"我们把拖车挂在汽车尾部。"},"pos":"verb"},{"en":"to put something, especially your leg, arm or finger, around something else so that you can hold onto it or move it; to go around something else in this way","cn":"（尤指用腿、胳膊、手指等）钩住，箍住","g":"[transitive, intransitive]","ex":{"en":"He hooked his foot under the stool and dragged it over.","cn":"他用脚从底下钩住凳子，把它拖了过去。"},"pos":"verb"},{"en":"to catch a fish with a hook","cn":"钓（鱼）","g":"[transitive]","lab":"figurative","ex":{"en":"It was the biggest pike I ever hooked.","cn":"那是我钓到的最大的狗鱼。"},"pos":"verb"},{"en":"to hit or kick a ball so that it goes to one side instead of straight ahead (usually by mistake in golf but deliberately in other sports)","cn":"打左曲球；打曲线球；踢弧线球","g":"[transitive]","ex":{"en":"He hooked his drive into the trees.","cn":"他把车挂在树林里。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钩;吊钩;挂钩","en":"A hook is a bent piece of metal or plastic that is used for catching or holding things, or for hanging things up.","ex":{"en":"One of his jackets hung from a hook.","cn":"他的一件夹克衫挂在衣钩上。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（用钩）吊住，挂住，固定","en":"If you hook one thing to another, you attach it there using a hook. If something hooks somewhere, it can be hooked there.","ex":{"en":"Paul hooked his tractor to the car and pulled it to safety.","cn":"保罗把自己的拖拉机挂在汽车上，然后把它拉到了安全的地方。"}},{"pos":"VERB 动词","cn":"（用手臂、腿或脚）钩住，绕住","en":"If you hook your arm, leg, or foot round an object, you place it like a hook round the object in order to move it or hold it.","ex":{"en":"She latched on to his arm, hooking her other arm around a tree","cn":"她拽住他的胳膊不放，另一只胳膊抱紧一棵树。"}},{"pos":"VERB 动词","cn":"钓（鱼）","en":"If you hook a fish, you catch it with a hook on the end of a line.","ex":{"en":"At the first cast I hooked a huge fish.","cn":"第一次抛下钓线，我就钓了一条大鱼。"}},{"pos":"N-COUNT 可数名词","cn":"（通常指拳击运动中的）钩拳","en":"A hook is a short sharp blow with your fist that you make with your elbow bent, usually in a boxing match.","ex":{"en":"Lewis desperately needs to keep clear of Ruddock's big left hook.","cn":"刘易斯无论如何得躲开拉多克凌厉的左钩拳才行。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）参与;（使）涉足","en":"If you are hooked into something, or hook into something, you get involved with it.","ex":{"en":"I'm guessing again now because I'm not hooked into the political circles","cn":"我现在又是在猜测了，因为我没有涉足政界。"}},{"pos":"VERB 动词","cn":"连接到（因特网）;上（网）","en":"If you hook into the Internet, you make a connection with the Internet on a particular occasion so that you can use it.","ex":{"en":"...an interactive media tent where people will be able to hook into the internet.","cn":"人们可以上网的互动式媒体帐篷区"}},{"pos":"PHRASE 短语","cn":"脱离困境;脱身","en":"If someone gets off the hook or is let off the hook, they manage to get out of the awkward or unpleasant situation that they are in.","ex":{"en":"Government officials accused of bribery and corruption get off the hook with monotonous regularity","cn":"被指控贪污受贿的政府官员无一例外总能脱身。"}},{"pos":"PHRASE 短语","cn":"摘下听筒（不让电话响）","en":"If you take a phone off the hook, you take the receiver off the part that it normally rests on, so that the phone will not ring."},{"pos":"PHRASE 短语","cn":"（电话）响个不停","en":"If your phone is ringing off the hook, so many people are trying to telephone you that it is ringing constantly.","ex":{"en":"Since war broke out, the phones at donation centers have been ringing off the hook.","cn":"自从战争爆发以来，捐赠中心的电话就一直响个不停。"}},{"pos":"","cn":"","en":"by hook or by crook→see: ; by hook or by crook→see: ; by hook or by crook→see: ; hook→see: ;"},{"pos":"","cn":"","en":"相关词组：hook up"}]},"examples":[{"en":"The images are used as a hook to get children interested in science.","cn":"这些图像用以吸引孩子们对科学产生兴趣。"},{"en":"He hooked his foot under the stool and dragged it over.","cn":"他用脚从底下钩住凳子，把它拖了过去。"}]},"hopefully":{"media":{"uk":"media/uk/hopefully__gb_1.mp3","us":"media/us/hopefully__us_1.mp3"},"oxford":{"phon":"ˈhəʊpfəli","pos":"adverb","senses":[{"en":"used to express what you hope will happen","cn":"有希望地；可以指望","ex":{"en":"Hopefully, we'll arrive before dark.","cn":"我们有望在天黑前到达。"}},{"en":"showing hope","cn":"抱有希望地","ex":{"en":"‘Are you free tonight?’ she asked hopefully.","cn":"“你今晚有空吗？”她抱着希望地问。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"但愿，作为希望（一些用词严谨者认为这种用法不正确，但实际上已被频繁地使用）","en":"You say hopefully when mentioning something that you hope will happen. Some careful speakers of English think that this use of hopefully is not correct, but it is very frequently used.","ex":{"en":"Both of them have been through an awful lot and hopefully now I can help them rebuild their lives","cn":"他们两人都曾历经磨难，但愿现在我能帮助他们重建正常的生活。"}}]},"examples":[{"en":"‘Are you free tonight?’ she asked hopefully. “","cn":"你今晚有空吗？”她抱着希望地问。"},{"en":"Hopefully, we'll arrive before dark.","cn":"我们有望在天黑前到达。"}]},"homeworker":{"oxford":{"phon":"ˈhəʊmwɜːkə(r)","pos":"noun","senses":[{"en":"a person who works at home, often doing jobs that are not well paid such as making clothes for shops","cn":"在家工作的人（常做低薪工作）","ex":{"en":"Few homeworkers doing piecework in manufacturing enjoy employee status.","cn":"在制造业中从事计件工作的家庭工人很少享有雇员身份。"}}]},"media":{"uk":"media/uk/homeworker__gb_1.mp3","us":"media/us/homeworker__us_1.mp3"}},"hover":{"oxford":{"phon":"ˈhɒvə(r)","pos":"verb","senses":[{"en":"to stay in the air in one place","cn":"翱翔；盘旋","g":"[intransitive]","ex":{"en":"A hawk hovered over the hill.","cn":"一只鹰在小山的上空翱翔。"}},{"en":"to wait somewhere, especially near somebody, in a shy or uncertain manner","cn":"踌躇，彷徨（尤指在某人身边）","g":"[intransitive]","ex":{"en":"He hovered nervously in the doorway.","cn":"他在门口紧张地来回踱步。"}},{"en":"to stay close to something, or to stay in an uncertain state","cn":"靠近（某事物）；处于不稳定状态","g":"[intransitive]","ex":{"en":"Temperatures hovered around freezing.","cn":"气温在冰点上下徘徊。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"悬浮;（鸟、昆虫等）振翅悬停","en":"To hover means to stay in the same position in the air without moving forwards or backwards. Many birds and insects can hover by moving their wings very quickly.","ex":{"en":"Beautiful butterflies hovered above the wild flowers","cn":"美丽的蝴蝶在野花上方飞舞。"}},{"pos":"VERB 动词","cn":"逗留在一处;徘徊;踌躇","en":"If you hover, you stay in one place and move slightly in a nervous way, for example because you cannot decide what to do.","ex":{"en":"Judith was hovering in the doorway","cn":"朱迪丝在门口徘徊。"}},{"pos":"VERB 动词","cn":"处于不确定状态;犹豫不决","en":"If you hover, you are in an uncertain situation or state of mind.","ex":{"en":"She hovered on the brink of death for three months as doctors battled to save her","cn":"3个月来她一直在死亡线上徘徊，而医生则在全力挽救她的生命。"}},{"pos":"VERB 动词","cn":"（价格、价值、分数等）上下波动左右摇摆","en":"If something such as a price, value, or score hovers around a particular level, it stays at more or less that level and does not change much.","ex":{"en":"In September 1989 the exchange rate hovered around 140 yen to the dollar","cn":"1989年9月，日元对美元的汇率一直在140比1的水平上下浮动。"}}]},"media":{"uk":"media/uk/hover__gb_1.mp3","us":"media/us/hover__us_1.mp3"},"examples":[{"en":"A hawk hovered over the hill.","cn":"一只鹰在小山的上空翱翔。"},{"en":"He hovered nervously in the doorway.","cn":"他在门口紧张地来回踱步。"}]},"holes":{"oxford":{"phon":"həʊl","pos":"noun","senses":[{"en":"a hollow space in sth solid or in the surface of sth","cn":"洞；孔；坑"},{"en":"a space or opening that goes all the way through sth","cn":"裂口；开口；孔眼"}]}},"horror":{"media":{"uk":"media/uk/horror__gb_1.mp3","us":"media/us/horror__us_1.mp3"},"oxford":{"phon":"ˈhɒrə(r)","pos":"noun","senses":[{"en":"a feeling of great shock or fear","cn":"震惊；恐惧","g":"[uncountable]","ex":{"en":"The thought of being left alone filled her with horror.","cn":"想到被孤零零地留下，她就不寒而栗。"}},{"en":"a very unpleasant or frightening experience","cn":"极其不愉快的（或可怕的）经历","g":"[countable, usually plural]","ex":{"en":"an account of the horrors inflicted on the detainees","cn":"对被拘留者遭受的恐怖经历的描述"}},{"en":"the very unpleasant nature of something, especially when it shocks or frightens you","cn":"（某事物）令人厌恶的性质；（尤指）震惊性，恐怖性","g":"[uncountable]","ex":{"en":"The full horror of the accident was beginning to become clear.","cn":"这次悲惨事故的真相已开始逐渐清晰了。"}},{"en":"a strong feeling of fear or of hating something","cn":"畏惧；痛恨","g":"[singular]","ex":{"en":"a horror of deep water","cn":"恐惧深水"}},{"en":"a type of book, film, etc. that is designed to frighten people","cn":"恐怖题材的作品","g":"[uncountable]","ex":{"en":"In this section you'll find horror and science fiction.","cn":"你可以在这一部分找到恐怖和科幻小说。"}},{"en":"a child who behaves badly","cn":"调皮捣蛋的孩子","g":"[countable]","lab":"British English, informal，，","ex":{"en":"Her son is a little horror.","cn":"她的儿子是个小捣蛋鬼。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"震惊;恐惧;惊恐","en":"Horror is a feeling of great shock, fear, and worry caused by something extremely unpleasant.","ex":{"en":"I felt numb with horror","cn":"我惊呆了。"}},{"pos":"N-SING 单数名词","cn":"惧怕;憎恶","en":"If you have a horror of something, you are afraid of it or dislike it very much.","ex":{"en":"...his horror of death.","cn":"他对死亡的惧怕"}},{"pos":"N-SING 单数名词","cn":"恐怖性;残酷","en":"The horror of something, especially something that hurts people, is its very great unpleasantness.","ex":{"en":"...the horror of this most bloody of civil wars.","cn":"这场极其血腥的内战的惨烈"}},{"pos":"N-COUNT 可数名词","cn":"极其不愉快（或可怕）的经历","en":"You can refer to extremely unpleasant or frightening experiences as horrors .","ex":{"en":"Can you possibly imagine all the horrors we have undergone since I last wrote you?","cn":"你能想象得出自从我上次给你写信以来我们所经历的所有可怕事情吗？"}},{"pos":"N-COUNT 可数名词","cn":"极讨厌（或丑陋）的人（或事物）","en":"If you refer to someone or something as a horror, you mean that you think they are very unpleasant or ugly.","ex":{"en":"Our host was arrogant and offensive. How his sweet wife could tolerate such a horror was baffling.","cn":"招待我们的男主人傲慢无礼。真不知道他温柔的妻子怎么能容忍这样一个讨厌的家伙。"}},{"pos":"ADJ 形容词","cn":"（影片或故事）情节恐怖的，惊悚的","en":"A horror film or story is intended to be very frightening.","ex":{"en":"...a psychological horror film.","cn":"心理恐怖片"}},{"pos":"ADJ 形容词","cn":"（经历或事件）非常不愉快的","en":"You can refer to an account of a very unpleasant experience or event as a horror story.","ex":{"en":"...a horror story about lost luggage while flying.","cn":"乘飞机旅行时丢失行李的糟糕经历"}},{"pos":"PHRASE 短语","cn":"最糟糕不过的事情","en":"Horror of horrors is used to refer to something that you consider to be the worst part of a situation.","ex":{"en":"The company has already boosted its share of the UK tea market with its round tea bags. Now it is successfully converting the nation to (horror of horrors) instant tea.","cn":"该公司已经凭借其袋泡茶提高了自己在英国茶叶市场的占有份额。现在它正在成功地使该国人民改喝（最可怕不过的）速溶茶。"}}]},"examples":[{"en":"I stood up to speak and — horror of horrors — realized I had left my notes behind.","cn":"我站起来讲话，可是，可怕的是，我发现自己忘了带讲稿。"},{"en":"With a look of horror, he asked if the doctor thought he had cancer.","cn":"他惊恐失色地问医生是否认定他患了癌症。"}]},"home":{"media":{"img":["media/pic/homes_comp.jpg","media/thumb/semidetached.jpg"],"uk":"media/uk/home__gb_1.mp3","us":"media/us/home__us_1.mp3"},"oxford":{"phon":"həʊm","pos":"noun","senses":[{"en":"the house or flat that you live in, especially with your family","cn":"家；住所","g":"[countable, uncountable]","sc":"house, etc.","ex":{"en":"Old people prefer to stay in their own homes.","cn":"老年人喜欢待在自己家中。"}},{"en":"a house or flat, etc., when you think of it as property that can be bought and sold","cn":"（可买卖的）房子，住宅，寓所","g":"[countable]","lab":"British English","sc":"house, etc.","ex":{"en":"a holiday/summer home","cn":"假日／消夏寓所"}},{"en":"the town, district, country, etc. that you come from, or where you are living and that you feel you belong to","cn":"家乡；故乡；定居地","g":"[countable, uncountable]","sc":"town/country","ex":{"en":"I often think about my friends back home.","cn":"我常常想起老家的朋友。"}},{"en":"used to refer to a family living together, and the way it behaves","cn":"家庭","g":"[countable]","sc":"family","ex":{"en":"She came from a violent home.","cn":"她出身于一个有暴力行为的家庭。"}},{"en":"a place where people who cannot care for themselves live and are cared for by others","cn":"养老院；养育院","g":"[countable]","sc":"for old people/children","ex":{"en":"a children’s home","cn":"儿童之家"}},{"en":"a place where pets with no owner are taken care of","cn":"收养所","g":"[countable]","sc":"for pets","ex":{"en":"a dogs’/cats’ home","cn":"狗／猫之家"}},{"en":"the place where a plant or animal usually lives; the place where somebody/something can be found","cn":"生息地；栖息地；产地","g":"[singular, uncountable]","sc":"of plant/animal","ex":{"en":"This region is the home of many species of wild flower.","cn":"这个地区有很多种类的野花。"}},{"en":"a place where an object is kept","cn":"（存放东西的）地方，场所","g":"[countable]","lab":"informal","sc":"where something is kept","ex":{"en":"We haven't found a home for all our books yet.","cn":"我们还没有找到地方存放我们所有的书。"}},{"en":"the place where something was first discovered, made or invented","cn":"发源地；发祥地","g":"[singular]","sc":"where something first done","ex":{"en":"New Orleans, the home of jazz","cn":"新奥尔良，爵士乐的发源地"}},{"en":"to or at the place where you live","cn":"到家；向家；在家","lab":"North American English","sc":"where you live","ex":{"en":"Come on, it's time to go home.","cn":"快点，该回家了。"},"pos":"adverb"},{"en":"into the correct position","cn":"到正确的位置","sc":"into correct position","ex":{"en":"She leaned on the door and pushed the bolt home.","cn":"她倚在门上，上好了门闩。"},"pos":"adverb"},{"en":"connected with the place where you live","cn":"家的；家庭的","sc":"where you live","ex":{"en":"home life (= with your family)","cn":"家庭生活"},"pos":"adjective"},{"en":"made or used at home","cn":"在家里做的；家用的","sc":"made/used at home","ex":{"en":"We have a home movie of my dad teaching me to swim.","cn":"我们有一部爸爸教我学游泳的自制家庭影片。"},"pos":"adjective"},{"en":"connected with your own country rather than foreign countries","cn":"本国的；国内的","lab":"especially British English","sc":"own country","ex":{"en":"products for the home market","cn":"为国内市场生产的产品"},"pos":"adjective"},{"en":"connected with a team’s own sports ground","cn":"主场的","sc":"in sport","ex":{"en":"a home game/match/win","cn":"主场赛事／比赛／胜利"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"家;住宅;住所","en":"Someone's home is the house or flat where they live.","ex":{"en":"Last night they stayed at home and watched TV","cn":"昨晚他们呆在了家里看电视。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（强调归属感的）家，家乡，祖国","en":"You can use home to refer in a general way to the house, town, or country where someone lives now or where they were born, often to emphasize that they feel they belong in that place.","ex":{"en":"She gives frequent performances of her work, both at home and abroad","cn":"她经常在国内外演出自己的作品。"}},{"pos":"ADV 副词","cn":"向家;在家","en":"Home means to or at the place where you live.","ex":{"en":"His wife wasn't feeling too well and she wanted to go home","cn":"他的妻子感到有些不舒服，想要回家。"}},{"pos":"ADJ 形容词","cn":"在家里做（或进行）的","en":"Home means made or done in the place where you live.","ex":{"en":"...cheap but healthy home cooking","cn":"便宜而健康的家常菜"}},{"pos":"ADJ 形容词","cn":"本国的;国内的","en":"Home means relating to your own country as opposed to foreign countries.","ex":{"en":"Europe's software companies still have a growing home market.","cn":"欧洲软件公司的国内市场仍在增长中。"}},{"pos":"N-COUNT 可数名词","cn":"养老院;疗养院;养育院","en":"A home is a large house or institution where a number of people live and are looked after, instead of living in their own houses or flats. They usually live there because they are too old or ill to look after themselves or for their families to care for them.","ex":{"en":"It's going to be a home for handicapped children.","cn":"这将是一家残疾儿童福利院。"}},{"pos":"N-COUNT 可数名词","cn":"家庭","en":"You can refer to a family unit as a home .","ex":{"en":"She had, at any rate, provided a peaceful and loving home for Harriet","cn":"她至少为哈丽雅特提供了一个安宁关爱的家。"}},{"pos":"N-SING 单数名词","cn":"发源地;发祥地;产地;生息地","en":"If you refer to the home of something, you mean the place where it began or where it is most typically found.","ex":{"en":"This south-west region of France is the home of claret.","cn":"法国西南部的这个地区是干红葡萄酒的产地。"}},{"pos":"N-COUNT 可数名词","cn":"适于存放…的地方","en":"If you find a home for something, you find a place where it can be kept.","ex":{"en":"The equipment itself is getting smaller, neater and easier to find a home for.","cn":"该设备本身正变得越来越小，越来越轻巧，也越来越便于存放。"}},{"pos":"ADV 副词","cn":"击中要害地;彻底地;深切地;切实地","en":"If you press, drive, or hammer something home, you explain it to people as forcefully as possible.","ex":{"en":"It is now up to all of us to debate this issue and press home the argument.","cn":"现在要靠我们大家对此问题进行辩论，并尽可能将论点阐述清楚。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（比赛的）主场","en":"When a sports team plays at home, they play a game on their own ground, rather than on the opposing team's ground.","ex":{"en":"I scored in both games against Barcelona; we drew at home and beat them away.","cn":"我在两场对阵巴塞罗那队的比赛中都进了球;我们在主场战平，在客场赢了他们。"}},{"pos":"PHRASE 短语","cn":"像在家一样舒适自在;无拘束","en":"If you feel at home, you feel comfortable in the place or situation that you are in.","ex":{"en":"He spoke very good English and appeared pleased to see us, and we soon felt quite at home","cn":"他英语说得非常好，见到我们显得很高兴，我们很快就不拘束了。"}},{"pos":"PHRASE 短语","cn":"使清楚地领会;使深切地感到","en":"To bring something home to someone means to make them understand how important or serious it is.","ex":{"en":"Their sobering conversation brought home to everyone present the serious and worthwhile work the Red Cross does.","cn":"他们发人深省的对话使在座的每个人都清楚地认识到红十字会所从事的严肃而有价值的工作。"}},{"pos":"PHRASE 短语","cn":"大功告成;稳操胜券","en":"If you say that someone is, in British English home and dry, or in American English home free, you mean that they have been successful or that they are certain to be successful.","ex":{"en":"The prime minister and the moderates are not yet home and dry.","cn":"首相和温和派还未大功告成。"}},{"pos":"PHRASE 短语","cn":"切中要害;使人接受（或认清）事实","en":"If a situation or what someone says hits home or strikes home, people accept that it is real or true, even though it may be painful for them to realize.","ex":{"en":"Did the reality of war finally hit home?","cn":"人们终于认清战争的现实了吗？"}},{"pos":"PHRASE 短语","cn":"像家里一样舒适的地方","en":"You can say a home from home in British English or a home away from home in American English to refer to a place in which you are as comfortable as in your own home.","ex":{"en":"Many cottages are a home from home, offering microwaves, dishwashers, tvs and videos.","cn":"很多度假屋都像自家一样，里面有微波炉、洗碗机、电视机和录像机。"}},{"pos":"CONVENTION 惯用语","cn":"请别拘束;请随便","en":"If you say to a guest 'Make yourself at home', you are making them feel welcome and inviting them to behave in an informal, relaxed way."},{"pos":"PHRASE 短语","cn":"平平常常;没有什么特别有趣的地方","en":"If you say that something is nothing to write home about, you mean that it is not very interesting or exciting.","ex":{"en":"So a dreary Monday afternoon in Walthamstow is nothing to write home about, right?","cn":"这么说，在沃尔瑟姆斯托度过的一个沉闷的周一下午没什么值得大书特书的，是吗？"}},{"pos":"PHRASE 短语","cn":"击中目标","en":"If something that is thrown or fired strikes home, it reaches its target.","ex":{"en":"Only two torpedoes struck home.","cn":"只有两枚鱼雷击中了目标。"}},{"pos":"","cn":"","en":"相关词组：home in"}]},"examples":[{"en":"The television pictures brought home to us the full horror of the attack.","cn":"电视画面使我们充分地了解这次袭击有多么恐怖。"},{"en":"He had always wanted a real home with a wife and children.","cn":"他一直想要一个有妻子和孩子的真正的家庭。"}]},"hold":{"media":{"uk":"media/uk/hold__gb_1.mp3","us":"media/us/hold__us_1.mp3","img":["media/ldoce/img/hold.jpg"]},"oxford":{"phon":"həʊld","pos":"verb","senses":[{"en":"to have somebody/something in your hand, arms, etc.","cn":"拿着；抓住；抱住；夹着","g":"[transitive]","sc":"in hand/arms","ex":{"en":"She was holding a large box.","cn":"她提着一只大箱子。"}},{"en":"to put your hand on part of your body, usually because it hurts","cn":"抱住，捂住，按住（受伤的身体部位等）","g":"[transitive]","sc":"in hand/arms","ex":{"en":"She groaned and held her head.","cn":"她呻吟着，用手抱住头。"}},{"en":"to keep somebody/something in a particular position","cn":"使保持（在某位置）","g":"[transitive]","sc":"in position","ex":{"en":"Hold your head up.","cn":"抬起头来。"}},{"en":"to support the weight of somebody/something","cn":"支撑…的重量","g":"[transitive]","sc":"support","ex":{"en":"I don't think that branch will hold your weight.","cn":"我觉得那根树枝撑不住你的重量。"}},{"en":"to have enough space for something/somebody; to contain something/somebody","cn":"容纳；包含","g":"[transitive]","sc":"contain","ex":{"en":"This barrel holds 25 litres.","cn":"这只桶能盛 25 升。"}},{"en":"to have or offer something; to be going to bring something","cn":"拥有；提供；带来","sc":"contain","ex":{"en":"I don't know what the future holds.","cn":"我不知道未来会怎样。"}},{"en":"to have a meeting, competition, conversation, etc.","cn":"召开；举行；进行","g":"[transitive]","sc":"meeting","ex":{"en":"Each month she holds a meeting with her entire staff.","cn":"每个月她都与全体员工举行一次会议。"}},{"en":"to have something you have gained or achieved","cn":"获得；赢得","g":"[transitive]","sc":"record/title","ex":{"en":"Who holds the world record for the long jump?","cn":"跳远世界纪录的保持者是谁？"}},{"en":"to have a particular job or position","cn":"担任；任职","g":"[transitive]","sc":"job","ex":{"en":"How long has he held office?","cn":"他任职有多久了？"}},{"en":"to keep somebody and not allow them to leave","cn":"监禁；拘留","g":"[transitive]","sc":"somebody prisoner","ex":{"en":"Police are holding two men in connection with last Thursday's bank raid.","cn":"警方拘留了两名与上星期四的银行抢劫案有关的男子。"}},{"en":"to keep somebody’s attention or interest","cn":"使（注意力或兴趣）持续不减；吸引住","g":"[transitive]","sc":"keep","ex":{"en":"There wasn't much in the museum to hold my attention.","cn":"博物馆中没有很多让我感兴趣的东西。"}},{"en":"to keep something at the same level, rate, speed, etc.; to stay at the same level, rate, etc.","cn":"（使）保持同样程度（或比率、速度等）","g":"[transitive, intransitive]","sc":"keep","ex":{"en":"Hold your speed at 70.","cn":"把速度保持在 70。"}},{"en":"to keep something so that it can be used later","cn":"保存；存储","g":"[transitive]","sc":"keep","ex":{"en":"Employees do not have access to personal records held on computer.","cn":"雇员没有机会看到存储在计算机中的个人记录。"}},{"en":"to wait until you can speak to the person you have phoned","cn":"（打电话时）等待，不挂断","g":"[intransitive, transitive]","sc":"on phone","ex":{"en":"That extension is busy right now. Can you hold?","cn":"分机现在占线。您能等一会吗？"}},{"en":"to own or have something","cn":"拥有；持有","g":"[transitive]","lab":"rather formal","sc":"own","ex":{"en":"Employees hold 30% of the shares.","cn":"雇员持有 30% 的股份。"}},{"en":"to defend something against attack; to have control of something","cn":"守卫；控制","g":"[transitive]","sc":"control","ex":{"en":"The rebels held the radio station.","cn":"叛乱者占据了电台。"}},{"en":"to remain strong and safe or in position","cn":"承受住；坚持住；保持原位","g":"[intransitive]","sc":"remain","ex":{"en":"They were afraid the dam wouldn't hold.","cn":"他们担心大坝会承受不住。"}},{"en":"to remain the same","cn":"保持不变","g":"[intransitive]","sc":"remain","ex":{"en":"How long will the fine weather hold?","cn":"好天气会持续多久？"}},{"en":"to have a belief or an opinion about somebody/something","cn":"怀有，持有（信念、意见）","g":"[transitive]","sc":"opinion","ex":{"en":"He holds strange views on education.","cn":"他对教育的看法不同寻常。"}},{"en":"to consider that something is true","cn":"认为；相信","g":"[transitive]","lab":"formal","sc":"opinion","ex":{"en":"I still hold that the government's economic policies are mistaken.","cn":"我仍然认为政府的经济政策是错误的。"}},{"en":"to be in close contact with the road and easy to control, especially when driven fast","cn":"（尤指高速行驶时）平稳行驶","g":"[transitive]","sc":"road/course"},{"en":"to continue to move in a particular direction","cn":"保持航线","g":"[transitive]","sc":"road/course"},{"en":"to make a note continue for a particular time","cn":"延长，继续唱（某音符）","g":"[transitive]","sc":"in music"},{"en":"be able to drink a reasonable amount of alcohol without becoming drunk","cn":"有一定的酒量","sc":"alcohol","ex":{"en":"I can hold my drink as well as anyone.","cn":"我的酒量不比任何人差。"}},{"en":"to win a game in which you are serving","cn":"保住发球局，保发（发球方在该局获胜）","g":"[transitive, intransitive]","sc":"in sport","ex":{"en":"Zverev held serve to take the set.","cn":"兹维列夫保住发球胜盘。"}},{"en":"used to tell somebody to stop doing something or not to do something","cn":"停下；不要做","g":"[transitive]","lab":"North American English, informal，，","sc":"stop","ex":{"en":"Hold your fire! (= don't shoot)","cn":"别开枪！"}},{"en":"the action of holding somebody/something; the way you are holding somebody/something","cn":"抓；握；拿；支撑","g":"[singular, uncountable]","sc":"with hand","ex":{"en":"His hold on her arm tightened.","cn":"他把她的胳膊抓得更紧了。"},"pos":"noun"},{"en":"a particular way of holding somebody, especially in a fight or in a sport such as wrestling","cn":"压，握，锁，扣（尤指打斗或摔跤等运动的招式）","g":"[countable]","sc":"in sport/a fight","ex":{"en":"He still had me in a tight hold.","cn":"他仍然紧紧锁住我。"},"pos":"noun"},{"en":"influence, power or control over somebody/something","cn":"影响；权威；控制","g":"[singular]","sc":"power/control","ex":{"en":"He struggled to get a hold of his anger.","cn":"他竭力压制自己的怒火。"},"pos":"noun"},{"en":"a place where you can put your hands or feet when climbing","cn":"支撑点（可手攀或脚踏的地方）","g":"[countable]","sc":"in climbing","ex":{"en":"She put her foot firmly in the hold and pulled herself up.","cn":"她把脚牢牢地踩在船舱里，然后把自己拉了起来。"},"pos":"noun"},{"en":"the part of a ship or plane where the goods being carried are stored","cn":"货舱","g":"[countable]","sc":"on ship/plane","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拿着;握住;托住","en":"When you hold something, you carry or support it, using your hands or your arms.","ex":{"en":"Hold the knife at an angle","cn":"斜握住刀。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（紧紧的）拿，握","en":"Hold is used in expressions such as grab hold of ,catch hold of, and get hold of, to indicate that you close your hand tightly around something, for example to stop something moving or falling.","ex":{"en":"I was woken up by someone grabbing hold of my sleeping bag","cn":"有人猛地抓住了我的睡袋，把我惊醒了。"}},{"pos":"VERB 动词","cn":"（通常为表示喜爱或安慰而）拥抱，抱住","en":"When you hold someone, you put your arms round them, usually because you want to show them how much you like them or because you want to comfort them.","ex":{"en":"If only he would hold her close to him.","cn":"要是他能将她拥入怀中就好了。"}},{"pos":"VERB 动词","cn":"用力使（某人）不得动弹","en":"If you hold someone in a particular position, you use force to keep them in that position and stop them from moving.","ex":{"en":"He then held the man in an armlock until police arrived","cn":"然后他反扭住那名男子的手臂让他动弹不得，直到警察赶到。"}},{"pos":"N-COUNT 可数名词","cn":"（使某人不得动弹的）抓住，夹住","en":"A hold is a particular way of keeping someone in a position using your own hands, arms, or legs.","ex":{"en":"...use of an unauthorized hold on a handcuffed suspect.","cn":"对戴手铐的嫌疑犯使用非法的擒拿方式"}},{"pos":"VERB 动词","cn":"（常指疼伤痛而）按住，捂住","en":"When you hold a part of your body, you put your hand on or against it, often because it hurts.","ex":{"en":"Soon she was crying bitterly about the pain and was holding her throat.","cn":"很快她痛得大哭起来，同时用手捂着自己的喉咙。"}},{"pos":"VERB 动词","cn":"使（身体部位）保持（某种姿势）","en":"When you hold a part of your body in a particular position, you put it into that position and keep it there.","ex":{"en":"Hold your hands in front of your face","cn":"把双手举在面前。"}},{"pos":"VERB 动词","cn":"把…固定住","en":"If one thing holds another in a particular position, it keeps it in that position.","ex":{"en":"...the wooden wedge which held the heavy door open","cn":"卡住沉重的门不让它关上的木楔"}},{"pos":"VERB 动词","cn":"存放;盛放;装","en":"If one thing is used to hold another, it is used to store it.","ex":{"en":"Two knife racks hold her favourite knives.","cn":"两个刀架上存放着她最心爱的刀具。"}},{"pos":"N-COUNT 可数名词","cn":"（船、飞机等的）货舱，行李舱","en":"In a ship or aeroplane, a hold is a place where cargo or luggage is stored.","ex":{"en":"A fire had been reported in the cargo hold.","cn":"行李舱内报称起火了。"}},{"pos":"VERB 动词","cn":"储备;储存","en":"If a place holds something, it keeps it available for reference or for future use.","ex":{"en":"The Small Firms Service holds an enormous amount of information on any business problem","cn":"小型企业服务处备有关于各种商务问题的海量信息。"}},{"pos":"VERB 动词","cn":"容纳得下","en":"If something holds a particular amount of something, it can contain that amount.","ex":{"en":"The small bottles don't seem to hold much","cn":"这些小瓶子好像装不下多少。"}},{"pos":"VERB 动词","cn":"大量喝（酒）而不醉","en":"If you can hold your drink, you are able to drink large quantities of alcohol without becoming ill or getting drunk.","ex":{"en":"...but you had to be able to hold your liquor.","cn":"但你得能喝酒才行。"}},{"pos":"VERB 动词","cn":"（车辆）抓（地）","en":"If a vehicle holds the road well, it remains in close contact with the road and can be controlled safely and easily.","ex":{"en":"I thought the car held the road really well.","cn":"我认为这辆车抓地性能真的非常好。"}},{"pos":"VERB 动词","cn":"持有，怀有（观点、信念等）","en":"Hold is used with words and expressions indicating an opinion or belief, to show that someone has a particular opinion or believes that something is true.","ex":{"en":"He held firm opinions which usually conflicted with my own","cn":"他对自己的观点坚定不移，而这些观点通常和我的相左。"}},{"pos":"VERB 动词","cn":"带给人，使人感到（害怕、神秘等）","en":"Hold is used with words such as 'fear' or 'mystery' to indicate someone's feelings towards something, as if those feelings were a characteristic of the thing itself.","ex":{"en":"Death doesn't hold any fear for me","cn":"死亡对我来说并不可怕。"}},{"pos":"VERB 动词","cn":"担任（职务）;掌握（权力）;负有（责任）","en":"Hold is used with nouns such as 'office', 'power', and 'responsibility' to indicate that someone has a particular position of power or authority.","ex":{"en":"She has never held ministerial office","cn":"她从未担任过部长级职务。"}},{"pos":"VERB 动词","cn":"持有（许可、票证等）;拥有（学位等）","en":"Hold is used with nouns such as 'permit', 'degree', or 'ticket' to indicate that someone has a particular document that allows them to do something.","ex":{"en":"Applicants should normally hold a good Honours degree","cn":"申请人通常应该拥有优秀荣誉学位。"}},{"pos":"VERB 动词","cn":"举行（聚会、会议、会谈、选举、审判等）","en":"Hold is used with nouns such as 'party', 'meeting', 'talks', 'election', and 'trial' to indicate that people are organizing a particular activity.","ex":{"en":"The country will hold democratic elections within a year","cn":"该国将在一年之内举行民主选举。"}},{"pos":"V-RECIP 相互动词","cn":"进行（谈话、采访、会商等）","en":"Hold is used with nouns such as 'conversation', 'interview', and 'talks' to indicate that two or more people meet and discuss something.","ex":{"en":"The Prime Minister, is holding consultations with his colleagues to finalise the deal","cn":"首相正在和同僚进行磋商，以敲定该协议。"}},{"pos":"VERB 动词","cn":"持有（股份、股票等）","en":"Hold is used with nouns such as 'shares' and 'stock' to indicate that someone owns a particular proportion of a business.","ex":{"en":"The group said it continues to hold 1,774,687 Vons shares","cn":"该集团称其继续持有1,774,687股冯氏公司的股份。"}},{"pos":"VERB 动词","cn":"占有（领先地位、优势等）","en":"Hold is used with words such as 'lead' or 'advantage' to indicate that someone is winning or doing well in a contest.","ex":{"en":"He continued to hold a lead in Angola's presidential race","cn":"他继续在安哥拉总统大选中占据领先地位。"}},{"pos":"VERB 动词","cn":"吸引住（注意力）;保持（兴趣）","en":"Hold is used with nouns such as 'attention' or 'interest' to indicate that what you do or say keeps someone interested or listening to you.","ex":{"en":"If you want to hold someone's attention, look them directly in the eye but don't stare","cn":"如果想吸引住某人的注意力，就要直视他们的眼睛，但别死盯着。"}},{"pos":"VERB 动词","cn":"认定（…负有责任）;归（咎）于","en":"If you hold someone responsible, liable, or accountable for something, you will blame them if anything goes wrong.","ex":{"en":"It's impossible to hold any individual responsible.","cn":"不可能归咎于任何个人。"}},{"pos":"VERB 动词","cn":"关押;扣留","en":"If someone holds you in a place, they keep you there as a prisoner and do not allow you to leave.","ex":{"en":"The inside of a van was as good a place as any to hold a kidnap victim","cn":"小货车内是关押被绑架人的好地方。"}},{"pos":"VERB 动词","cn":"（军队、暴乱人群等）占据，控制","en":"If people such as an army or a violent crowd hold a place, they control it by using force.","ex":{"en":"Demonstrators have been holding the square since Sunday.","cn":"示威者从周日起就占领了广场。"}},{"pos":"N-SING 单数名词","cn":"（因握有某人把柄或掌握权力而形成的）控制力，支配力","en":"If you have a hold over someone, you have power or control over them, for example because you know something about them you can use to threaten them or because you are in a position of authority.","ex":{"en":"It's always useful to have a hold over a fellow like Carl May","cn":"能支配像卡尔·梅这样的人总是很有用的。"}},{"pos":"VERB 动词","cn":"（接电话时让对方）稍等，不要挂断","en":"If you ask someone to hold, or to hold the line, when you are answering a telephone call, you are asking them to wait for a short time, for example so that you can find the person they want to speak to.","ex":{"en":"Could you hold the line and I'll just get my pen","cn":"能否请您稍等一会儿，我拿支笔？"}},{"pos":"VERB 动词","cn":"代接（电话）并向受话人转告通话内容","en":"If you hold telephone calls for someone, you do not allow people who phone to speak to that person, but take messages instead.","ex":{"en":"He tells his secretary to hold his calls.","cn":"他让秘书代接电话。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）保持（在一定价值或水平）","en":"If something holds at a particular value or level, or is held there, it is kept at that value or level.","ex":{"en":"OPEC production is holding at around 21.5 million barrels a day","cn":"石油输出国组织的石油产量保持在每天约2,150万桶。"}},{"pos":"VERB 动词","cn":"持续发出（声音、音符）","en":"If you hold a sound or musical note, you continue making it.","ex":{"en":"...a voice which hit and held every note with perfect ease and clarity.","cn":"非常自如清晰地唱出并拉长每个音符的歌喉"}},{"pos":"VERB 动词","cn":"延迟;推迟","en":"If you hold something such as a train, a lift, or an elevator, you delay it.","ex":{"en":"A London Underground spokesman defended the decision to hold the train until police arrived.","cn":"伦敦地铁公司的发言人为推迟发车直到警方赶来的决定作了辩解。"}},{"pos":"VERB 动词","cn":"（提议、邀请等）有效","en":"If an offer or invitation still holds, it is still available for you to accept.","ex":{"en":"Does your offer still hold?","cn":"你的提议仍然有效吗？"}},{"pos":"VERB 动词","cn":"（好形势）保持不变，持续","en":"If a good situation holds, it continues and does not get worse or fail.","ex":{"en":"Our luck couldn't hold for ever","cn":"我们不会永远走运。"}},{"pos":"VERB 动词","cn":"（论点、理论等）站得住脚，成立","en":"If an argument or theory holds, it is true or valid, even after close examination.","ex":{"en":"Today, most people think that argument no longer holds","cn":"今天，大多数人认为那个论点已经站不住脚了。"}},{"pos":"VERB 动词","cn":"（在重压下）保持不倒，支撑住","en":"If part of a structure holds, it does not fall or break although there is a lot of force or pressure on it.","ex":{"en":"How long would the roof hold?","cn":"房顶能支撑多久？"}},{"pos":"VERB 动词","cn":"（法规等）适用，有效","en":"If laws or rules hold, they exist and remain in force.","ex":{"en":"These laws also hold for universities.","cn":"这些法律也适用于各大学。"}},{"pos":"VERB 动词","cn":"坚持（观点或信念）","en":"If you say that you hold to a particular opinion or belief, you are stating firmly that you continue to have that opinion or belief.","ex":{"en":"I hold to my belief that people should be allowed to have private lives","cn":"我坚信应该允许人们拥有自己的私生活。"}},{"pos":"VERB 动词","cn":"遵守，恪守（承诺或高尚的行为准则）","en":"If you hold to a promise or to high standards of behaviour, you keep that promise or continue to behave according to those standards.","ex":{"en":"Will the President be able to hold to this commit-ment?","cn":"总统能恪守此承诺吗？"}},{"pos":"VERB 动词","cn":"使遵守，使恪守（承诺或高尚的行为准则）","en":"If someone or something holds you to a promise or to high standards of behaviour, they make you keep that promise or those standards.","ex":{"en":"I would say it's almost time to hold him to that promise","cn":"我认为已经差不多是时候让他兑现那个承诺了。"}},{"pos":"PHRASE 短语","cn":"（尤指当众）滔滔不绝地说","en":"If you hold forth on a subject, you speak confidently and for a long time about it, especially to a group of people.","ex":{"en":"Barry was holding forth on politics.","cn":"巴里正在滔滔不绝地谈论政治。"}},{"pos":"PHRASE 短语","cn":"（通常指好不容易）得到，获得","en":"If you get hold of an object or information, you obtain it, usually after some difficulty.","ex":{"en":"It is hard to get hold of guns in this country.","cn":"在这个国家里要搞到枪支是很困难的。"}},{"pos":"PHRASE 短语","cn":"领会;弄懂","en":"If you get hold of a fact or a subject, you learn about it and understand it well.","ex":{"en":"He first had to get hold of some basic facts.","cn":"他首先得弄清一些基本事实。"}},{"pos":"PHRASE 短语","cn":"设法和…取得联络","en":"If you get hold of someone, you manage to contact them.","ex":{"en":"The only electrician we could get hold of was miles away.","cn":"我们唯一能够联络到的电工离这里有好几英里远。"}},{"pos":"CONVENTION 惯用语","cn":"停下;慢着","en":"If you say 'Hold it', you are telling someone to stop what they are doing and to wait.","ex":{"en":"Hold it! Don't move!","cn":"停下！别动！"}},{"pos":"PHRASE 短语","cn":"延迟;暂缓;搁置","en":"If you put something on hold, you decide not to do it, deal with it, or change it now, but to leave it until later.","ex":{"en":"He put his retirement on hold until he had found a solution","cn":"他推迟了退休，直到他找到了解决办法。"}},{"pos":"PHRASE 短语","cn":"（面对攻击、反对等）顶住，坚持住","en":"If you hold your own, you are able to resist someone who is attacking or opposing you.","ex":{"en":"The Frenchman held his own against the challenger.","cn":"这名法国人顶住了挑战者的进攻。"}},{"pos":"PHRASE 短语","cn":"与…相匹敌;不比…逊色","en":"If you can do something well enough to hold your own, you do not appear foolish when you are compared with someone who is generally thought to be very good at it.","ex":{"en":"She can hold her own against almost any player.","cn":"她几乎能和任何一名选手一较高下。"}},{"pos":"PHRASE 短语","cn":"不动","en":"If you hold still, you do not move.","ex":{"en":"Can't you hold still for a second?","cn":"你一秒钟不动都做不到吗？"}},{"pos":"PHRASE 短语","cn":"完全控制;彻底影响","en":"If something takes hold, it gains complete control or influence over a person or thing.","ex":{"en":"She felt a strange excitement taking hold of her","cn":"她浑身感到一股莫名的兴奋。"}},{"pos":"PHRASE 短语","cn":"抓紧;抓牢;扶好（以站稳）","en":"If you hold tight, you put your hand round or against something in order to prevent yourself from falling over. A bus driver might say 'Hold tight!' to you if you are standing on a bus when it is about to move.","ex":{"en":"He held tight to the rope","cn":"他牢牢抓住绳子。"}},{"pos":"PHRASE 短语","cn":"暂不行动","en":"If you hold tight, you do not immediately start a course of action that you have been planning or thinking about.","ex":{"en":"The unions have circulated their branches, urging members to hold tight until a national deal is struck.","cn":"各工会已经在其分支机构中作了宣传工作，敦促会员等到达成全国性协议后再行动。"}},{"pos":"","cn":"","en":"to hold something at bay→see: ; to hold your breath→see: ; can't hold a candle to→see: ; to hold something in check→see: ; to hold court→see: ; to hold fast→see: ; to hold the fort→see: ; what the future holds→see: ; to hold your ground→see: ; to hold your peace→see: ; to hold someone to ransom→see: ; to hold sway→see: ; to hold your tongue→see: ;"},{"pos":"","cn":"","en":"相关词组：hold against hold back hold down hold in hold off hold on hold on to hold out hold over hold together hold up hold with"}]},"examples":[{"en":"Do you think that mixed-ability classes hold back the better students?","cn":"你认为把能力参差的学生混在一班会妨碍高水平学生进步吗？"},{"en":"She held off all the last-minute challengers and won the race in a new record time.","cn":"她最后一刻甩掉了所有对手，以新的纪录赢得了赛跑冠军。"}]},"hotly":{"oxford":{"phon":"ˈhɒtli","pos":"adverb","senses":[{"en":"done in an angry or excited way or with a lot of strong feeling","cn":"愤怒地；激动地；强烈地","ex":{"en":"a hotly debated topic","cn":"激烈辩论的话题"}},{"en":"done with a lot of energy and determination","cn":"起劲地；坚决地","ex":{"en":"hotly contested elections","cn":"竞争激烈的选举"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"激烈地;愤怒地;强烈地","en":"If people discuss, argue, or say something hotly, they speak in a lively or angry way, because they feel strongly.","ex":{"en":"'You're a fool, then,' she said hotly","cn":"“那你就是个笨蛋，”她气冲冲地说。"}},{"pos":"ADV-GRADED 副词","cn":"紧追不放地;穷追不舍地","en":"If you are being hotly pursued, someone is trying hard to catch you and is close behind you.","ex":{"en":"He'd snuck out of America hotly pursued by the CIA.","cn":"在中央情报局的穷追不舍下，他已偷偷溜出了美国。"}}]},"media":{"uk":"media/uk/hotly__gb_1.mp3","us":"media/us/hotly__us_1.mp3"},"examples":[{"en":"Recent reports in the press have been hotly denied.","cn":"新闻界最近的报道遭到了坚决否认。"},{"en":"She ran out of the shop, hotly pursued by the store detective.","cn":"她冲出商店，商店侦探在后面猛追。"}]},"hot":{"media":{"uk":"media/uk/hot__gb_1.mp3","us":"media/us/hot__us_1.mp3"},"oxford":{"phon":"hɒt","pos":"adjective","senses":[{"en":"having a high temperature; producing heat","cn":"温度高的；热的","sc":"temperature","ex":{"en":"It's hot today, isn't it?","cn":"今天很热，对吗？"}},{"en":"feeling heat in an unpleasant or uncomfortable way","cn":"觉得闷（或燥、湿）热","sc":"temperature","ex":{"en":"Is anyone too hot?","cn":"有人觉得太热了吗？"}},{"en":"making you feel hot","cn":"使人感到热的","sc":"temperature","ex":{"en":"London was hot and dusty.","cn":"伦敦很热而且灰尘多。"}},{"en":"containing pepper and spices that can produce a burning feeling in your mouth because they have a strong taste and smell","cn":"辣的；辛辣的","sc":"food with spices","ex":{"en":"hot spicy food","cn":"辛辣的食物"}},{"en":"involving a lot of activity, argument or strong feelings","cn":"活跃的；激烈的；强烈的","sc":"causing strong feelings","ex":{"en":"Today we enter the hottest phase of the election campaign.","cn":"今天我们进入了竞选活动最激烈的阶段。"}},{"en":"difficult or dangerous to deal with and making you feel worried or uncomfortable","cn":"艰难的；棘手的；危险的","sc":"difficult/dangerous","ex":{"en":"When things got too hot most journalists left the area.","cn":"事态发展到过于严峻时，大多数记者便撤离了这个地区。"}},{"en":"new, exciting and very popular","cn":"风行的；风靡一时的；走红的","lab":"informal","sc":"popular","ex":{"en":"This is one of the hottest clubs in town.","cn":"这是市里一家最受欢迎的夜总会。"}},{"en":"fresh, very recent and usually exciting","cn":"最新的，新近的（通常令人兴奋）","sc":"news","ex":{"en":"I've got some hot gossip for you!","cn":"我要告诉你一些最新的传闻！"}},{"en":"likely to be successful","cn":"有望成功的","g":"[only before noun]","sc":"tip/favourite","ex":{"en":"She seems to be the hot favourite for the job.","cn":"她似乎是这份工作最热门的人选。"}},{"en":"very good at doing something; knowing a lot about something","cn":"善于（做某事）；（对某事）了解很多","g":"[not before noun]","lab":"informal","sc":"good at something/knowing a lot","ex":{"en":"Don't ask me—I'm not too hot on British history.","cn":"别问我，我不大了解英国历史。"}},{"en":"if somebody has a hot temper they become angry very easily","cn":"易发怒的；（脾气）暴躁的","sc":"anger"},{"en":"feeling or causing sexual excitement","cn":"感到（或引起）性激动的","sc":"sexual excitement","ex":{"en":"You were as hot for me as I was for you.","cn":"当时你想要我，我也想要你。"}},{"en":"containing scenes, statements, etc. that are of an extreme nature and are likely to shock or anger people","cn":"（场面、言辞等）过激的，过火的","sc":"causing shock/anger","ex":{"en":"Some of the nude scenes were regarded as too hot for Broadway.","cn":"有些裸露场面被认为太过火了，不适合在百老汇上演。"}},{"en":"thinking that something is very important and making sure that it always happens or is done","cn":"重视，确保（某事发生或完成）","g":"[not before noun]","sc":"strict","ex":{"en":"They're very hot on punctuality at work.","cn":"他们很重视工作守时。"}},{"en":"having a strong and exciting rhythm","cn":"节奏强的","sc":"music"},{"en":"stolen and difficult to get rid of because they can easily be recognized","cn":"偷来（因容易识别）而难以销赃的","sc":"goods","ex":{"en":"I'd never have touched those phones if I'd known they were hot.","cn":"早知道那些手机是偷来的，我绝不会碰的。"}},{"en":"used in children’s games to say that the person playing is very close to finding a person or thing, or to guessing the correct answer","cn":"快找到了；快猜中了","g":"[not before noun]","sc":"in children’s games","ex":{"en":"You're getting hot!","cn":"你快猜中了！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热的;烫的","en":"Something that is hot has a high temperature.","ex":{"en":"When the oil is hot, add the sliced onion","cn":"油热了后，放入切好的洋葱。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"天气热的;气温高的;炎热的","en":"Hot is used to describe the weather or the air in a room or building when the temperature is high.","ex":{"en":"It was too hot even for a gentle stroll","cn":"天太热，连慢慢散步都吃不消。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）感觉热的","en":"If you are hot, you feel as if your body is at an unpleasantly high temperature.","ex":{"en":"I was too hot and tired to eat more than a few mouthfuls","cn":"我又热又累，只吃了几口就吃不下了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（温度）…高的","en":"You use hot to talk or ask about how high the temperature of something is.","ex":{"en":"They are called incandescent lights, and their colour depends on how hot they are","cn":"这种灯叫做白炽灯，其颜色取决于温度。"}},{"pos":"ADJ 形容词","cn":"（食物）趁热吃的","en":"Hot food is intended to be eaten as soon as it is cooked, as opposed to food that you eat when it has cooled or that you do not cook at all.","ex":{"en":"If you live alone, you might not want to cook a hot meal every day.","cn":"如果单身居住，你可能不会想每天都做一顿热菜热饭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（食物）辣的，辛辣的","en":"You can say that food is hot when it has a strong, burning taste caused by chillies, pepper, or ginger.","ex":{"en":"...hot curries.","cn":"辛辣的咖喱食品"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（议题、话题）热门的，受到广泛关注的","en":"A hot issue or topic is one that is very important at the present time and is receiving a lot of publicity.","ex":{"en":"The role of women in war has been a hot topic of debate in America since the Gulf conflict.","cn":"自海湾冲突以来，妇女在战争中的作用一直是美国国内一个备受争议的热门话题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（消息）刚发布的，最新的，新近的","en":"Hot news is new, recent, and fresh.","ex":{"en":"...eight pages of the latest movies, video releases and the hot news from Tinseltown.","cn":"有关上档电影、发行影碟及好莱坞最新消息的8页报道"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"风行的;走红的;炙手可热的","en":"You can use hot to describe something that is very exciting and that many people want to see, use, obtain, or become involved with.","ex":{"en":"The hottest show in town was the Monet Exhibition at the Art Institute","cn":"全城最轰动的展览是在美术学院举办的莫奈画展。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（常指非法获得的贵重或知名物品）烫手的，难以销赃的","en":"You can use hot to describe something that no one wants to deal with, often because it has been illegally obtained and is very valuable or famous.","ex":{"en":"If too much publicity is given to the theft of important works, the works will become too hot to handle and be destroyed.","cn":"如果重要作品遭窃一事被大肆报道，这些作品就会因为难以转手而被销毁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情形）棘手的;艰难的的","en":"You can describe a situation that is created by a person's behaviour or attitude as hot when it is unpleasant and difficult to deal with.","ex":{"en":"When the streets get too hot for them, they head south in one stolen car after another.","cn":"当他们觉得在街头混不下去了时，就沿途不断偷车换开，一路往南去了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（比赛）激烈的，双方全力以赴的","en":"A hot contest is one that is intense and involves a great deal of activity and determination.","ex":{"en":"It took hot competition from abroad, however, to show us just how good Scottish cashmere really is.","cn":"然而，我们是通过来自国外的激烈竞争才认识到了苏格兰羊绒的优良品质。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"被看好的;最有望获胜的","en":"If a person or team is the hot favourite, people think that they are the one most likely to win a race or competition.","ex":{"en":"Atlantic City is the hot favourite to stage the fight.","cn":"在大西洋城举行这场拳击比赛是众望所归。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（脾气）暴躁的，易怒的","en":"Someone who has a hot temper gets angry very quickly and easily.","ex":{"en":"His hot temper was making it increasingly difficult for others to work with him.","cn":"他的火暴脾气使得别人越来越难以和他合作。"}},{"pos":"PHRASE 短语","cn":"忽冷忽热;反复无常","en":"If someone blows hot and cold, they keep changing their attitude towards something, sometimes being very enthusiastic and at other times expressing no interest at all.","ex":{"en":"The media, meanwhile, has blown hot and cold on the affair.","cn":"同时，媒体对这件事的态度表现得忽冷忽热。"}},{"pos":"PHRASE 短语","cn":"焦虑不安;六神无主;举止失常","en":"If you are hot and bothered, you are so worried and anxious that you cannot think clearly or behave sensibly.","ex":{"en":"Ray was getting very hot and bothered about the idea.","cn":"这个想法让雷心慌意乱。"}},{"pos":"PHRASE 短语","cn":"对…有强烈的情欲","en":"If you say that one person has the hots for another, you mean that they feel a strong sexual attraction to that person.","ex":{"en":"I've had the hots for him ever since he came to college.","cn":"自从他来上大学后，我就对他春心萌动。"}},{"pos":"","cn":"","en":"相关词组：hot up"}]},"examples":[{"en":"The report was highly critical of senior members of the Cabinet and was considered too hot to publish.","cn":"报道中对内阁高级官员的批评被认为过于激烈，不宜发表。"},{"en":"When things got too hot most journalists left the area.","cn":"事态发展到过于严峻时，大多数记者便撤离了这个地区。"}]},"homogenized":{"media":{"uk":"media/uk/homogenized__gb_1.mp3","us":"media/us/homogenized__us_1.mp3"},"oxford":{"phon":"həˈmɒdʒənaɪzd","pos":"adjective","senses":[{"en":"treated so that the cream is mixed in with the rest","cn":"经过均质处理的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（牛奶）均质的","en":"Homogenized milk is milk where the fat has been broken up so that it is evenly distributed."}]}},"hole":{"oxford":{"phon":"həʊl","pos":"noun","senses":[{"en":"a hollow space in something solid or in the surface of something","cn":"洞；孔；坑","g":"[countable]","sc":"hollow space","ex":{"en":"He dug a deep hole in the garden.","cn":"他在花园里挖了个深坑。"}},{"en":"a space or opening that goes all the way through something","cn":"裂口；开口；孔眼","g":"[countable]","sc":"opening","ex":{"en":"We drilled a hole through the wall.","cn":"我们在墙上钻了一个洞。"}},{"en":"the home of a small animal","cn":"洞穴；巢穴","g":"[countable]","sc":"animal’s home","ex":{"en":"a mouse hole","cn":"鼠洞"}},{"en":"an unpleasant place to live or be in","cn":"糟糕的住所（或处所）","g":"[countable, usually singular]","lab":"informal, disapproving，，","sc":"unpleasant place","ex":{"en":"I am not going to bring up my child in this hole.","cn":"我不会在这个鬼地方养育孩子的。"}},{"en":"a hollow in the ground that you must get the ball into; one of the sections of a golf course with the tee at the beginning and the hole at the end","cn":"球洞；球座到球洞的区域","g":"[countable]","sc":"in golf","ex":{"en":"The ball rolled into the hole and she had won.","cn":"球滚进了洞，她赢了。"}},{"en":"a fault or weakness in something such as a plan, law or story","cn":"（计划、法律或报道等的）错误，缺陷，漏洞","g":"[countable, usually plural]","sc":"fault/weakness","ex":{"en":"I don't believe what she says—her story is full of holes.","cn":"我不相信她的话，她的说法漏洞百出。"}},{"en":"a place or position that needs to be filled because somebody/something is no longer there","cn":"空缺的地方（或位置）","g":"[singular]","sc":"empty place/position","ex":{"en":"After his wife left, there was a gaping hole in his life.","cn":"妻子离开后，他的人生中出现了一大片空洞。"}},{"en":"to make a hole or holes in something, especially a boat or ship","cn":"（尤指在船上）打洞，造成破洞","g":"[transitive, usually passive]","sc":"make a hole","ex":{"en":"The ship had been holed by a missile.","cn":"那艘船被导弹打了个洞。"},"pos":"verb"},{"en":"to hit a golf ball into the hole","cn":"击球入洞","g":"[transitive, intransitive]","sc":"in golf","ex":{"en":"She holed a 25 foot putt.","cn":"她打了一个 25 英尺远的推杆进洞。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"洞;坑;孔眼","en":"A hole is a hollow space in something solid, with an opening on one side.","ex":{"en":"He took a shovel, dug a hole, and buried his once-prized possessions","cn":"他拿起一把铁锨，挖了个坑，将自己曾经珍爱的物品埋了起来。"}},{"pos":"N-COUNT 可数名词","cn":"（贯穿的）孔洞","en":"A hole is an opening in something that goes right through it.","ex":{"en":"These tiresome creatures eat holes in the leaves","cn":"这些讨厌的虫子在叶子上咬出了洞。"}},{"pos":"N-COUNT 可数名词","cn":"(鼠、兔等小动物的）洞穴，窝","en":"A hole is the home or hiding place of a mouse, rabbit, or other small animal.","ex":{"en":"...a rabbit hole.","cn":"兔窝"}},{"pos":"N-COUNT 可数名词","cn":"（法律、理论、论点等的）漏洞，缺陷，破绽","en":"A hole in a law, theory, or argument is a fault or weakness that it has.","ex":{"en":"There were some holes in that theory, some unanswered questions.","cn":"那个理论中有一些漏洞，一些问题没有解答。"}},{"pos":"N-COUNT 可数名词","cn":"糟糕的地方;鬼地方","en":"If you refer to a place as a hole, you are emphasizing that you think it is very unpleasant.","ex":{"en":"Why don't you leave this awful hole and come to live with me?","cn":"你为什么不离开这个破地方，搬过来和我住？"}},{"pos":"N-COUNT 可数名词","cn":"（9洞或18洞高尔夫球场的）球洞（指从球座到球穴的一段区域）","en":"A hole is also one of the nine or eighteen sections of a golf course.","ex":{"en":"I played nine holes with Gary Player today.","cn":"我今天和加里·普莱耶打了9洞高尔夫球。"}},{"pos":"N-COUNT 可数名词","cn":"（高尔夫球场上的）球穴","en":"A hole is one of the places on a golf course that the ball must drop into, usually marked by a flag."},{"pos":"VERB 动词","cn":"（高尔夫球比赛中）击球入穴","en":"If you hole in a game of golf, you hit the ball so that it goes into the hole.","ex":{"en":"He holed from nine feet at the 18th","cn":"他打到第18洞时从9英尺外击球入穴。"}},{"pos":"VERB 动词","cn":"打出破洞于，炸出窟窿于（建筑物、船只等上）","en":"If something such as a building or ship is holed, holes are made in it by guns or other weapons.","ex":{"en":"Blocks of flats have been holed and some shells have fallen within the historic ramparts.","cn":"几栋公寓楼被炸出了窟窿，几枚炮弹还落在了古护城墙内。"}},{"pos":"PHRASE 短语","cn":"绝对不需要","en":"If you say that you need something or someone like a hole in the head, you are emphasizing that you do not want them and that they would only add to the problems that you already have.","ex":{"en":"We need more folk heroes like we need a hole in the head.","cn":"我们绝对不需要有更多的民间英雄了。"}},{"pos":"PHRASE 短语","cn":"置身困境;处境尴尬","en":"If you say that you are in a hole, you mean that you are in a difficult or embarrassing situation.","ex":{"en":"He admitted that the government was in 'a dreadful hole'.","cn":"他承认政府目前“处境极为尴尬”。"}},{"pos":"PHRASE 短语","cn":"（高尔夫球运动中从发球区的）一杆入穴","en":"If you get a hole in one in golf, you get the golf ball into the hole with a single stroke.","ex":{"en":"All they ever dream about is getting a hole in one.","cn":"他们一直梦想着能一杆入穴。"}},{"pos":"PHRASE 短语","cn":"在（论点或理论）中挑毛病","en":"If you pick holes in an argument or theory, you find weak points in it so that it is no longer valid.","ex":{"en":"He then goes on to pick holes in the article before reaching his conclusion.","cn":"他接着在文章中挑了一番刺儿后才作出结论。"}},{"pos":"","cn":"","en":"相关词组：hole up"}]},"media":{"uk":"media/uk/hole__gb_1.mp3","us":"media/us/hole__us_1.mp3"},"examples":[{"en":"We start the current fiscal year $30 million in the hole.","cn":"我们今年的财政年度一开始便负着 3 000 万元的债。"},{"en":"After his wife left, there was a gaping hole in his life.","cn":"妻子离开后，他的人生中出现了一大片空洞。"}]},"hockey":{"oxford":{"phon":"ˈhɒki","pos":"noun","senses":[{"en":"a game played on a field by two teams of 11 players, with curved sticks and a small hard ball. Teams try to hit the ball into the other team’s goal.","cn":"曲棍球","lab":"British English","ex":{"en":"to play hockey","cn":"打曲棍球"}},{"en":"a game played on ice, in which players use long sticks to hit a hard rubber disc (called a puck) into the other team’s goal","cn":"冰球运动；冰上曲棍球","lab":"North American English","ex":{"en":"She plays hockey in the winter.","cn":"她在冬天打冰球。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"曲棍球","en":"Hockey is an outdoor game played between two teams of 11 players who use long curved sticks to hit a small ball and try to score goals.","ex":{"en":"She played hockey for the national side.","cn":"她在国家队打曲棍球。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"冰球;冰上曲棍球","en":"Hockey is a game played on ice between two teams of 11 players who use long curved sticks to hit a small rubber disk, called a puck, and try to score goals."}]},"media":{"img":["media/ldoce/img/hockey.jpg","media/pic/sports_comp.jpg"],"uk":"media/uk/hockey__gb_1.mp3","us":"media/us/hockey__us_1.mp3"},"examples":[{"en":"a hockey stick/player/team","cn":"曲棍球球棍/球员/球队"},{"en":"to play hockey","cn":"打曲棍球"}]},"hoarding":{"media":{"uk":"media/uk/hoarding__gb_1.mp3","us":"media/us/hoarding__us_1.mp3"},"oxford":{"phon":"ˈhɔːdɪŋ","pos":"noun","senses":[{"en":"a large board on the outside of a building or at the side of the road, used for displaying advertisements","cn":"大幅广告牌","g":"[countable]","lab":"British English","ex":{"en":"advertising hoardings","cn":"大幅大幅的广告牌"}},{"en":"a temporary fence made of boards that is placed around an area of land until a building has been built","cn":"（建筑工地用木板搭起的）临时围栏","g":"[countable]","lab":"British English"},{"en":"the act of collecting and keeping large amounts of food, money, etc., often secretly","cn":"（常指偷偷的）贮藏，囤积","g":"[uncountable]","ex":{"en":"Consumer hoarding of limited goods, such as gasoline and paper, is creating shortages in stores.","cn":"消费者囤积汽油和纸张等有限商品，导致商店出现短缺。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（路旁或建筑物侧面的）巨幅广告牌，告示牌","en":"A hoarding is a very large board at the side of a road or on the side of a building, which is used for displaying advertisements and posters.","ex":{"en":"An advertising hoarding on the platform caught her attention.","cn":"站台上的一幅巨幅广告牌吸引了她的注意力。"}}]},"examples":[{"en":"advertising hoardings","cn":"大幅大幅的广告牌"}]},"hope":{"media":{"uk":"media/uk/hope__gb_1.mp3","us":"media/us/hope__us_1.mp3"},"oxford":{"phon":"həʊp","pos":"verb","senses":[{"en":"to want something to happen and think that it is possible","cn":"希望，期望（某事发生）","g":"[intransitive, transitive]","ex":{"en":"All we can do now is wait and hope.","cn":"我们现在所能做的就是等候和期待。"}},{"en":"to intend to do something if possible","cn":"希望，想要（做某事）","g":"[transitive]","ex":{"en":"We're hoping to address all these issues.","cn":"我们希望解决所有这些问题。"}},{"en":"a feeling of wanting and expecting a particular thing to happen; something that you wish for","cn":"希望；愿望","g":"[uncountable, countable]","lab":"North American English","ex":{"en":"Don't lose hope—we'll find her.","cn":"别失去希望，我们会找到她的。"},"pos":"noun"},{"en":"a reason to believe that something good may happen","cn":"有实现的可能；有希望","g":"[uncountable]","ex":{"en":"The future is not without hope.","cn":"未来并非没有希望。"},"pos":"noun"},{"en":"a person, a thing or a situation that will help you get what you want","cn":"被寄予希望的人（或事物、情况）","g":"[countable, usually singular]","ex":{"en":"He turned to her in despair and said, ‘You're my last hope.’","cn":"他绝望地向她求助说：“你是我最后的希望。”"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"希望;期望","en":"If you hope that something is true, or if you hope for something, you want it to be true or to happen, and you usually believe that it is possible or likely.","ex":{"en":"She had decided she must go on as usual, follow her normal routine, and hope and pray","cn":"她打定主意必须像平时一样生活，遵循自己通常的作息规律，同时怀抱希望、虔诚祈祷。"}},{"pos":"VERB 动词","cn":"指望;奢望","en":"If you say that you cannot hope for something, or if you talk about the only thing that you can hope to get, you mean that you are in a bad situation, and there is very little chance of improving it.","ex":{"en":"Things aren't ideal, but that's the best you can hope for","cn":"事情并不理想，但你只能指望这样了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对未来的）希望，期望，指望","en":"Hope is a feeling of desire and expectation that things will go well in the future.","ex":{"en":"Now that he has become President, many people once again have hope for genuine changes in the system","cn":"既然他已当上了总统，很多人又再次看到了进行真正的体制改革的希望。"}},{"pos":"N-COUNT 可数名词","cn":"希望;期望;盼望","en":"If someone wants something to happen, and considers it likely or possible, you can refer to their hopes of that thing, or to their hope that it will happen.","ex":{"en":"They have hopes of increasing trade between the two regions","cn":"他们希望增进两个地区之间的贸易。"}},{"pos":"N-COUNT 可数名词","cn":"被寄予希望的人（或事物）","en":"If you think that the help or success of a particular person or thing will cause you to be successful or to get what you want, you can refer to them as your hope .","ex":{"en":"...England's last hope in the English Open Table Tennis Championships","cn":"英格兰队在英国乒乓球公开锦标赛中的最后希望"}},{"pos":"PHRASE 短语","cn":"从最好的方面想;抱乐观的希望","en":"If you are in a difficult situation and do something and hope for the best, you hope that everything will happen in the way you want, although you know that it may not.","ex":{"en":"I took the risk and hoped for the best","cn":"我冒了这个险，心里祈祷能够诸事顺利。"}},{"pos":"PHRASE 短语","cn":"（不应）抱有很大的希望","en":"If you tell someone not to get their hopes up, or not to build their hopes up, you are warning them that they should not become too confident of progress or success.","ex":{"en":"There is no reason for people to get their hopes up over this mission","cn":"不必对这次行动抱太大希望。"}},{"pos":"PHRASE 短语","cn":"没有一线希望;毫无机会","en":"If you say that someone has not got a hope in hell of doing something, you are emphasizing that they will not be able to do it.","ex":{"en":"Everybody knows they haven't got a hope in hell of forming a government anyway.","cn":"众人皆知他们根本就无力组建政府。"}},{"pos":"PHRASE 短语","cn":"很高期望;很大希望;厚望","en":"If you have high hopes or great hopes that something will happen, you are confident that it will happen.","ex":{"en":"I had high hopes that Derek Randall might play an important part","cn":"我对德里克·兰德尔发挥重要作用寄予厚望。"}},{"pos":"PHRASE 短语","cn":"存一线希望;抱着万分之一的希望","en":"If you hope against hope that something will happen, you hope that it will happen, although it seems impossible.","ex":{"en":"She glanced about the hall, hoping against hope that Richard would be waiting for her.","cn":"她眼睛扫过大厅，对理查德会在那里等她仍怀有一丝希望。"}},{"pos":"PHRASE 短语","cn":"（表示礼貌）我希望，但愿","en":"You use 'I hope' in expressions such as 'I hope you don't mind' and 'I hope I'm not disturbing you', when you are being polite and want to make sure that you have not offended someone or disturbed them.","ex":{"en":"I hope you don't mind me coming to see you","cn":"希望你不介意我来见你。"}},{"pos":"PHRASE 短语","cn":"（表示警告他人不要做愚蠢或危险的事）我希望，但愿","en":"You say 'I hope' when you want to warn someone not to do something foolish or dangerous.","ex":{"en":"You're not trying to see him, I hope?","cn":"但愿你不是想要去见他吧？"}},{"pos":"PHRASE 短语","cn":"（表示更加礼貌和委婉）我希望，我想","en":"You add 'I hope' to what you are saying to make it sound more polite and less rude or less definite.","ex":{"en":"I'm the best man for the job, I hope","cn":"希望我是那份工作的最佳人选。"}},{"pos":"PHRASE 短语","cn":"怀着（…发生的）希望","en":"If you do one thing in the hope of another thing happening, you do it because you think it might cause or help the other thing to happen, which is what you want.","ex":{"en":"He was studying in the hope of being admitted to an engineering college","cn":"他努力学习，希望能被一所工程学院录取。"}},{"pos":"PHRASE 短语","cn":"（在不太可能的情况下）对…继续抱有希望，痴心妄想","en":"If you live in hope that something will happen, you continue to hope that it will happen, although it seems unlikely, and you realize that you are being foolish.","ex":{"en":"I just live in hope that one day she'll talk to me","cn":"我只是妄想着有一天她会和我说话。"}},{"pos":"CONVENTION 惯用语","cn":"毫无希望;绝无可能","en":"If you say 'Some hope', or 'Not a hope', you think there is no possibility that something will happen, although you may want it to happen.","ex":{"en":"The industry reckons it will see orders swell by 10% this financial year. Some hope.","cn":"业界估计本财年订单会增加10%。这绝对不可能。"}}]},"examples":[{"en":"I called early in the hope of catching her before she went to work.","cn":"我很早就打了个电话，希望在她上班之前找到她。"},{"en":"He turned to her in despair and said, ‘You're my last hope. ’","cn":"他绝望地向她求助说：“你是我最后的希望。”"}]},"horn":{"oxford":{"phon":"hɔːn","pos":"noun","senses":[{"en":"a hard pointed part that grows, usually in pairs, on the heads of some animals, such as sheep and cows. Horns are often curved.","cn":"（羊、牛等动物的）角","g":"[countable]","ex":{"en":"a large bull with curved horns","cn":"长着弯曲犄角的大公牛"}},{"en":"the hard substance of which animal horns are made","cn":"角质","g":"[uncountable]","ex":{"en":"ornaments made of rhino horn","cn":"犀牛角制成的装饰品"}},{"en":"a device in a vehicle for making a loud sound as a warning or signal","cn":"（车辆的）喇叭","g":"[countable]","lab":"British English","ex":{"en":"to honk your car horn","cn":"按响汽车喇叭"}},{"en":"a simple musical instrument that consists of a curved metal tube that you blow into","cn":"（乐器）号","g":"[countable]","ex":{"en":"a hunting horn","cn":"猎号"}},{"en":"a brass musical instrument that consists of a long tube curled around in a circle with a wide opening at the end","cn":"（铜管乐器）法国号，圆号","g":"[countable]","lab":"especially British English","ex":{"en":"a horn concerto","cn":"法国号协奏曲"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（汽车等的）喇叭;汽笛;警报器","en":"On a vehicle such as a car, the horn is the device that makes a loud noise as a signal or warning.","ex":{"en":"He sounded the car horn.","cn":"他按响了汽车喇叭。"}},{"pos":"N-COUNT 可数名词","cn":"(牛、鹿等动物的）角","en":"The horns of an animal such as a cow or deer are the hard pointed things that grow from its head.","ex":{"en":"A mature cow has horns.","cn":"成年奶牛有犄角。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"角质","en":"Horn is the hard substance that the horns of animals are made of. Horn is sometimes used to make objects such as spoons, buttons, or ornaments."},{"pos":"N-COUNT 可数名词","cn":"（铜管乐器中的）法国号，圆号","en":"A horn is a musical instrument of the brass family. It is a long circular metal tube, wide at one end, which you play by blowing."},{"pos":"N-COUNT 可数名词","cn":"号（角）（一种简单乐器，由一根金属管组成，一端宽，一端窄）","en":"A horn is a simple musical instrument consisting of a metal tube that is wide at one end and narrow at the other. You play it by blowing into it.","ex":{"en":"...a hunting horn.","cn":"猎号"}},{"pos":"N-COUNT 可数名词","cn":"角状物;喇叭形物","en":"A horn is a hollow curved object that is narrow at one end and wide at the other.","ex":{"en":"...a wind-up gramophone with a big horn.","cn":"带有一个大喇叭形扬声器的发条式留声机"}},{"pos":"PHRASE 短语","cn":"自夸;自吹自擂","en":"If you blow your own horn, you boast about yourself."},{"pos":"PHR-RECIP 相互短语","cn":"争吵;争论","en":"If two people lock horns, they argue about something.","ex":{"en":"During his six years in office, Seidman has often locked horns with lawmakers.","cn":"在任的6年中，塞德曼经常和立法议员争得不可开交。"}},{"pos":"PHRASE 短语","cn":"进退维谷;左右为难","en":"If you are on the horns of a dilemma, you have to choose between two things, both of which are unpleasant or difficult.","ex":{"en":"The bird is caught on the horns of a dilemma. Should it attack the predator, even though it then risks its own life? Or should it get out while the going is good?","cn":"这只鸟进退维谷。是应该冒着生命危险攻击捕食者呢？还是应该及早逃命？"}},{"pos":"PHRASE 短语","cn":"变得谨慎行事；（尤指）紧缩开支","en":"If someone pulls in their horns or draws in their horns, they start behaving more cautiously than they did before, especially by spending less money.","ex":{"en":"Customers are drawing in their horns at a time of high interest rates.","cn":"消费者在高利率时期都在紧缩开支。"}},{"pos":"","cn":"","en":"to take the bull by the horns→see: ;"}]},"media":{"img":["media/pic/mammals_comp.jpg","media/thumb/horn.jpg"],"uk":"media/uk/horn__gb_1.mp3","us":"media/us/horn__us_1.mp3"},"examples":[{"en":"I'm sure she doesn't want us horning in on her business.","cn":"我肯定她不希望我们插手她的事。"},{"en":"( BrE ) to sound/toot your horn","cn":"鸣喇叭"}]},"holy":{"media":{"uk":"media/uk/holy__gb_1.mp3","us":"media/us/holy__us_1.mp3"},"oxford":{"phon":"ˈhəʊli","pos":"adjective","senses":[{"en":"connected with God or a particular religion","cn":"与神（或宗教）有关的；神圣的","g":"[usually before noun]","ex":{"en":"the Holy Bible","cn":"《圣经》"}},{"en":"good in a moral and religious way","cn":"圣洁的","ex":{"en":"a holy life/man","cn":"圣洁的生活／人"}},{"en":"used to emphasize that you are surprised, afraid, etc.","cn":"（强调惊讶、害怕等）","g":"[only before noun]","lab":"informal","ex":{"en":"Holy cow! What was that?","cn":"天哪！那是什么？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"与上帝（或宗教）有关的;神圣的","en":"If you describe something as holy, you mean that it is considered to be special because it is connected with God or a particular religion.","ex":{"en":"To them, as to all Christians, this is a holy place.","cn":"对他们以及所有基督徒来说，这里是一处圣地。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"虔诚的;圣洁的;献身于宗教（或教会）的","en":"A holy person is a religious leader or someone who leads a religious life.","ex":{"en":"The Indians think of him as a holy man, a combination of doctor and priest.","cn":"印度人把他视为圣人，他既是医生又是僧侣。"}},{"pos":"ADJ 形容词","cn":"（表示惊讶、恐慌等）天啊，上帝啊","en":"Holy is used in exclamations such as 'Holy cow!' and 'Holy smoke!' to express an emotion such as surprise or panic."}]},"examples":[{"en":"Holy cow! What was that?","cn":"天哪！那是什么？"},{"en":"a holy war (= one fought to defend the beliefs of a particular religion)","cn":"圣战"}]},"hobbies":{"oxford":{"phon":"ˈhɒbi","pos":"noun","senses":[{"en":"an activity that you do for pleasure when you are not working","cn":"业余爱好"}]},"media":{"img":["media/pic/hobbies_comp.jpg"]}},"honor":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/honor__gb_1.mp3","us":"media/us/honor__us_1.mp3"},"oxford":{"phon":"ˈɒnə(r)","pos":"noun","senses":[{"en":"great respect for somebody","cn":"尊敬；尊重；崇敬","g":"[uncountable]","ex":{"en":"the guest of honor (= the most important one)","cn":"(正餐等的)主客,贵宾"}},{"en":"something that you are very pleased or proud to do because people are showing you great respect","cn":"指荣幸、光荣","g":"[singular]","ex":{"en":"It was a great honor to be invited here today.","cn":"今天承蒙邀请到此，深感荣幸。"}},{"en":"the quality of knowing and doing what is morally right","cn":"正义感；道义；节操","g":"[uncountable]","ex":{"en":"a man of honor","cn":"守信义的人"}},{"en":"a good reputation; respect from other people","cn":"荣誉；名誉；他人的尊敬","g":"[uncountable]","ex":{"en":"upholding the honor of your country","cn":"捍卫祖国的荣誉"}},{"en":"a person or thing that causes others to respect and admire something/somebody","cn":"引起尊敬（或尊重、崇敬）的人（或事物）","g":"[singular]","ex":{"en":"She is an honor to the profession.","cn":"她是这个职业的荣耀。"}},{"en":"an award, official title, etc. given to somebody as a reward for something that they have done","cn":"（为表扬某人的）奖励，荣誉称号，头衔","g":"[countable]","ex":{"en":"to win the highest honor","cn":"赢得最高荣誉"}},{"en":"a university course that is of a higher level than a basic course (in the US also used to describe a class in school that is at a higher level than other classes)","cn":"大学荣誉学位课程；（美国学校的）优等班","g":"[plural]","lab":"North American English","ex":{"en":"an honors degree/course","cn":"荣誉学位／课程"}},{"en":"if you pass an exam or graduate from a university or school with honors, you receive a special grade for having achieved a very high standard","cn":"优异成绩","g":"[plural]"},{"en":"a title of respect used when talking to or about a judge or a US mayor","cn":"法官大人；（美国）市长阁下","g":"[countable]","ex":{"en":"No more questions, Your Honor.","cn":"没有其他问题了，法官大人。"}},{"en":"the cards that have the highest value","cn":"最大点数的牌","g":"[countable, usually plural]"},{"en":"to do something that shows great respect for somebody/something","cn":"尊敬，尊重（某人）","lab":"ironic","sc":"show respect","ex":{"en":"It was a simple ceremony to honor the Goddess of water.","cn":"这是一个简单的仪式，以纪念水之女神。"},"pos":"verb"},{"en":"to give public praise, an award or a title to somebody for something they have done","cn":"给予表扬（或奖励、头衔、称号）","sc":"give award","ex":{"en":"She has never been properly honored in her own country.","cn":"她在自己的国家从未受到过适当的荣誉。"},"pos":"verb"},{"en":"to do what you have agreed or promised to do","cn":"信守，执行（承诺）","lab":"formal","sc":"keep promise","ex":{"en":"I have every intention of honoring our contract.","cn":"我完全愿意执行我们的合约。"},"pos":"verb"}]}},"hormonal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"激素的;荷尔蒙的;有关激素的","en":"Hormonal means relating to or involving hormones.","ex":{"en":"...our individual hormonal balance.","cn":"我们每个人体内的激素平衡"}}]},"media":{"uk":"media/uk/hormonal__gb_1.mp3","us":"media/us/hormonal__us_1.mp3"},"examples":[{"en":"the hormonal changes occurring during pregnancy","cn":"妊娠期间的激素变化"}],"oxford":{"phon":"hɔːˈməʊnl","pos":"adjective","senses":[{"en":"connected with hormones (= chemicals produced in the body or in a plant that influence how cells and tissues function)","cn":"激素的","g":"[usually before noun]","ex":{"en":"the hormonal changes occurring during pregnancy","cn":"妊娠期间的激素变化"}},{"en":"affected by hormone changes in your body in a way that makes you feel emotional","cn":"（因激素的关系而）情绪变化的","lab":"informal","ex":{"en":"I was 14—rebellious, sulky and hormonal.","cn":"那年我 14 岁——叛逆、闷闷不乐、荷尔蒙旺盛。"}}]}},"hobby":{"oxford":{"phon":"ˈhɒbi","pos":"noun","senses":[{"en":"an activity that you do for pleasure when you are not working","cn":"业余爱好","ex":{"en":"Do you have any hobbies?","cn":"你有什么业余爱好吗 ?"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"业余爱好;嗜好","en":"A hobby is an activity that you enjoy doing in your spare time.","ex":{"en":"My hobbies are letter writing, football, music, photography, and tennis.","cn":"我的业余爱好是写信、踢足球、听音乐、玩摄影和打网球。"}}]},"media":{"img":["media/pic/creativehobbies_comp.jpg","media/thumb/model.jpg"],"uk":"media/uk/hobby__gb_1.mp3","us":"media/us/hobby__us_1.mp3"},"examples":[{"en":"I only play jazz as a hobby.","cn":"我弹奏爵士乐只是一种业余爱好。"},{"en":"Her hobbies include swimming and gardening.","cn":"她爱好游泳和园艺。"}]},"hotels":{"oxford":{"phon":"həʊˈtel","pos":"noun","senses":[{"en":"a building where people stay, usually for a short time, paying for their rooms and meals","cn":"旅馆；旅社"},{"en":"( AustralE, NZE ) a pub","cn":"酒吧；酒馆"}]}},"hooks":{"oxford":{"phon":"hʊk","pos":"noun","senses":[{"en":"a curved piece of metal, plastic or wire for hanging things on, catching fish with, etc.","cn":"钩；钓钩；挂钩；鱼钩"},{"en":"a short hard blow that is made with the elbow bent","cn":"钩拳"}]}},"housings":{"oxford":{"phon":"ˈhaʊzɪŋ","pos":"noun","senses":[{"en":"houses, flats/apartments, etc. that people live in, especially when referring to their type, price or condition （","cn":"统称，尤指住房类型、价格、条件）住房，住宅"},{"en":"the job of providing houses, flats/apartments, etc. for people to live in","cn":"住房供给"}]}},"housemaids":{"oxford":{"phon":"ˈhaʊsmeɪd","pos":"noun","senses":[{"en":"a female servant in a large house who cleans the rooms, etc. and often lives there （","cn":"家庭的）女仆，女佣"}]}},"housewives":{"oxford":{"phon":"ˈhaʊswaɪf","pos":"noun","senses":[{"en":"a woman who stays at home to cook, clean, take care of the children, etc. while her husband or partner goes out to work","cn":"主妇；家庭妇女"}]}},"honed":{"oxford":{"phon":"həʊn","pos":"verb","senses":[{"en":"to develop and improve sth, especially a skill, over a period of time","cn":"磨练，训练（尤指技艺）"},{"en":"to make a blade sharp or sharper","cn":"磨（刀）；把（刀）磨快"}]}},"households":{"oxford":{"phon":"ˈhaʊshəʊld","pos":"noun","senses":[{"en":"all the people living together in a house or flat/apartment","cn":"一家人；家庭；同住一所（或一套）房子的人"}]}},"houses":{"oxford":{"phon":"haʊs","pos":"noun","senses":[{"en":"a building for people to live in, usually for one family","cn":"房屋；房子；住宅"},{"en":"all the people living in a house","cn":"住在一所房子里的人；全家人"}]}},"hoping":{"oxford":{"phon":"həʊp","pos":"verb","senses":[{"en":"to want sth to happen and think that it is possible","cn":"希望，期望（某事发生）"},{"en":"Hope can be used in the passive in the form it is hoped that … . For must always be used with hope in other passive sentences. * hope","cn":"可用于 it is hoped that ... 这一句型的被动句，其他被动句中 hope 必须与 for 连用"}]}},"holidaymakers":{"oxford":{"phon":"ˈhɒlədeɪmeɪkə(r)","pos":"noun","senses":[{"en":"a person who is visiting a place on holiday/vacation","cn":"度假者"}]}},"hoped":{"oxford":{"phon":"həʊp","pos":"verb","senses":[{"en":"to want sth to happen and think that it is possible","cn":"希望，期望（某事发生）"},{"en":"Hope can be used in the passive in the form it is hoped that … . For must always be used with hope in other passive sentences. * hope","cn":"可用于 it is hoped that ... 这一句型的被动句，其他被动句中 hope 必须与 for 连用"}]}},"horizons":{"oxford":{"phon":"həˈraɪzn","pos":"noun","senses":[{"en":"the furthest that you can see, where the sky seems to meet the land or the sea","cn":"地平线"},{"en":"the limit of your desires, knowledge or interests （","cn":"欲望、知识或兴趣的）范围，眼界"}]}},"holidays":{"oxford":{"phon":"ˈhɒlədeɪ","pos":"noun","senses":[{"en":"a period of time when you are not at work or school","cn":"假期"},{"en":"a period of time spent travelling or resting away from home （","cn":"外出旅游或休闲的）度假"}]}},"hopes":{"oxford":{"phon":"həʊp","pos":"verb","senses":[{"en":"to want sth to happen and think that it is possible","cn":"希望，期望（某事发生）"},{"en":"Hope can be used in the passive in the form it is hoped that … . For must always be used with hope in other passive sentences. * hope","cn":"可用于 it is hoped that ... 这一句型的被动句，其他被动句中 hope 必须与 for 连用"}]}},"holidaying":{"oxford":{"phon":"ˈhɒlədeɪ","pos":"noun","senses":[{"en":"a period of time when you are not at work or school","cn":"假期"},{"en":"a period of time spent travelling or resting away from home （","cn":"外出旅游或休闲的）度假"}]}},"hours":{"oxford":{"phon":"ˈaʊə(r)","pos":"noun","senses":[{"en":"60 minutes; one of the 24 parts that a day is divided into","cn":"小时"},{"en":"a period of about an hour, used for a particular purpose","cn":"约一小时的时间"}]}},"horrors":{"oxford":{"phon":"ˈhɒrə(r)","pos":"noun","senses":[{"en":"a feeling of great shock, fear or disgust","cn":"震惊；恐惧；厌恶"},{"en":"a great fear or hatred of sth","cn":"对某事物的强烈畏惧（或憎恨）"}]}},"homes":{"oxford":{"phon":"həʊm","pos":"noun","senses":[{"en":"the house or flat/apartment that you live in, especially with your family","cn":"家；住所"},{"en":"a house or flat/apartment, etc., when you think of it as property that can be bought and sold （","cn":"可买卖的）房子，住宅，寓所"}]},"media":{"img":["media/pic/homes_comp.jpg"]}},"holds":{"oxford":{"phon":"həʊld","pos":"verb","senses":[{"en":"to carry sth; to have sb/sth in your hand, arms, etc.","cn":"拿着；抓住；抱住；托住；夹着"},{"en":"to put your hand on part of your body, usually because it hurts","cn":"抱住，捂住，按住（受伤的身体部位等）"}]}},"hospitals":{"oxford":{"phon":"ˈhɒspɪtl","pos":"noun","senses":[{"en":"a large building where people who are ill/sick or injured are given medical treatment and care","cn":"医院："}]}},"horses":{"oxford":{"phon":"hɔːs","pos":"noun","senses":[{"en":"a large animal with four legs, a mane (= long thick hair on its neck) and a tail. Horses are used for riding on, pulling carriages , etc.","cn":"马"},{"en":"( informal ) horse racing","cn":"赛马"}]}},"hogging":{"oxford":{"phon":"hɒɡ","pos":"noun","senses":[{"en":"( especially NAmE ) a pig, especially one that is kept and made fat for eating （","cn":"尤指喂肥供食用的）猪"},{"en":"( BrE ) a male pig that has been castrated (= had part of its sex organs removed) and is kept for its meat （","cn":"供食用的）阉公猪"}]}},"homemakers":{"oxford":{"phon":"ˈhəʊmmeɪkə(r)","pos":"noun","senses":[{"en":"a person who works at home and takes care of the house and family","cn":"料理家务者；操持家务者"}]}},"honorable":{"oxford":{"phon":"ˈɒnərəbl","pos":"adjective","senses":[{"en":"deserving great respect","cn":"可敬的；值得钦佩的"},{"en":"showing high moral standards","cn":"品格高尚的"},{"en":"allowing somebody to keep their good name and the respect of others","cn":"保护声誉的；体面的"},{"en":"a title of respect used for an official of high rank","cn":"（高级官员的尊称）","g":"[only before noun]"}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdehonorable.mp3","us":"media/ldoce/hwd/ame/1/laadhonorable.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"howl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（狼、狗等）长嚎，嗥叫","en":"If an animal such as a wolf or a dog howls, it makes a long, loud, crying sound.","ex":{"en":"Somewhere in the streets beyond a dog suddenly howled, baying at the moon.","cn":"远处的街上，有只狗突然对月长嚎起来。"}},{"pos":"VERB 动词","cn":"（人因疼痛、愤怒、愁苦而）吼叫，嚎哭，哀号","en":"If a person howls, they make a long, loud cry expressing pain, anger, or unhappiness.","ex":{"en":"He howled like a wounded animal as blood spurted from the gash","cn":"当血从伤口中喷出时，他像一只受伤的动物一样嚎叫起来。"}},{"pos":"VERB 动词","cn":"（风）呼啸，怒号","en":"When the wind howls, it blows hard and makes a loud noise.","ex":{"en":"The wind howled all night, but I slept a little","cn":"风整夜怒号着，但我还是睡了一会儿。"}},{"pos":"VERB 动词","cn":"（人）高声嚷，大声呼叫","en":"If you howl something, you say it in a very loud voice.","ex":{"en":"'Get away, get away, get away' he howled","cn":"“滚开，滚开，都滚开”他高声嚷道。"}},{"pos":"VERB 动词","cn":"放声（大笑）","en":"If you howl with laughter, you laugh very loudly.","ex":{"en":"Joe, Pink, and Booker howled with delight","cn":"乔、平克和布克高兴得放声大笑。"}},{"pos":"","cn":"","en":"相关词组：howl down"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to laugh very loudly because you think something is very funny","cn":""},{"en":"to suddenly laugh loudly because you think a situation, someone's words, something you are reading etc is very funny","cn":""},{"en":"to laugh loudly and unpleasantly in a high voice, like someone who is mad","cn":""}]},"collocations":{"phrases":["ADJ. deep | mournful The dog gave a mournful howl.","VERB + HOWL give, let out | hear","PREP. with a ~ With a howl he leapt at his foe. | ~ of a howl of laughter/protest","PHRASES be greeted/met with howls of sth His comments were met with howls of outrage. | the howl of the wind/a wolf, howls of laughter, howl"]},"media":{"uk":"media/ldoce/hwd/bre/a/howl_n0205.mp3","us":"media/ldoce/hwd/ame/0/howl1.mp3"},"examples":[{"en":"The baby was howling (= crying loudly) all the time I was there.","cn":"我在那里时孩子一直哭得很厉害。"},{"en":"They listened to the howl of the wind through the trees.","cn":"他们听着风在林间呼啸的声音。"}],"oxford":{"phon":"haʊl","pos":"verb","senses":[{"en":"to make a long, loud call","cn":"长嚎；嗥叫","g":"[intransitive]","ex":{"en":"the sound of wolves howling in the night","cn":"夜里狼嚎的声音"}},{"en":"to make a loud noise when you are angry, in pain, etc. or you find something funny","cn":"（因愤怒、疼痛、开心等）大声叫喊，吼","g":"[intransitive]","ex":{"en":"The child howled in pain.","cn":"那孩子疼得直叫。"}},{"en":"to blow hard and make a long loud noise","cn":"怒号；呼啸","g":"[intransitive]","ex":{"en":"The wind was howling around the house.","cn":"狂风在房子四周呼啸。"}},{"en":"to say something loudly and angrily","cn":"怒吼","g":"[transitive]","ex":{"en":"The crowd howled its displeasure.","cn":"群众不满地怒吼着。"}},{"en":"a long loud call made by a dog, wolf, etc.","cn":"（狗、狼等的）嗥叫，长嚎","ex":{"en":"the mournful howl of a lone dog","cn":"一只孤独的狗的哀嚎"},"pos":"noun"},{"en":"a loud noise showing that you are angry, in pain, etc. or you find something funny","cn":"（因愤怒、疼痛、开心等发出的）喊叫声，吼叫","ex":{"en":"to let out a howl of anguish","cn":"发出痛苦的喊叫声"},"pos":"noun"},{"en":"a long loud sound made when the wind is blowing strongly","cn":"（狂风的）啸鸣，怒号","ex":{"en":"They listened to the howl of the wind through the trees.","cn":"他们听着风在林间呼啸的声音。"},"pos":"noun"}]}},"homeless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无家可归的","en":"Homeless people have nowhere to live.","ex":{"en":"...the growing number of homeless families","cn":"越来越多的居无定所家庭"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having no home to live in, especially because you are very poor or have been forced to leave your old home","cn":""},{"en":"to sleep outdoors in a city because you do not have anywhere to live","cn":""},{"en":"someone who has no home or regular work","cn":""}]},"collocations":{"phrases":["VERBS be | become, end up, find yourself He found himself homeless after his marriage broke up. | leave sb, make sb, render sb Three hundred","ADV. officially | intentionally, voluntarily The local authority ruled that he had made himself intentionally homeless and was therefore not"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdehomeless.mp3","us":"media/ldoce/hwd/ame/b/homeless.mp3"},"examples":[{"en":"The scheme has been set up to help homeless people.","cn":"这个计划的目的是帮助无家可归的人。"},{"en":"helping the homeless","cn":"帮助无家可归者"}],"oxford":{"phon":"ˈhəʊmləs","pos":"adjective","senses":[{"en":"having no home, and therefore typically living on the streets","cn":"无家可归的；露宿街头的","ex":{"en":"The scheme has been set up to help homeless people.","cn":"这个计划的目的是帮助无家可归的人。"}},{"en":"people who have no home","cn":"无家可归的人们","g":"[plural]","ex":{"en":"helping the homeless","cn":"帮助无家可归者"}}]}},"hoarse":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（嗓音）嘶哑的，粗哑的","en":"If your voice is hoarse or if you are hoarse, your voice sounds rough and unclear, for example because your throat is sore.","ex":{"en":"'So what do you think?' she said in a hoarse whisper","cn":"“那么你认为如何？”她声音嘶哑地悄声问道。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not sounding soft or gentle, especially because the person speaking is angry or rude","cn":""},{"en":"deep and rough, as if the sounds are produced deep down in your throat","cn":""},{"en":"slightly rough, as though you have a sore throat, but also attractive and deep","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A hoarse voice is deep and rough and kind of hard to make out. People get hoarse when they're sick, or when they are calling in sick to work."}]},"collocations":{"phrases":["VERBS be, sound | become, get, go | leave sb, make sb/sth, scream yourself, shout yourself All the shouting had left her rather hoarse. Exci","ADV. extremely, very | rather, slightly","PREP. from Her voice was hoarse from shouting. | with His voice was hoarse with anxiety."]},"media":{"uk":"media/ldoce/hwd/bre/1/hoarse0205.mp3","us":"media/ldoce/hwd/ame/6/hoarse.mp3"},"examples":[{"en":"He shouted himself hoarse.","cn":"他把嗓子喊哑了。"},{"en":"a hoarse cough/cry/scream","cn":"粗哑的咳嗽；嘶哑的哭声/尖叫声"}],"oxford":{"phon":"hɔːs","pos":"adjective","senses":[{"en":"if a person or their voice is hoarse, their voice sounds rough and unpleasant, especially because of a sore throat (= a painful throat because of an infection)","cn":"嘶哑的；沙哑的","ex":{"en":"He shouted himself hoarse.","cn":"他把嗓子喊哑了。"}}]}},"hostility":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"敌意;对抗;敌对行为","en":"Hostility is unfriendly or aggressive behaviour towards people or ideas.","ex":{"en":"The last decade has witnessed a serious rise in the levels of racism and hostility to Black and ethnic groups","cn":"过去十年里，对黑人及少数族裔的种族歧视和敌对行为变得日益猖獗。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"反对;抵制","en":"Your hostility to something you do not approve of is your opposition to it.","ex":{"en":"There is hostility among traditionalists to this method of teaching history.","cn":"传统主义者反对这种讲授历史的方法。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"strong disagreement with or protest against something","cn":""},{"en":"a reason you give for opposing an idea or plan","cn":""},{"en":"a strong feeling of opposition to something, or dislike for someone, which is shown in your behaviour, and has often existed for a long time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Hostility is the state of ill will and bad feeling. If a teacher embarrasses you in front of the whole class, you will probably regard him or her with hostility for the remainder of the school year."}]},"collocations":{"phrases":["ADJ. bitter, considerable, deep, extreme, great, implacable | downright, open, outright Mixed-race couples faced open hostility. | veiled Th","VERB + HOSTILITY feel the deep hostility felt by many teenagers against the police | express, show | arouse, attract, provoke The prime mini","PREP. ~ between You could almost feel the hostility between her and her mother. | ~ against/to/towards the bitter hostility towards the occu","VERB + HOSTILITY cease, end, suspend Both sides finally agreed to suspend hostilities. | resume Hostilities were resumed later that year.","HOSTILITY + VERB begin, break out | cease, end On the 11th of November 1918 hostilities ceased. | resume","PREP. ~ against the beginning of hostilities against Germany in 1914 | ~ between Hostilities broke out between the two provinces later that ","PHRASES the cessation of hostilities, an outbreak of hostilities"]},"media":{"uk":"media/ldoce/hwd/bre/7/hostility0205.mp3","us":"media/ldoce/hwd/ame/2/hostility.mp3"},"examples":[{"en":"feelings of hostility towards people from other backgrounds","cn":"对其他不同背景的人的敌视情绪"},{"en":"There was open hostility between the two schools.","cn":"这两所学校公开相互敌对。"}],"oxford":{"phon":"hɒˈstɪləti","pos":"noun","senses":[{"en":"aggressive or unfriendly feelings or behaviour","cn":"敌意；对抗","g":"[uncountable]","ex":{"en":"There was a barely veiled hostility in her tone.","cn":"她语气中带着几乎未加掩饰的敌意。"}},{"en":"strong and angry opposition towards an idea, a plan or a situation","cn":"（对思想、计划或情形的）愤怒反对，愤怒反抗","g":"[uncountable]","ex":{"en":"The proposal was met with outright hostility.","cn":"提议遭到公然反对。"}},{"en":"acts of fighting in a war","cn":"战争行为","g":"[plural]","lab":"formal","ex":{"en":"the start/outbreak of hostilities between the two sides","cn":"双方之间敌对行为的爆发"}}]}},"homicide":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"凶杀;杀人","en":"Homicide is the illegal killing of a person.","ex":{"en":"The police arrived at the scene of the homicide.","cn":"警方赶到了凶杀现场。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of physically attacking someone","cn":""},{"en":"the crime of attacking and robbing someone in a public place","cn":""},{"en":"the crime of deliberately killing someone","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The noun homicide means a murder. If you kill another person, you are committing a homicide . The level of the homicide is legally defined as murder if the act was intentional, and \"manslaughter\" if it was unintentional."}]},"collocations":{"phrases":["ADJ. criminal, culpable, unlawful | justifiable The jury returned a verdict of justifiable homicide. • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/9/homicide0205.mp3","us":"media/ldoce/hwd/ame/f/homicide.mp3"},"oxford":{"phon":"ˈhɒmɪsaɪd","pos":"noun","senses":[{"en":"the act of killing another person, especially when it is a crime","cn":"（蓄意）杀人罪","ex":{"en":"He has been arrested on homicide and assault charges.","cn":"他因杀人和侵犯他人身体的指控被逮捕。"}}]}},"hound":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"猎犬;赛犬","en":"A hound is a type of dog that is often used for hunting or racing.","ex":{"en":"Rainey's chief interest in life is hunting with hounds.","cn":"雷尼生活的最大爱好就是带着猎狗去打猎。"}},{"pos":"VERB 动词","cn":"（不断地）烦扰，叨唠，纠缠","en":"If someone hounds you, they constantly disturb or speak to you in an annoying or upsetting way.","ex":{"en":"Newcomers are constantly hounding them for advice","cn":"新人总是一刻不停地缠着向他们讨教。"}},{"pos":"VERB 动词","cn":"（常指通过不断批评而）逼迫（某人辞职或离开某地）","en":"If someone is hounded out of a job or place, they are forced to leave it, often because other people are constantly criticizing them.","ex":{"en":"There is a general view around that he has been hounded out of office by the press.","cn":"人们普遍认为他不堪舆论压力被迫离职。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a dog that is fast and has a good sense of smell, used for hunting","cn":"猎犬"},{"en":"a dog","cn":"狗"},{"en":"if someone such as a police officer tails someone, they secretly follow that person to find out where they are going or what they are doing","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A hound is a type of dog with big floppy ears, mainly used for hunting. To hound someone is to relentlessly pursue or pester them. When Elvis sings, “You ain’t nothing but a hound dog,” he’s referring to both."}]},"collocations":{"phrases":["ADJ. hunting","QUANT. pack","HOUND + VERB bark, bay We could hear the hounds barking at the fox. | pick up the scent The hounds picked up the scent of the fox. | chase s","PHRASES ride to hounds Days off were spent riding to hounds (= hunting) ."]},"media":{"uk":"media/ldoce/hwd/bre/b/hound_n0205.mp3","us":"media/ldoce/hwd/ame/1/hound1.mp3"},"examples":[{"en":"They were hounded day and night by the press.","cn":"他们日夜遭到新闻界的跟踪。"},{"en":"After the court case, Lee was hounded relentlessly by the press.","cn":"案件审结后﹐李不断受到新闻界的骚扰。"}],"oxford":{"phon":"haʊnd","pos":"noun","senses":[{"en":"a dog that can run fast and has a good sense of smell, used for hunting","cn":"猎犬；猎狗","ex":{"en":"The hounds picked up the scent of the fox.","cn":"猎狗嗅到了那只狐狸的气味。"}},{"en":"to keep following somebody and not leave them alone, especially in order to get something from them or ask them questions","cn":"追踪；追逐；纠缠","ex":{"en":"They were hounded day and night by the press.","cn":"他们日夜遭到新闻界的跟踪。"},"pos":"verb"}]}},"homesick":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"想家的;思乡的","en":"If you are homesick, you feel unhappy because you are away from home and are missing your family, friends, and home very much.","ex":{"en":"She's feeling a little homesick.","cn":"她有点想家。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not happy","cn":""},{"en":"sad, especially for a long time – used about people and periods of time","cn":""},{"en":"sad because you are away from your home, family, and friends","cn":""}]},"collocations":{"phrases":["VERBS be, feel | become, get | make sb Seeing other families together made him terribly homesick.","ADV. desperately, terribly, very | a bit, a little"]},"media":{"uk":"media/ldoce/hwd/bre/7/homesick0205.mp3","us":"media/ldoce/hwd/ame/2/homesick.mp3"},"examples":[{"en":"I felt homesick for Scotland.","cn":"我思念故乡苏格兰。"}],"oxford":{"phon":"ˈhəʊmsɪk","pos":"adjective","senses":[{"en":"sad because you are away from home and you miss your family and friends","cn":"思乡的；想家的；患怀乡病的","ex":{"en":"I felt homesick for Scotland.","cn":"我思念故乡苏格兰。"}}]}},"hormone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"激素;荷尔蒙","en":"A hormone is a chemical, usually occurring naturally in your body, that makes an organ of your body do something."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical substance produced by your body that influences its growth, development, and condition","cn":"激素﹐荷尔蒙"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun hormone to describe a message-sending chemical sent out by glands in the human body, which make you hungry or moody or ready to fight."}]},"collocations":{"phrases":["ADJ. female, male | growth, sex children who do not produce enough growth hormone","VERB + HORMONE produce, release, secrete Hormones are secreted into the bloodstream.","HORMONE + NOUN production | replacement therapy, treatment | deficiency, imbalance | balance, level"]},"media":{"uk":"media/ldoce/hwd/bre/c/hormone0205.mp3","us":"media/ldoce/hwd/ame/f/hormone.mp3"},"examples":[{"en":"Oestrogen is a female sex hormone.","cn":"雌激素是一种雌性荷尔蒙。"},{"en":"the hormonal changes occurring during pregnancy","cn":"妊娠期间的激素变化"}],"oxford":{"phon":"ˈhɔːməʊn","pos":"noun","senses":[{"en":"a chemical substance produced in the body or in a plant that encourages growth or influences how the cells and tissues function; an artificial substance that has similar effects","cn":"激素；荷尔蒙","ex":{"en":"growth hormones","cn":"生长激素"}}]}},"honourable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）值得尊敬的，正直的;（行为）光荣的，体面的","en":"If you describe people or actions as honourable, you mean that they are good and deserve to be respected and admired.","ex":{"en":"I believe he was an honourable man, dedicated to the people and his union","cn":"我认为他是个品行高洁的人，一心奉献于人民和工会的事业。"}},{"pos":"ADJ 形容词","cn":"（用于某些贵族和法官等官员名字前的尊称）尊敬的，阁下","en":"Honourable is used as a title before the names of some members of the nobility, judges, and some other officials.","ex":{"en":"...the Honourable Mr Justice Swinton Thomas.","cn":"尊敬的斯温顿·托马斯法官先生"}},{"pos":"ADJ 形容词","cn":"（英国议会辩论时议员彼此间的尊称）尊敬的，阁下","en":"In debates in the British parliament, one member of parliament refers to another as the honourable member, the honourable gentleman, the honourable lady, or their honourable friend.","ex":{"en":"...the Honourable Member for Billericay.","cn":"比勒里基区的议员阁下"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"morally correct","cn":""},{"en":"morally correct, especially according to a set of ideas about how people should behave in a particular profession","cn":""},{"en":"fair, honest, or kind","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. very a very honourable man | completely, entirely, perfectly My intentions were perfectly honourable."]},"media":{"uk":"media/ldoce/hwd/bre/7/honourable0205.mp3","us":"media/ldoce/hwd/ame/4/honorable.mp3"},"examples":[{"en":"With a few honourable exceptions, the staff were found to be incompetent.","cn":"除了几个优秀的人以外，其他职员都不能胜任工作。"},{"en":"They managed an honourable 2–2 draw.","cn":"他们奋力打成了 2:2 平局，值得敬佩。"}],"oxford":{"phon":"ˈɒnərəbl","pos":"adjective","senses":[{"en":"deserving great respect","cn":"可敬的；值得钦佩的","ex":{"en":"She had a long and honourable career in government.","cn":"她从政时间长，且名声清白。"}},{"en":"showing high moral standards","cn":"品格高尚的","ex":{"en":"He was an honourable man who could not lie.","cn":"他是个高尚的人，不会说谎。"}},{"en":"allowing somebody to keep their good name and the respect of others","cn":"保护声誉的；体面的","ex":{"en":"an honourable compromise","cn":"体面的妥协"}},{"en":"(in the UK) a title used by a child of some ranks of the nobility","cn":"（英国某些贵族子女的头衔）","g":"[only before noun]"},{"en":"(in the UK) a title used by Members of Parliament when talking about or to another Member during a debate","cn":"（英国议会议员辩论时相互间的尊称）","g":"[only before noun]","ex":{"en":"If my Honourable Friend would give me a chance to answer,…","cn":"如果尊敬的阁下能给我答辩的机会…"}},{"en":"a title of respect used for an official of high rank","cn":"（高级官员的尊称）","g":"[only before noun]","ex":{"en":"the Honorable Alan Simpson, US senator","cn":"美国参议员艾伦·辛普森"}}]}},"hoard":{"collins":{"senses":[{"pos":"VERB 动词","cn":"贮藏;囤积","en":"If you hoard things such as food or money, you save or store them, often in secret, because they are valuable or important to you.","ex":{"en":"They've begun to hoard food and gasoline and save their money","cn":"他们已经存钱并开始贮藏食物和汽油。"}},{"pos":"N-COUNT 可数名词","cn":"贮藏物;隐藏物;收藏物","en":"A hoard is a store of things that you have saved and that are valuable or important to you or you do not want other people to have.","ex":{"en":"The case involves a hoard of silver and jewels valued at up to $40m.","cn":"此案涉及密藏的一批价值高达4,000万美元的银子和珠宝。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large quantity of something that you keep, and that you replace regularly because you use it often","cn":""},{"en":"the amount of a particular product that a shop keeps to be sold","cn":""},{"en":"something such as money, food, or water that you keep because you might need it in the future","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To hoard is to save something (or lots of things) for future use. Squirrels hoard nuts for the winter. Old ladies tend to hoard canned food and used plastic bags."}]},"collocations":{"phrases":["ADJ. big, large, major, vast one of the biggest hoards of Roman coins ever found | small | secret her secret hoard of food","PREP. in ~s Gold coins have been found in hoards in many parts of the country. | ~ of a vast hoard of treasure"]},"media":{"uk":"media/ldoce/hwd/bre/0/hoard_las2_br.mp3","us":"media/ldoce/hwd/ame/3/hoard1.mp3"},"examples":[{"en":"the discovery of a hoard of gold coins","cn":"一批秘藏金币的发现"},{"en":"families who hoarded food during the strike","cn":"罢工期间囤积食品的家庭"}],"oxford":{"phon":"hɔːd","pos":"noun","senses":[{"en":"a collection of money, food, valuable objects, etc., especially one that somebody keeps in a secret place so that other people will not find or steal it","cn":"（钱、食物、贵重物品等的）贮存，聚藏；（尤指）秘藏","ex":{"en":"They dug up a hoard of Roman coins.","cn":"他们挖出一批秘藏的古罗马硬币。"}},{"en":"to collect and keep large amounts of food, money, etc., often secretly","cn":"（常指偷偷地）贮藏，囤积","ex":{"en":"The prisoners used to hoard scraps of food in secret places.","cn":"过去囚犯常把残羹剩饭存放在隐秘的地方。"},"pos":"verb"}]}},"horoscope":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"星象（指某人诞生时各天体的位置，用以占卜命运）","en":"Your horoscope is a prediction of events which some people believe will happen to you in the future. Horoscopes are based on the position of the stars when you were born."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of the positions and movements of the stars and how they might influence people and events","cn":""},{"en":"a description of people’s characters and the things that will happen to them, based on the position of the stars and planets at the time of their birth – especially a description that is printed in a newspaper or magazine","cn":""},{"en":"the twelve signs that you can belong to according to your birth date and the position of the stars then, which some people believe influence our characters and our lives","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"You can usually read your daily horoscope in the local newspaper. A horoscope is a forecast of your future based on the month in which you were born."}]},"collocations":{"phrases":["VERB + HOROSCOPE cast, draw up To draw up someone's horoscope, you need to know their date and exact time of birth. | consult, read | believ","HOROSCOPE + VERB say sth What does your horoscope say?"]},"media":{"uk":"media/ldoce/hwd/bre/e/horoscope0205.mp3","us":"media/ldoce/hwd/ame/c/horoscope.mp3"},"oxford":{"phon":"ˈhɒrəskəʊp","pos":"noun","senses":[{"en":"a prediction of what is going to happen to somebody in the future, based on the position of the stars and the planets when the person was born","cn":"占星术","ex":{"en":"Do you believe in horoscopes?","cn":"你相信占星术吗？"}}]}},"hoax":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"恶作剧;假警报;骗局","en":"A hoax is a trick in which someone tells people a lie, for example that there is a bomb somewhere when there is not, or that a picture is genuine when it is not.","ex":{"en":"A series of bomb hoaxes has disrupted Christmas shopping in the city centre","cn":"一系列炸弹假警报扰乱了市中心的圣诞节购物活动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a clever plan designed to make someone believe something that you want them to believe, or do something that you want them to do","cn":""},{"en":"a clever plan designed to harm someone, for example by making them go somewhere where they will be caught or attacked, or making them say something they will be punished for","cn":""},{"en":"something that is said or done with the deliberate intention of deceiving people","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you put on big fake feet, stomp through your muddy backyard and tell everyone you saw Bigfoot fixing a steak on your grill, you are playing a hoax on your friends."}]},"collocations":{"phrases":["ADJ. elaborate It turned out to be an elaborate hoax. | cruel He described the deception as a cruel hoax. | bomb","VERB + HOAX perpetrate, play, stage a hoax perpetrated by the British government","HOAX + NOUN call, caller","PREP. ~ on The organizers staged a hoax on some of the competitors."]},"media":{"uk":"media/ldoce/hwd/bre/7/hoax0205.mp3","us":"media/ldoce/hwd/ame/2/hoax1.mp3"},"examples":[{"en":"hoax calls","cn":"恶作剧的电话"},{"en":"a bomb hoax","cn":"炸弹骗局"}],"oxford":{"phon":"həʊks","pos":"noun","senses":[{"en":"an act intended to make somebody believe something that is not true, especially something unpleasant","cn":"骗局；恶作剧","ex":{"en":"He was accused of using a bomb hoax to empty a rival restaurant.","cn":"他被控谎称有炸弹以吓跑一家对手餐厅的食客。"}},{"en":"to trick somebody by making them believe something that is not true, especially something unpleasant","cn":"作弄；欺骗","ex":{"en":"He hoaxed us by sending a friend instead of coming himself. We’d never met him so we had no reason to think it wasn’t him.","cn":"他派了一个朋友来欺骗我们，而不是亲自来。我们从未见过他，所以我们没有理由认为那不是他。"},"pos":"verb"}]}},"housekeeping":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"料理家务;家政管理","en":"Housekeeping is the work and organization involved in running a home, including the shopping and cleaning.","ex":{"en":"I thought that cooking and housekeeping were unimportant, easy tasks.","cn":"我认为做饭和料理家务微不足道，一下子就能搞定。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（旅馆的）客房勤杂","en":"Housekeeping is the part of the organization of a hotel which deals with keeping the rooms clean and properly equipped."},{"pos":"N-UNCOUNT 不可数名词","cn":"家务开支;家用钱","en":"Housekeeping is the money that you use to buy food, cleaning materials, and other things that you need in your home.","ex":{"en":"...the housekeeping money Jim gave her each week.","cn":"吉姆每周给她的家用钱"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the work and organization of things that need to be done in a house, hotel etc, for example cooking and buying food","cn":"家务﹔后勤"},{"en":"an amount of money that is kept and used to pay for food and other things needed in the home","cn":"家务开支﹐家用钱"},{"en":"jobs that need to be done to keep a system working properly 〔","cn":"维持某个系统正常运转的〕内务工作"}]},"collocations":{"phrases":["ADJ. careful, good, prudent The company has made considerable savings through good housekeeping, such as avoiding wastage. | bad, poor My fi","HOUSEKEEPING + NOUN allowance, money Her husband spent the housekeeping money on gambling."]},"media":{"uk":"media/ldoce/hwd/bre/3/housekeeping0205.mp3","us":"media/ldoce/hwd/ame/9/housekeeping.mp3"},"examples":[{"en":"Call housekeeping and ask them to bring us some clean towels.","cn":"给总务处打电话，让他们给我们送些干净的毛巾来。"},{"en":"Most large companies now use computers for accounting and housekeeping operations.","cn":"多数大公司现在用计算机进行会计运算和内务操作。"}],"oxford":{"phon":"ˈhaʊskiːpɪŋ","pos":"noun","senses":[{"en":"the work involved in taking care of a house, especially shopping and managing money","cn":"家务（尤指采购和管理开支）","ex":{"en":"My financial problems were made worse by my bad housekeeping.","cn":"我持家无方，使得经济状况更加糟糕。"}},{"en":"the department in a hotel, a hospital, an office building, etc. that is responsible for cleaning the rooms, etc.","cn":"（旅馆、医院、写字楼等的）总务处，后勤部","ex":{"en":"Call housekeeping and ask them to bring us some clean towels.","cn":"给总务处打电话，让他们给我们送些干净的毛巾来。"}},{"en":"the money used to buy food, cleaning materials and other things needed for taking care of a house","cn":"家务开支","lab":"especially in British English"},{"en":"jobs that are done to enable an organization or computer system to work well","cn":"内务处理","ex":{"en":"The company has made considerable savings through good housekeeping, such as avoiding wastage.","cn":"公司通过如避免浪费等有效的内部管理方法节约了数量可观的资金。"}}]}},"horrific":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（攻击、事故、伤势等）令人震惊的，极其可怕的，十分严重的","en":"If you describe a physical attack, accident, or injury as horrific, you mean that it is very bad, so that people are shocked when they see it or think about it.","ex":{"en":"I have never seen such horrific injuries","cn":"我从来没有见过如此严重的伤势。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大得令人厌恶的","en":"If you describe something as horrific, you mean that it is so big that it is extremely unpleasant.","ex":{"en":"...piling up horrific extra amounts of money on top of your original debt.","cn":"在你原来债务的基础上又高筑债台"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not at all pleasant, enjoyable, or successful","cn":""},{"en":"very bad","cn":""},{"en":"so bad that you are shocked","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something horrific causes horror. It’s disastrous and makes you shudder with fear. Yikes!"}]},"collocations":{"phrases":["VERBS be, look | describe sth as Police described the attack as horrific.","ADV. really | absolutely, quite, truly Some of the scenes we witnessed were quite horrific. | fairly, pretty"]},"media":{"uk":"media/ldoce/hwd/bre/7/horrific0205.mp3","us":"media/ldoce/hwd/ame/3/horrific.mp3"},"examples":[{"en":"a horrific murder/accident/attack, etc.","cn":"骇人听闻的谋杀、事故、攻击等"},{"en":"We had a horrific trip.","cn":"我们的旅行糟糕透顶。"}],"oxford":{"phon":"həˈrɪfɪk","pos":"adjective","senses":[{"en":"extremely bad and making you feel shocked or frightened","cn":"极坏的；令人震惊的；令人惊恐的","ex":{"en":"a horrific murder/accident/attack, etc.","cn":"骇人听闻的谋杀、事故、攻击等"}},{"en":"very bad or unpleasant","cn":"极差的；很不愉快的","lab":"informal","ex":{"en":"We had a horrific trip.","cn":"我们的旅行糟糕透顶。"}}]}},"honeymoon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（新婚夫妇的）蜜月","en":"A honeymoon is a holiday taken by a man and a woman who have just got married."},{"pos":"VERB 动词","cn":"度蜜月","en":"When a recently-married couple honeymoon somewhere, they go there on their honeymoon.","ex":{"en":"They honeymooned in Venice.","cn":"他们在威尼斯度了蜜月。"}},{"pos":"N-COUNT 可数名词","cn":"（新工作开始或新政府成立后的）和谐时期，蜜月期","en":"You can use honeymoon to refer to a period of time after the start of a new job or new government when everyone is pleased with the person or people concerned and is nice to them.","ex":{"en":"Austrians voted for EU membership by a two-to-one majority in a June 1994 referendum, but the honeymoon is definitely over","cn":"奥地利在1994年6月举行的全民公决中以2比1的多数票支持加入欧盟，但这一蜜月期明显已经结束了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ceremony in which two people get married, especially one with a religious service","cn":""},{"en":"a wedding. Marriage is less common and more formal than wedding","cn":""},{"en":"a large formal meal or party after a wedding","cn":""}]},"collocations":{"phrases":["ADJ. brief, short We had a brief honeymoon in Paris. | long | second After so many years of marriage, we're planning a second honeymoon.","VERB + HONEYMOON go on, have, leave for, spend They go on honeymoon the day after the wedding.","HONEYMOON + VERB be over (usually figurative) The honeymoon was over and the reality of what she had taken on began to dawn.","HONEYMOON + NOUN couple | suite | period (figurative) There was always a honeymoon period when Mum started a new job.","PREP. for a ~ They can't decide where to go for their honeymoon. | on ~ While on honeymoon in Bali, she learned to scuba dive."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdehoneymoon.mp3","us":"media/ldoce/hwd/ame/d/honeymoon1.mp3"},"examples":[{"en":"The honeymoon period for the government is now over.","cn":"这届政府的蜜月期现在已经过去了。"},{"en":"We went to Venice for our honeymoon.","cn":"我们去了威尼斯度蜜月。"}],"oxford":{"phon":"ˈhʌnimuːn","pos":"noun","senses":[{"en":"a holiday taken by a couple who have just got married","cn":"蜜月","ex":{"en":"We went to Venice for our honeymoon.","cn":"我们去威尼斯度的蜜月。"}},{"en":"the period of time at the start of a new activity when nobody is criticized and people feel enthusiastic","cn":"（新活动之初的）和谐时期","ex":{"en":"The honeymoon period for the government is now over.","cn":"这届政府的蜜月期现在已经过去了。"}},{"en":"to spend your honeymoon somewhere","cn":"（去某处）度蜜月","ex":{"en":"They are honeymooning in Paris.","cn":"他们正在巴黎度蜜月。"},"pos":"verb"}]}},"hostage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人质","en":"A hostage is someone who has been captured by a person or organization and who may be killed or injured if people do not do what that person or organization demands.","ex":{"en":"It is hopeful that two hostages will be freed in the next few days.","cn":"有两名人质可望在几天后获释。"}},{"pos":"PHRASE 短语","cn":"被扣作人质","en":"If someone is taken hostage or is held hostage, they are captured and kept as a hostage.","ex":{"en":"He was taken hostage while on his first foreign assignment as a television journalist.","cn":"他第一次作为电视记者出国采访时就被扣作人质。"}},{"pos":"N-VAR 可变名词","cn":"受限制的人;不由自主的人","en":"If you say you are hostage to something, you mean that your freedom to take action is restricted by things that you cannot control.","ex":{"en":"With the reduction in foreign investments, the government will be even more a hostage to the whims of the international oil price","cn":"随着外资的减少，政府将更加受制于起伏不定的国际油价。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is kept in a prison as a punishment for a crime, or while they are waiting for their trial","cn":""},{"en":"someone who has been found guilty of a crime and sent to a prison. Convict is used especially about someone who is sent to prison for a long time. It is more commonly used in historical descriptions, or in the phrase an escaped convict","cn":""},{"en":"someone who is kept in a prison or a mental hospital","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A hostage is a prisoner taken by kidnappers and held until the kidnappers get whatever they’re asking for. If you refuse to empty the litter box, your roommate might take your cat as a hostage until you clean it."}]},"collocations":{"phrases":["VERB + HOSTAGE hold (sb) Eight people were held hostage for four months. | seize, take (sb) The gunmen took 24 hostages. | free, release, se"]},"media":{"uk":"media/ldoce/hwd/bre/e/hostage0205.mp3","us":"media/ldoce/hwd/ame/8/hostage.mp3"},"examples":[{"en":"Three children were taken hostage during the bank robbery.","cn":"在银行抢劫案中有三名儿童被扣为人质。"},{"en":"The government is negotiating the release of the hostages.","cn":"政府正就释放人质进行谈判。"}],"oxford":{"phon":"ˈhɒstɪdʒ","pos":"noun","senses":[{"en":"a person who is captured and held prisoner by a person or group, and who may be injured or killed if people do not do what the person or group is asking","cn":"人质","ex":{"en":"Three children were taken hostage during the bank robbery.","cn":"在银行抢劫案中有三名儿童被扣为人质。"}}]}},"horace":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"(65–8 BC) a Roman poet and writer of satire (= literature making fun of stupid or evil people ) , whose work greatly influenced English poetry. His full Latin name was Quintus Horatius Flaccus.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/p028-000006209.mp3","us":"media/ldoce/hwd/ame/9/p028-000006209.mp3"},"oxford":{"phon":"ˈhɒrəs","pos":"","senses":[{"en":"a first name for boys","cn":"贺拉斯（男子名）"}]}},"homeland":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"祖国","en":"Your homeland is your native country.","ex":{"en":"Many are planning to return to their homeland.","cn":"很多人正计划回到自己的祖国去。"}},{"pos":"N-COUNT 可数名词","cn":"“黑人家园”（指过去南非种族隔离制度下的黑人有一定自治权的地区）","en":"The homelands were regions within South Africa in which black South Africans had a limited form of self-government."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the country where someone was born","cn":"祖国﹐家乡"},{"en":"a large area of land where a particular group of people can live 〔","cn":"某一群人的〕定居点﹐聚居地"}]},"collocations":{"phrases":["ADJ. beloved They were devastated that they had to leave their beloved homeland. | ancient, traditional the struggle to defend their ancient","VERB + HOMELAND flee, leave During the war, they were forced to flee their homeland. | go back to, return to, visit He longs to return to hi","PREP. in a/sb's ~ They hope to remain in their homeland."]},"media":{"uk":"media/ldoce/hwd/bre/f/homeland0205.mp3","us":"media/ldoce/hwd/ame/2/homeland.mp3"},"examples":[{"en":"Many refugees have been forced to flee their homeland.","cn":"很多难民被迫逃离了祖国。"},{"en":"the Transkei homeland","cn":"特兰斯凯黑人定居地"}],"oxford":{"phon":"ˈhəʊmlænd","pos":"noun","senses":[{"en":"the country where a person was born","cn":"祖国；家乡","g":"[usually singular]","ex":{"en":"Many refugees have been forced to flee their homeland.","cn":"很多难民被迫逃离了祖国。"}},{"en":"(in the Republic of South Africa under the apartheid system in the past) one of the areas with some self-government that were intended for a group of black African people to live in","cn":"（南非共和国过去在种族隔离制度下设立、有一定自治权的）黑人定居地","ex":{"en":"the Transkei homeland","cn":"特兰斯凯黑人定居地"}}]}},"holder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拥有人;持有人","en":"A holder is someone who owns or has something.","ex":{"en":"This season the club has had 73,500 season-ticket holders.","cn":"本赛季该俱乐部已经有73,500名持有季票的观众。"}},{"pos":"N-COUNT 可数名词","cn":"盛放器;支托物","en":"A holder is a container in which you put an object, usually in order to protect it or to keep it in place.","ex":{"en":"...a toothbrush holder.","cn":"牙刷托"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who owns or controls something","cn":"拥有人﹐持有人"},{"en":"something that is used to hold an object","cn":"支托物"}]},"collocations":{"phrases":["ADJ. licence, passport, ticket Only ticket holders will be allowed into the ground. | account, credit card, policy Account holders with the "]},"media":{"uk":"media/ldoce/hwd/bre/1/holder0205.mp3","us":"media/ldoce/hwd/ame/7/l3holder.mp3"},"examples":[{"en":"the current holder of the world record","cn":"目前的世界纪录保持者"},{"en":"the holder of a French passport","cn":"持有法国护照者"}],"oxford":{"phon":"ˈhəʊldə(r)","pos":"noun","senses":[{"en":"a person who has or owns the thing mentioned","cn":"持有者；拥有者","ex":{"en":"a licence holder","cn":"执照持有人"}},{"en":"a thing that holds the object mentioned","cn":"支托（或握持）…之物","ex":{"en":"a pen holder","cn":"笔筒"}}]}},"homosexual":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同性恋的;同性性欲的","en":"A homosexual relationship is a sexual relationship between people of the same sex."},{"pos":"ADJ 形容词","cn":"（人）同性恋性向的","en":"Someone who is homosexual is sexually attracted to people of the same sex.","ex":{"en":"A fraud trial involving two homosexual lawyers was abandoned.","cn":"一桩涉及两名同性恋律师的欺诈案审判被撤销了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sexually attracted to people of the same sex","cn":""},{"en":"a woman who is sexually attracted to other women","cn":""},{"en":"sexually attracted to people of the same sex","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Homosexual is a noun and adjective. Either way, it has to do with people who are attracted to members of the same sex."}]},"collocations":{"phrases":["ADJ. practising | closet, repressed | female, male","VERB + HOMOSEXUAL come out as He came out as a homosexual after his mother died.","HOMOSEXUAL + VERB come out of the closet","PHRASES discrimination against homosexuals"]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41homosexual.mp3","us":"media/ldoce/hwd/ame/b/homosexual.mp3"},"examples":[{"en":"a practising homosexual","cn":"有同性恋行为的人"},{"en":"a homosexual act/relationship","cn":"同性恋行为/关系"}],"oxford":{"phon":"ˌhəʊməˈsekʃuəl","pos":"adjective","senses":[{"en":"sexually attracted to people of the same sex; showing this","cn":"同性恋者（通常指男性）","ex":{"en":"a homosexual act/relationship","cn":"同性恋行为／关系"}},{"en":"a person, usually a man, who is sexually attracted to people of the same sex","cn":"同性恋者（通常指男性）","ex":{"en":"He came out as a homosexual after his mother died.","cn":"他在母亲死后公开承认自己是同性恋者。"},"pos":"noun"}]}},"horrible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讨厌的;糟透的","en":"If you describe something or someone as horrible, you do not like them at all.","ex":{"en":"The record sounds horrible.","cn":"唱片难听极了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人震惊的;使人恐惧的;让人极度反感的","en":"You can call something horrible when it causes you to feel great shock, fear, and disgust.","ex":{"en":"Still the horrible shrieking came out of his mouth.","cn":"他的嘴里还是发出了恐怖的尖叫声。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极严重的","en":"Horrible is used to emphasize how bad something is.","ex":{"en":"That seems like a horrible mess that will drag on for years","cn":"看起来那像是个会拖延多年的大烂摊子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very bad and unpleasant","cn":"糟糕的﹐令人不快的"},{"en":"horrible, especially in a way that makes you feel slightly sick","cn":"恶心的﹐使人反感的"},{"en":"very unpleasant – often used about a taste that stays in your mouth 〔","cn":"常指口中的余味〕令人极为不快的"}]},"vocab":{"pos":"adj","senses":[{"en":"The difference between bad and horrible is like the difference between an unpleasant dream and an awful nightmare."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, smell, sound, taste","ADV. bloody (taboo) , really That was a really horrible thing to say! | absolutely, perfectly, quite, truly a truly horrible sight | pretty,","PREP. to My sister has always been horrible to me."]},"media":{"uk":"media/ldoce/hwd/bre/6/horrible0205.mp3","us":"media/ldoce/hwd/ame/b/horrible.mp3"},"examples":[{"en":"I've got a horrible feeling she lied to us.","cn":"我有种不快的感觉，觉得她对我们说了谎。"},{"en":"My sister was being horrible to me all day.","cn":"我姐姐一整天都对我很凶。"}],"oxford":{"phon":"ˈhɒrəbl","pos":"adjective","senses":[{"en":"very bad or unpleasant; used to describe something that you do not like","cn":"极坏的；十分讨厌的；可恶的","lab":"informal","ex":{"en":"What horrible weather!","cn":"这个鬼天气！"}},{"en":"making you feel very shocked and frightened","cn":"令人震惊的；恐怖的","ex":{"en":"a pretty horrible experience","cn":"非常可怕的经历"}},{"en":"unfriendly, unpleasant or unkind","cn":"不友善的；讨厌的；不厚道的","lab":"informal","ex":{"en":"a horrible person","cn":"讨厌鬼"}}]}},"honey":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"蜂蜜","en":"Honey is a sweet, sticky, yellowish substance that is made by bees."},{"pos":"N-VOC 称呼名词","cn":"(爱称）亲爱的，宝贝","en":"You call someone honey as a sign of affection.","ex":{"en":"Honey, I don't really think that's a good idea.","cn":"亲爱的，我不认为那是个好主意。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sweet sticky substance produced by bee s , used as food","cn":"蜂蜜"},{"en":"used to address someone you love","cn":"亲爱的﹐宝贝〔用于称呼心爱的人〕"},{"en":"an attractive woman","cn":"美女"}]},"collocations":{"phrases":["ADJ. clear | runny | wild","QUANT. dollop | jar, pot","VERB + HONEY make, produce learning how bees make honey a jar of locally-produced honey | gather to gather honey from the hive | spread (sth","HONEY + NOUN bee","PHRASES as sweet as honey •"]},"media":{"uk":"media/ldoce/hwd/bre/9/honey0205.mp3","us":"media/ldoce/hwd/ame/5/honey.mp3"},"examples":[{"en":"Have you seen my keys, honey?","cn":"你见到我的钥匙了吗，宝贝？"},{"en":"He can be a real honey when he wants to be.","cn":"他高兴的时候挺招人喜欢的。"}],"oxford":{"phon":"ˈhʌni","pos":"noun","senses":[{"en":"a sweet, sticky yellow-brown substance made by bees that is spread on bread, etc. like jam","cn":"蜂蜜","g":"[uncountable]","ex":{"en":"How do bees make honey?","cn":"蜜蜂如何酿蜜？"}},{"en":"a way of addressing somebody that you like or love","cn":"（爱称）亲爱的，宝贝儿","g":"[countable]","lab":"informal","ex":{"en":"Have you seen my keys, honey?","cn":"你见到我的钥匙了吗，宝贝？"}},{"en":"a person that you like or love and think is very kind","cn":"可爱的人","g":"[countable]","lab":"informal","ex":{"en":"He can be a real honey when he wants to be.","cn":"他高兴的时候挺招人喜欢的。"}}]}},"hopeful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)抱有希望的，满怀希望的","en":"If you are hopeful, you are fairly confident that something that you want to happen will happen.","ex":{"en":"I am hopeful this misunderstanding will be rectified very quickly","cn":"我相信这个误会将很快得到纠正。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（征兆、事件等）给人以希望的","en":"If something such as a sign or event is hopeful, it makes you feel that what you want to happen will happen.","ex":{"en":"The result of the election in is yet another hopeful sign that peace could come to the Middle East.","cn":"已出炉的选举结果再次显示在中东实现和平是有希望的。"}},{"pos":"ADJ 形容词","cn":"（行动）被寄予希望的","en":"A hopeful action is one that you do in the hope that you will get what you want to get.","ex":{"en":"We've chartered the aircraft in the hopeful anticipation that the government will allow them to leave.","cn":"我们已经包租了那架飞机，希望政府会对他们放行。"}},{"pos":"N-COUNT 可数名词","cn":"希望获得成功的人","en":"If you refer to someone as a hopeful, you mean that they are hoping and trying to achieve success in a particular career, election, or competition.","ex":{"en":"His soccer skills continue to be put to good use in his job as football coach to young hopefuls.","cn":"他的球技在他给这些希望成为明日之星的年轻人担任教练的过程中继续发挥出很大作用。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"believing that good things will happen","cn":""},{"en":"believing that what you hope for will happen","cn":""},{"en":"thinking about what is good in a situation, rather than what is bad","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"If you're hopeful about something, you're optimistic. You think it's going to turn out OK. Your team has been doing well in practice, so you're hopeful that you'll win the finals."}]},"collocations":{"phrases":["VERBS be, feel, seem, sound I feel quite hopeful that a peaceful solution will be found. | become, get Don't get too hopeful. We may not be ","ADV. extremely, very | almost | fairly, pretty, quite | eternally Only Janet, eternally hopeful, thought it was worth trying again.","PREP. about She was not very hopeful about her situation. | of The police are quite hopeful of catching the thieves. 2 making you think that","VERBS be, look, seem Things aren't looking very hopeful at the moment.","ADV. extremely, very | fairly, quite There are some fairly hopeful signs of recovery in the US market."]},"media":{"uk":"media/ldoce/hwd/bre/7/hopeful_n0205.mp3","us":"media/ldoce/hwd/ame/2/hopeful1.mp3"},"examples":[{"en":"50 young hopefuls are trying for a place in the England team. * 50","cn":"名雄心勃勃的年轻人亟欲跻身英格兰队。"},{"en":"I feel hopeful that we'll find a suitable house very soon.","cn":"我对很快找到合适的房子抱有希望。"}],"oxford":{"phon":"ˈhəʊpfl","pos":"adjective","senses":[{"en":"believing that something you want will happen","cn":"抱有希望；满怀希望","g":"[not usually before noun]","lab":"British English","ex":{"en":"I feel hopeful that we'll find a suitable house very soon.","cn":"我对很快找到合适的房子抱有希望。"}},{"en":"showing hope","cn":"表现出希望的","g":"[only before noun]","ex":{"en":"a hopeful smile","cn":"充满希望的微笑"}},{"en":"making you believe that something you want will happen; bringing hope","cn":"给人以希望的","ex":{"en":"The latest trade figures are a hopeful sign.","cn":"最新贸易数字令人鼓舞。"}},{"en":"a person who wants to succeed at something","cn":"希望成功的人；雄心勃勃的人","ex":{"en":"50 young hopefuls are trying for a place in the England team.","cn":"50 名雄心勃勃的年轻人亟欲跻身英格兰队。"},"pos":"noun"}]}}});
